def test_strict_mcp_config_present_in_both_failover_respawn_attempts(
        agentctl, tmp_path, monkeypatch):
    """ARCH-131 fail-over respawns through `_respawn_in_place`, which calls the
    SAME `_spawn_claude` closure as the first attempt, so a source-level guard
    on `_spawn_claude` alone cannot tell whether the respawned argv is built
    by a path that skipped it. Driving a real fail-over end to end, and
    inspecting BOTH invocations' argv, is what shows
    `--strict-mcp-config` (now unconditional, issue_01M4APS4KRPE6ESTZAVEJVFDKC)
    reaches the respawn too, not only the first attempt.

    The first (Anthropic) attempt exits 1; only `--model deepseek` succeeds,
    forcing a real second spawn rather than a single-call run."""
    import shlex
    import types

    run_dir = tmp_path / "run-fbtest-mcp"
    run_dir.mkdir()
    worktree = tmp_path / "wt-fbtest-mcp"
    worktree.mkdir()
    argv_dir = tmp_path / "argvs"
    argv_dir.mkdir()
    counter = tmp_path / "count"
    stub = tmp_path / "claude-stub-fb"
    stub.write_text(
        "#!/bin/sh\n"
        f"n_file={shlex.quote(str(counter))}\n"
        'n=0; [ -f "$n_file" ] && n=$(cat "$n_file")\n'
        'n=$((n + 1))\n'
        'echo "$n" > "$n_file"\n'
        f"printf '%s\\n' \"$@\" > {shlex.quote(str(argv_dir))}/argv-$n.txt\n"
        'model=""; prev=""\n'
        'for a in "$@"; do if [ "$prev" = "--model" ]; then model="$a"; fi; prev="$a"; done\n'
        'if [ "$model" = "deepseek" ]; then\n'
        "  printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"deepseek\"}'\n"
        "  exit 0\n"
        "fi\n"
        "exit 1\n"
    )
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "scheduled")

    args = types.SimpleNamespace(agent="bug-investigator", task="t",
                                 parent=None, dry_run=False, label=None)
    agent_def = {"body": "sys", "model_alias": "opus",
                 "frontmatter": {"model": "opus", "model_floor": "deepseek"}}
    rc = agentctl._run_session(
        args=args, agent=agent_def, run_id="run-fbtest-mcp", run_dir=run_dir,
        worktree=worktree, profile="p", repo="agent-platform",
        started_at="2026-06-11T00:00:00Z", user_prompt="u")
    assert rc == 0, "the deepseek respawn must have succeeded"
    argv_files = sorted(argv_dir.iterdir())
    assert len(argv_files) == 2, (
        f"expected exactly two claude invocations (first attempt + one "
        f"fail-over respawn), got {len(argv_files)}")
    for f in argv_files:
        argv = f.read_text().splitlines()
        assert "--strict-mcp-config" in argv, (
            f"{f.name}: --strict-mcp-config missing from a non-private dispatch's argv")
        assert "--mcp-config" in argv, (
            f"{f.name}: --mcp-config (kb/ops) missing from a non-private dispatch's argv")


def _run_fleet_decision_respawn(agentctl, tmp_path, monkeypatch, *, name: str,
                                claude_md_before: str, first_attempt_shell: str,
                                materialized_documents):
    """Drive a real ARCH-131 fail-over respawn (same shape as
    `test_strict_mcp_config_present_in_both_failover_respawn_attempts`) and
    capture BOTH spawns' `--settings` so a caller can assert the fleet
    decision (`claudeMdExcludes`) is identical across them. `first_attempt_shell`
    runs inside the stub's Anthropic attempt, before it exits 1 — the dying
    subprocess's own chance to rewrite the worktree's `.claude/CLAUDE.md`
    before the respawn's `_spawn_claude` call runs."""
    import shlex
    import types

    run_dir = tmp_path / f"run-{name}"
    run_dir.mkdir()
    worktree = tmp_path / f"wt-{name}"
    worktree.mkdir()
    claude_dir = worktree / ".claude"
    claude_dir.mkdir()
    claude_md = claude_dir / "CLAUDE.md"
    claude_md.write_text(claude_md_before)
    argv_dir = tmp_path / f"argvs-{name}"
    argv_dir.mkdir()
    counter = tmp_path / f"count-{name}"
    stub = tmp_path / f"claude-stub-{name}"
    stub.write_text(
        "#!/bin/sh\n"
        f"n_file={shlex.quote(str(counter))}\n"
        'n=0; [ -f "$n_file" ] && n=$(cat "$n_file")\n'
        'n=$((n + 1))\n'
        'echo "$n" > "$n_file"\n'
        f"printf '%s\\n' \"$@\" > {shlex.quote(str(argv_dir))}/argv-$n.txt\n"
        'model=""; prev=""\n'
        'for a in "$@"; do if [ "$prev" = "--model" ]; then model="$a"; fi; prev="$a"; done\n'
        'if [ "$model" = "deepseek" ]; then\n'
        "  printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"deepseek\"}'\n"
        "  exit 0\n"
        "fi\n"
        f"{first_attempt_shell}\n"
        "exit 1\n"
    )
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "scheduled")

    args = types.SimpleNamespace(agent="bug-investigator", task="t",
                                 parent=None, dry_run=False, label=None)
    agent_def = {"body": "sys", "model_alias": "opus",
                 "frontmatter": {"model": "opus", "model_floor": "deepseek"}}
    rc = agentctl._run_session(
        args=args, agent=agent_def, run_id=f"run-{name}", run_dir=run_dir,
        worktree=worktree, profile="p", repo="agent-platform",
        started_at="2026-06-11T00:00:00Z", user_prompt="u",
        docs_unavailable_reason=None,
        materialized_documents=materialized_documents)
    assert rc == 0, "the deepseek respawn must have succeeded"
    argv_files = sorted(argv_dir.iterdir())
    assert len(argv_files) == 2, (
        f"expected exactly two claude invocations (first attempt + one "
        f"fail-over respawn), got {len(argv_files)}")
    excludes = []
    for f in argv_files:
        argv = f.read_text().splitlines()
        settings = json.loads(argv[argv.index("--settings") + 1])
        excludes.append(settings["claudeMdExcludes"])
    return excludes


_FLEET_ID = "platform/instruction-blocks/no-agent-merges"
_FLEET_HASH = "f" * 64
_FLEET_MARKER = (f"<!-- instruction-block: {_FLEET_ID} scope:fleet "
                 f"body_sha256:{_FLEET_HASH} -->\nbody\n")
_FLEET_ROW = {"id": _FLEET_ID, "kind": "instruction-block",
             "body_sha256": _FLEET_HASH, "scope": "fleet"}


def test_a_respawn_keeps_declining_even_after_claude_md_gains_the_fleet_marker(
        agentctl, tmp_path, monkeypatch):
    """Round 3 finding (reviewer, PR #823): `_fleet_blocks_confirmed_in_claude_md`
    used to run inside `_spawn_claude` and re-read the worktree's own
    `.claude/CLAUDE.md` on every ARCH-131 fail-over respawn — after the first
    attempt's subprocess, which had just died, had full write access to that
    same file for its whole turn. The decision is now taken exactly once,
    before any subprocess of this dispatch exists, and reused by the respawn.

    No marker is on disk when the first spawn's decision is taken, so it
    must decline. The dying first attempt then writes the recorded fleet
    block's marker into CLAUDE.md before it exits — the one case where a
    recomputing check would flip from "decline" to "confirmed" on the
    respawn. Checked against the unfixed code at 76dfd5be: there, the
    respawn's `--settings` carries a non-empty `claudeMdExcludes`, because
    `_spawn_claude` re-read the now-marked file; this assertion failed."""
    write_marker = (f"cat > .claude/CLAUDE.md <<'MARKER_EOF'\n{_FLEET_MARKER}MARKER_EOF")
    excludes = _run_fleet_decision_respawn(
        agentctl, tmp_path, monkeypatch,
        name="fleet-add", claude_md_before="",
        first_attempt_shell=write_marker,
        materialized_documents=[_FLEET_ROW])
    assert excludes == [[], []], (
        "both spawns must keep loading the user CLAUDE.md — the decision was "
        "taken before the marker existed and must not be recomputed")


def test_a_respawn_keeps_excluding_even_after_claude_md_loses_the_fleet_marker(
        agentctl, tmp_path, monkeypatch):
    """The opposite direction of the test above. The marker is on disk, and
    `materialized_documents` confirms it, when the first spawn's decision is
    taken — it must exclude the user CLAUDE.md. The dying first attempt then
    deletes CLAUDE.md before it exits; a recomputing check would flip from
    "confirmed" to "decline" on the respawn. Checked against the unfixed code
    at 76dfd5be: there, the respawn's `--settings` carries an EMPTY
    `claudeMdExcludes`, because `_spawn_claude` re-read the now-empty file;
    this assertion failed."""
    excludes = _run_fleet_decision_respawn(
        agentctl, tmp_path, monkeypatch,
        name="fleet-remove", claude_md_before=_FLEET_MARKER,
        first_attempt_shell="rm -f .claude/CLAUDE.md",
        materialized_documents=[_FLEET_ROW])
    assert excludes[0] != [] and excludes[1] != [], (
        "both spawns must exclude the user CLAUDE.md — the decision was "
        "taken while the marker was still present and must not be recomputed")


