def test_activate_profile_records_profile_documents_current_when_signaled(
        agentctl, tmp_path, monkeypatch):
    """Security review, PR #740 round 4: `_spawn_dispatch` must be able to
    tell "this call's `.profile-documents.json` is current" from "this call
    ran" — `loaded["profile_documents_current"]` is how. A real write or a
    verified no-op both carry knowledge-ctx's signal.

    Round 5: that signal travels on the dedicated pipe fd `activate_profile`
    opens and passes via `--profile-documents-current-fd`, not a stderr
    marker — pinned against a stub that writes to the passed fd the way the
    real binary does (`kwargs["pass_fds"]`), not against captured stdout/
    stderr, which this stub leaves carrying nothing of the kind on purpose."""
    def fake_run(cmd, **kwargs):
        (write_fd,) = kwargs["pass_fds"]
        os.write(write_fd, agentctl._PROFILE_DOCUMENTS_CURRENT_PAYLOAD)
        class _R:
            returncode = 0
            stdout = "profile: company/commercial\nwrote 3 files.\n"
            stderr = ""
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    monkeypatch.setattr(agentctl, "_ancestor_pids", lambda: [])

    loaded: dict = {}
    agentctl.activate_profile(tmp_path, "company/commercial", loaded=loaded)
    assert loaded["profile_documents_current"] is True


def test_activate_profile_records_profile_documents_current_false_on_a_dry_run(
        agentctl, tmp_path, monkeypatch):
    """The real `knowledge-ctx use --dry-run` behavior: exit 0, nothing ever
    written to the pipe fd, because it returned before writing or checking
    anything. The stub here never touches `kwargs["pass_fds"]` at all,
    pinning that a dispatch reading an untouched pipe (not an explicit
    false-shaped payload) must still land False — the fail-closed default, not
    something the stub has to assert into existence."""
    def fake_run(cmd, **kwargs):
        class _R:
            returncode = 0
            stdout = ("profile: company/commercial\n"
                       "\n(dry-run — no files written.)\n")
            stderr = ""
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    monkeypatch.setattr(agentctl, "_ancestor_pids", lambda: [])

    loaded: dict = {}
    agentctl.activate_profile(tmp_path, "company/commercial", dry_run=True, loaded=loaded)
    assert loaded["profile_documents_current"] is False


def test_cmd_spawn_records_a_blocked_claude_md_write_on_the_run(agentctl):
    """`activate_profile` runs BEFORE `cmd_spawn` creates `run_dir`
    (`T.create_run_dir` follows the call, not the reverse), and
    `T.update_meta` requires `meta.json` already on disk — so the recording
    can only happen after each of `cmd_spawn`'s own two `write_meta` calls
    (the dry-run branch and the real-spawn branch), not once, shared, right
    after `run_dir` is created. Pinned on source because exercising this
    live would mean driving the whole of `cmd_spawn` (worktree allocation,
    the budget gate, model resolution) just to reach one `update_meta` call —
    the two write_meta call sites are what this test protects.
    """
    src = Path(agentctl.__file__).read_text()
    assert "claude_md_blocked = None" in src, (
        "cmd_spawn must default claude_md_blocked so both write_meta branches "
        "can read it whether or not activate_profile ran")
    assert "claude_md_blocked = activate_profile(worktree, profile" in src, (
        "cmd_spawn must capture activate_profile's return value")
    record_snippet = (
        "if claude_md_blocked is not None:\n"
        "            T.update_meta(run_dir, claude_md_blocked_path=claude_md_blocked[0],\n"
        "                          claude_md_blocked_reason=claude_md_blocked[1])"
    )
    assert src.count(record_snippet) == 2, (
        "expected the blocked-write recording right after EACH of cmd_spawn's "
        "two write_meta calls (dry-run and real spawn); found "
        f"{src.count(record_snippet)}")


def test_cmd_status_shows_a_blocked_claude_md_write(agentctl, tmp_path, monkeypatch, capsys):
    """`agentctl status <run-id>` is the orchestrator's window into a dispatch
    it cannot otherwise be notified about (`agentctl spawn` `setsid`s the run
    out of the caller's process tree) — so a blocked composed-instruction
    delivery recorded on the run must show up here, the same way a refused
    model fail-over already does via `fallback_blocked_to`."""
    from types import SimpleNamespace
    run_dirs_root = tmp_path / "agent-runs"
    day = run_dirs_root / "2026-09-22"
    monkeypatch.setattr(agentctl, "RUNS_ROOT", run_dirs_root)

    def make_run(rid, *, meta_extra=None):
        rd = day / rid
        rd.mkdir(parents=True)
        meta = {"run_id": rid, "agent": "coder", "task": "t", "repo": "agent-platform",
                "worktree": "/wt", "profile": "p", "model": "m",
                "started_at": "2026-09-22T00:00:00Z", "pid": 999999}
        meta.update(meta_extra or {})
        (rd / "meta.json").write_text(json.dumps(meta))

    make_run("run-blocked", meta_extra={
        "claude_md_blocked_path": "/wt/.claude/CLAUDE.md",
        "claude_md_blocked_reason": "not listed in the previous individuation manifest",
    })
    agentctl.cmd_status(SimpleNamespace(run_id="run-blocked"))
    out = capsys.readouterr().out
    assert "NOT DELIVERED" in out
    assert "/wt/.claude/CLAUDE.md" in out
    assert "not listed in the previous individuation manifest" in out

    make_run("run-clean")
    agentctl.cmd_status(SimpleNamespace(run_id="run-clean"))
    out = capsys.readouterr().out
    assert "NOT DELIVERED" not in out
    assert "claude_md:" not in out


