# --- the two gates that decide whether _refuse_open_pr_reuse asks gh at all -
# (item 2 on PR #710: the guard used to ask gh, hardcoded to `convivy/<repo>`,
# on EVERY non-`--pr` write-class dispatch — a gh outage refused brand-new
# work, and a repo with no GitHub remote at all was refused outright.)

def _setup_bare_primary(agentctl, monkeypatch, tmp_path, *, origin_url=None):
    """A `CONVIVY_ROOT/demo` primary with one commit, optionally with `origin`
    set to `origin_url` (any string `git remote add` accepts — never
    dereferenced, since `_repo_github_slug` only reads the configured URL)."""
    for k, v in {"GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@example.com",
                 "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@example.com",
                 "GIT_CONFIG_GLOBAL": os.devnull, "GIT_CONFIG_NOSYSTEM": "1"}.items():
        monkeypatch.setenv(k, v)
    root = tmp_path / "root"
    primary = root / "demo"
    primary.mkdir(parents=True)
    _git_ok(primary, "init", "-q", "-b", "main")
    (primary / "README.md").write_text("one\n")
    _git_ok(primary, "add", "-A")
    _git_ok(primary, "commit", "-q", "-m", "one")
    if origin_url is not None:
        _git_ok(primary, "remote", "add", "origin", origin_url)
    monkeypatch.setattr(agentctl.W, "CONVIVY_ROOT", root)
    return primary


def test_repo_github_slug_is_none_with_no_origin(agentctl, monkeypatch, tmp_path):
    _setup_bare_primary(agentctl, monkeypatch, tmp_path, origin_url=None)
    assert agentctl._repo_github_slug("demo") is None


def test_repo_github_slug_is_none_for_a_non_github_origin(agentctl, monkeypatch, tmp_path):
    """A non-GitHub remote (a local path, a self-hosted git server) cannot
    have a GitHub PR — allow rather than mis-query github.com."""
    _setup_bare_primary(agentctl, monkeypatch, tmp_path,
                        origin_url=str(tmp_path / "remote.git"))
    assert agentctl._repo_github_slug("demo") is None


@pytest.mark.parametrize("origin_url,slug", [
    ("https://github.com/other-owner/other-repo.git", "other-owner/other-repo"),
    ("https://github.com/other-owner/other-repo", "other-owner/other-repo"),
    ("git@github.com:other-owner/other-repo.git", "other-owner/other-repo"),
    ("ssh://git@github.com/other-owner/other-repo.git", "other-owner/other-repo"),
])
def test_repo_github_slug_reads_the_owner_from_origin(agentctl, monkeypatch, tmp_path,
                                                       origin_url, slug):
    """The owner/repo comes from the repo's own `origin`, not a hardcoded
    `convivy/` — a fork or a differently-owned remote is asked correctly."""
    _setup_bare_primary(agentctl, monkeypatch, tmp_path, origin_url=origin_url)
    assert agentctl._repo_github_slug("demo") == slug


def test_repo_github_slug_is_none_for_an_unresolvable_repo(agentctl, monkeypatch, tmp_path):
    monkeypatch.setattr(agentctl.W, "CONVIVY_ROOT", tmp_path / "root")
    assert agentctl._repo_github_slug("no-such-repo") is None


