def _stub_branch_reachable_on_github(agentctl, monkeypatch, *, exists=True, slug="convivy/demo"):
    """`_refuse_open_pr_reuse` only asks gh once `_branch_may_already_exist` says
    the branch might already be claimed AND `_repo_github_slug` finds a GitHub
    remote to ask. These pure-decision tests stub both so they exercise the
    gh-consulting branch without touching a real filesystem or `origin`."""
    monkeypatch.setattr(agentctl, "_branch_may_already_exist", lambda *a, **k: exists)
    monkeypatch.setattr(agentctl, "_repo_github_slug", lambda repo: slug)


def test_refuse_open_pr_reuse_is_a_noop_for_a_review_agent(agentctl, monkeypatch):
    """Review branches' behaviour stays exactly as it is — the check must not
    even ask gh for a review-class agent."""
    _stub_branch_reachable_on_github(agentctl, monkeypatch)
    monkeypatch.setattr(agentctl, "_gh_open_pr_for_branch",
                        lambda *a, **k: pytest.fail("must not consult gh for a reviewer"))
    assert agentctl._refuse_open_pr_reuse("reviewer", "demo", "reviewer-x") is None
    assert agentctl._refuse_open_pr_reuse("hollis-reviewer", "demo", "reviewer-x") is None


