def test_cmd_spawn_refuses_model_changing_override_without_reason(agentctl, monkeypatch):
    """The actual CLI entry point a real caller hits: cmd_spawn's own preflight
    (model-lane epic issue_01KZH2GYGTVHFXZ055GEZVH2ZJ) must refuse a
    model-changing --model with no --reason BEFORE any worktree/run-dir side
    effect, not just inside _run_session's belt-and-suspenders re-check —
    reviewer finding on this epic's first PR (#416): every prior test drove
    _run_session directly, leaving this, the path production actually takes,
    untested."""
    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})

    def _unreached(*a, **kw):
        raise AssertionError("cmd_spawn must refuse before touching R.can_spawn "
                             "(i.e. before any worktree/run-dir side effect)")
    monkeypatch.setattr(agentctl.R, "can_spawn", _unreached)

    args = _cmd_spawn_args(model="opus", reason=None)
    assert agentctl.cmd_spawn(args) == 2


