_SLACK_READS = (
    "mcp__claude_ai_Slack__slack_read_channel",
    "mcp__claude_ai_Slack__slack_read_thread",
    "mcp__claude_ai_Slack__slack_get_reactions",
    "mcp__claude_ai_Slack__slack_search_public",
    "mcp__claude_ai_Slack__slack_read_user_profile",
    "mcp__claude_ai_Slack__slack_list_channel_members",
)


def _covered_by(tool, deny):
    return any(fnmatch.fnmatchcase(tool, pattern) for pattern in deny)


def test_slack_reads_are_denied_by_the_connector_class_unless_the_record_allows_slack(
        agentctl, monkeypatch):
    """Reads were left open on purpose, and that rule is retired. The Library's
    record lists `claude_ai_Slack` among its connector servers, so the wildcard
    denies every Slack tool, reads included, to every dispatch. The only grant is
    an explicit allow for Slack in the record (platform/decisions/0048). Each read
    is matched against the wildcard, so the test fails if the wildcard is gone."""
    import policy_client
    base = dict(_PUBLIC_CREW_RECORD, connector_servers=["claude_ai_Slack"])
    for agent in ("reviewer", "coder", "explainer", "planning-orchestrator"):
        monkeypatch.setattr(policy_client, "resolve", lambda a, c, m: dict(base))
        agentctl._LIBRARY_DENIALS_MEMO.clear()
        got = agentctl._disallowed_tools(agent, "agent-platform", model="claude-sonnet-5")
        for tool in _SLACK_READS:
            assert _covered_by(tool, got), f"{agent} may still read {tool}"
        monkeypatch.setattr(policy_client, "resolve",
                            lambda a, c, m: dict(base, explicit={"claude_ai_Slack": "allow"}))
        agentctl._LIBRARY_DENIALS_MEMO.clear()
        granted = agentctl._disallowed_tools(agent, "agent-platform", model="claude-sonnet-5")
        for tool in _SLACK_READS:
            assert not _covered_by(tool, granted), f"{agent} lost the Library's Slack grant"


