def test_disallowed_tools_applied_before_model_flag(agentctl):
    """ARCH-246 ordering guard (PR #59 review): --disallowedTools is greedy, so the
    deny list MUST be applied before --model in the spawn command — otherwise the
    model name + system prompt get silently swallowed as tool names. Lock the order
    at the source level (the closure isn't independently callable)."""
    import inspect
    src = inspect.getsource(agentctl._run_session)
    # The call carries `model=` since PR #487 — the Library keys policy by
    # agent/crew/MODEL, and the parameter existed unwired until then. It is the model
    # the spawn runs (`spawn_model`), so a fail-over respawn gets its own policy.
    # `eval_mode=` joined it for the review-replay eval harness (agent-platform#807):
    # the one call site that builds the real --disallowedTools flag needs to know
    # whether THIS dispatch is an eval replay, the same way it already needs to know
    # which model is about to run. Checked as two normalized-whitespace substrings
    # rather than one exact multi-line block, so reflowing the call doesn't make
    # this fail for a reason unrelated to what it guards.
    collapsed = " ".join(src.split())
    assert "_disallowed_tools(args.agent, repo, agent, model=spawn_model," in collapsed
    assert 'eval_mode=getattr(args, "eval_mode", False))' in collapsed
    i_deny = src.index('"--disallowedTools"')
    i_model = src.index('"--model"')
    assert i_deny < i_model, "--disallowedTools must precede --model in the command"


def test_every_claude_spawn_site_applies_the_deny_list(agentctl):
    """Every place this file starts a `claude -p` subprocess must apply the deny
    list — a second, hand-built spawn site (`agentctl scribe verify`, since
    removed) once bypassed `_run_session` entirely and was silently exempt from
    every deny, found by security review after it was caught keeping the Slack
    write tools every other agent had just lost.

    Pinned by counting CLAUDE_BIN spawn sites against `--disallowedTools` uses: if a
    second spawn site is ever added, this fails until it carries the deny too.
    """
    from pathlib import Path
    src = Path(agentctl.__file__).read_text()
    spawn_sites = src.count("CLAUDE_BIN, \"-p\"")
    deny_uses = src.count('"--disallowedTools"')
    assert spawn_sites == 1, (
        f"expected 1 claude spawn site, found {spawn_sites} — a new one must apply "
        "_disallowed_tools before --model, or it is exempt from every deny")
    assert deny_uses == spawn_sites, (
        f"{spawn_sites} claude spawn sites but only {deny_uses} apply --disallowedTools")


def test_every_claude_spawn_site_pins_thrifty_sonic(agentctl):
    """Same shape as test_every_claude_spawn_site_applies_the_deny_list, for the
    bash-first-steer pin (bin/co's matching comment has the full rationale):
    counts CLAUDE_BIN spawn sites against literal
    `"CLAUDE_CODE_THRIFTY_SONIC": "0"` env-dict entries, so a second spawn site
    added later — or an edit dropping the key from the existing one — fails this
    test instead of shipping green with nothing in CI checking it (reviewer
    finding, PR #505: the live-spawn guard in tests/test_claude_thrifty_sonic_pin.py
    skips unconditionally on CI's `convivy-linux` runner, which (not verified on
    ci1) has no `claude`
    binary on PATH)."""
    src = Path(agentctl.__file__).read_text()
    spawn_sites = src.count("CLAUDE_BIN, \"-p\"")
    pin_uses = src.count('"CLAUDE_CODE_THRIFTY_SONIC": "0"')
    assert spawn_sites == 1, (
        f"expected 1 claude spawn site, found {spawn_sites} — a new one must set "
        "CLAUDE_CODE_THRIFTY_SONIC=0 in its env dict, or the bash-first-steer pin "
        "silently doesn't apply there")
    assert pin_uses == spawn_sites, (
        f"{spawn_sites} claude spawn sites but only {pin_uses} set "
        "CLAUDE_CODE_THRIFTY_SONIC=0")


def test_thrifty_sonic_pin_reaches_run_session_subprocess_env(agentctl, tmp_path, monkeypatch):
    """The CI-visible half of the guard for the MAIN `claude -p` spawn site
    (`_run_session`): drives it against a stub `claude` that dumps its real
    environment to a file, and asserts CLAUDE_CODE_THRIFTY_SONIC=0 actually
    reaches the subprocess — not just that the literal string exists somewhere
    in the source (that's the cheaper, source-level check above). Same
    monkeypatch shape as `_run_repo_session` further down this file, since that
    helper only captures argv, not env."""
    import shlex
    import types

    run_dir = tmp_path / "run-thrifty"
    run_dir.mkdir()
    worktree = tmp_path / "wt-thrifty"
    worktree.mkdir()
    env_file = tmp_path / "env-thrifty.txt"
    stub = tmp_path / "claude-stub-thrifty"
    stub.write_text(
        "#!/bin/sh\n"
        f"env > {shlex.quote(str(env_file))}\n"
        "printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"x\"}'\n"
        "exit 0\n"
    )
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    args = types.SimpleNamespace(agent="reviewer", task="t", parent=None,
                                 dry_run=False, label=None, model=None,
                                 review_sha=None)
    agentctl._run_session(
        args=args, agent={"body": "sys", "model_alias": "sonnet"},
        run_id="run-thrifty", run_dir=run_dir, worktree=worktree, profile="p",
        repo="hollis", started_at="2026-08-18T00:00:00Z", user_prompt="u")

    env_lines = env_file.read_text().splitlines()
    # Scalar, not `in env_lines` directly: pytest's assertion rewriting dumps
    # the full list on failure, and env_lines is the real subprocess
    # environment (ambient secrets included) — security-reviewer, PR #505.
    pin_present = "CLAUDE_CODE_THRIFTY_SONIC=0" in env_lines
    assert pin_present, (
        "the claude subprocess _run_session spawned is missing "
        "CLAUDE_CODE_THRIFTY_SONIC=0 in its environment — the bash-first-steer "
        "pin dropped out of _run_session's env dict")


def test_every_claude_spawn_site_strips_tmux(agentctl):
    """Same shape as test_every_claude_spawn_site_pins_thrifty_sonic, for the
    TMUX/TMUX_PANE strip (dispatch_env's docstring has the full incident:
    2026-09-13, issue_01M2EG40BSYN7MXM2EWBT9VKBN — a dispatched coder's bare
    `tmux kill-server` reached the operator's live server because the spawn
    env carried the dispatcher's TMUX straight through).

    Checks each `CLAUDE_BIN, "-p"` spawn site OWNS a `DE.dispatch_env(` call
    within a window right after it, rather than comparing a whole-file total —
    a whole-file count would stay 1==1 even if the site's real env regressed
    to raw `os.environ` while an unrelated second `DE.dispatch_env(` call (a
    debug/logging copy, say) appeared elsewhere in the file (reviewer, PR #567
    round 1). A new spawn site later, with no matching call in its window,
    fails this test instead of shipping green."""
    lines = Path(agentctl.__file__).read_text().splitlines()
    spawn_site_lines = [i for i, line in enumerate(lines) if 'CLAUDE_BIN, "-p"' in line]
    assert len(spawn_site_lines) == 1, (
        f"expected 1 claude spawn site, found {len(spawn_site_lines)} — a new "
        "one must build its env from DE.dispatch_env(), or it inherits the "
        "dispatcher's TMUX/TMUX_PANE")
    # _run_session's DE.dispatch_env( call sits 157 lines below its spawn site as of
    # the second #821/main merge (2026-10-08), which combined #813's eval-dispatch
    # path and #824's Postgres fix with #821's own — 180 leaves headroom without
    # widening the window to the whole function.
    window = 180
    for i in spawn_site_lines:
        following = lines[i:i + window]
        assert any("DE.dispatch_env(" in line for line in following), (
            f"claude spawn site at {agentctl.__file__}:{i + 1} has no "
            f"DE.dispatch_env( call within {window} lines — it may be building "
            "its env from raw os.environ, carrying the dispatcher's TMUX "
            "straight through")


def test_every_claude_spawn_site_denies_push_for_review_agents(agentctl):
    """Same shape as test_every_claude_spawn_site_strips_tmux, for the
    reviewer/security-reviewer push refusal (issue_01M3MMJFKSE5ZCA5YNXCJ1YCAK):
    on 2026-09-28 a reviewer's `git push` — meant for a scratch repo, sent
    from the reviewer's own worktree after a `cd` into a not-yet-created
    directory failed — pushed a stray branch to the real
    convivy/agent-platform. A new spawn site with no matching call in its
    window ships a reviewer that can still push, with nothing here catching
    it."""
    lines = Path(agentctl.__file__).read_text().splitlines()
    spawn_site_lines = [i for i, line in enumerate(lines) if 'CLAUDE_BIN, "-p"' in line]
    assert len(spawn_site_lines) == 1, (
        f"expected 1 claude spawn site, found {len(spawn_site_lines)} — a new "
        "one must build its env with "
        "DE.dispatch_env(deny_push=_is_review_agent(args.agent)), or a "
        "reviewer spawned there keeps a git that can push")
    # _run_session's deny_push=... call sits 158 lines below its spawn site as of
    # the second #821/main merge (2026-10-08), which combined #813's eval-dispatch
    # path and #824's Postgres fix with #821's own — 180 leaves headroom without
    # widening the window to the whole function.
    window = 180
    for i in spawn_site_lines:
        following = lines[i:i + window]
        assert any("deny_push=_is_review_agent(args.agent)" in line for line in following), (
            f"claude spawn site at {agentctl.__file__}:{i + 1} has no "
            "deny_push=_is_review_agent(args.agent) in its DE.dispatch_env( "
            "call — a reviewer spawned there keeps a git that can push to a "
            "network remote")


def test_run_session_subprocess_env_excludes_tmux(agentctl, tmp_path, monkeypatch):
    """The CI-visible half of the TMUX-strip guard for the MAIN `claude -p`
    spawn site (`_run_session`): drives it against a stub `claude` that dumps
    its real environment to a file, with TMUX/TMUX_PANE set in the parent
    (as a real co session's env would be), and asserts neither reaches the
    subprocess. Fails against pre-fix code, where `{**os.environ}` carried
    both straight through. Same monkeypatch shape as
    test_thrifty_sonic_pin_reaches_run_session_subprocess_env."""
    import shlex
    import types

    monkeypatch.setenv("TMUX", "/private/tmp/tmux-501/default,1314,3")
    monkeypatch.setenv("TMUX_PANE", "%3")

    run_dir = tmp_path / "run-tmux"
    run_dir.mkdir()
    worktree = tmp_path / "wt-tmux"
    worktree.mkdir()
    env_file = tmp_path / "env-tmux.txt"
    stub = tmp_path / "claude-stub-tmux"
    stub.write_text(
        "#!/bin/sh\n"
        f"env > {shlex.quote(str(env_file))}\n"
        "printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"x\"}'\n"
        "exit 0\n"
    )
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    args = types.SimpleNamespace(agent="reviewer", task="t", parent=None,
                                 dry_run=False, label=None, model=None,
                                 review_sha=None)
    agentctl._run_session(
        args=args, agent={"body": "sys", "model_alias": "sonnet"},
        run_id="run-tmux", run_dir=run_dir, worktree=worktree, profile="p",
        repo="hollis", started_at="2026-08-18T00:00:00Z", user_prompt="u")

    env_lines = env_file.read_text().splitlines()
    env_map = dict(line.split("=", 1) for line in env_lines if "=" in line)
    env_keys = set(env_map)
    assert "TMUX" not in env_keys, (
        "the claude subprocess _run_session spawned inherited TMUX from the "
        "dispatcher — the tmux-identity strip dropped out of _run_session's "
        "env dict")
    assert "TMUX_PANE" not in env_keys, (
        "the claude subprocess _run_session spawned inherited TMUX_PANE from "
        "the dispatcher — the tmux-identity strip dropped out of "
        "_run_session's env dict")
    # Round 2 (issue_01M2EG40BSYN7MXM2EWBT9VKBN): TMUX alone isn't enough — an
    # unqualified `tmux` in the child still resolves the same-UID default
    # socket (/tmp/tmux-<uid>/default, the socket every real co session runs
    # on) unless TMUX_TMPDIR points somewhere private.
    assert "TMUX_TMPDIR" in env_keys, (
        "the claude subprocess _run_session spawned has no TMUX_TMPDIR — an "
        "unqualified tmux in it still falls back to the operator's default "
        "socket")
    assert os.path.isdir(env_map["TMUX_TMPDIR"])
    assert env_map["TMUX_TMPDIR"] != "/tmp"


# --- push refusal for reviewer/security-reviewer (issue_01M3MMJFKSE5ZCA5YNXCJ1YCAK) -
#
# Same monkeypatch shape as test_thrifty_sonic_pin_reaches_run_session_subprocess_env
# and test_run_session_subprocess_env_excludes_tmux: drive `_run_session` against a
# stub `claude` that dumps its real environment to a file, and read what actually
# reached the subprocess — not just that the call site's source contains the right
# literal (the static check above).

def _run_session_env(agentctl, tmp_path, monkeypatch, *, agent_name, label,
                     run_github_token=None):
    import shlex
    import types

    run_dir = tmp_path / f"run-{label}"
    run_dir.mkdir()
    worktree = tmp_path / f"wt-{label}"
    worktree.mkdir()
    env_file = tmp_path / f"env-{label}.txt"
    stub = tmp_path / f"claude-stub-{label}"
    stub.write_text(
        "#!/bin/sh\n"
        f"env > {shlex.quote(str(env_file))}\n"
        "printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"x\"}'\n"
        "exit 0\n"
    )
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    args = types.SimpleNamespace(agent=agent_name, task="t", parent=None,
                                 dry_run=False, label=None, model=None,
                                 review_sha=None)
    agentctl._run_session(
        args=args, agent={"body": "sys", "model_alias": "sonnet"},
        run_id=f"run-{label}", run_dir=run_dir, worktree=worktree, profile="p",
        repo="hollis", started_at="2026-08-18T00:00:00Z", user_prompt="u",
        run_github_token=run_github_token)
    env_lines = env_file.read_text().splitlines()
    return dict(line.split("=", 1) for line in env_lines if "=" in line)


@pytest.mark.parametrize("agent_name", ["reviewer", "security-reviewer"])
def test_run_session_subprocess_env_denies_push_for_review_agents(
        agentctl, tmp_path, monkeypatch, agent_name):
    env_map = _run_session_env(agentctl, tmp_path, monkeypatch,
                               agent_name=agent_name, label=agent_name)
    assert "GIT_CONFIG_COUNT" in env_map, (
        f"the claude subprocess spawned for {agent_name!r} has no "
        "GIT_CONFIG_COUNT in its environment — the push refusal dropped out "
        "of _run_session's env dict")
    count = int(env_map["GIT_CONFIG_COUNT"])
    pairs = [(env_map[f"GIT_CONFIG_KEY_{i}"], env_map[f"GIT_CONFIG_VALUE_{i}"])
             for i in range(count)]
    key = f"url.{agentctl.DE._PUSH_REFUSAL_BASE}.pushInsteadOf"
    values = {v for k, v in pairs if k == key}
    assert values == set(agentctl.DE._PUSH_REFUSAL_PREFIXES), (
        f"{agent_name!r} subprocess env is missing the push-refusal rewrite "
        f"for one or more network prefixes: got {values}, want "
        f"{set(agentctl.DE._PUSH_REFUSAL_PREFIXES)}")


def test_run_session_subprocess_env_coder_has_no_push_refusal(
        agentctl, tmp_path, monkeypatch):
    """deny_push is reviewer/security-reviewer only — a coder's git keeps the ability to
    push. `_run_session_env`'s worktree is a bare directory, not a real git checkout, so
    `git_dir` resolves to None and neither the push refusal nor the object-store redirect
    (knowledge#793 round 6) apply — GIT_CONFIG_COUNT is absent altogether here."""
    env_map = _run_session_env(agentctl, tmp_path, monkeypatch,
                               agent_name="coder", label="coder")
    assert "GIT_CONFIG_COUNT" not in env_map, (
        "a coder run's git environment carries GIT_CONFIG_COUNT despite there "
        "being no git_dir to key either the push refusal or the object-store "
        "redirect off of")
    assert "GIT_OBJECT_DIRECTORY" not in env_map
    assert "GIT_ALTERNATE_OBJECT_DIRECTORIES" not in env_map


