@pytest.mark.parametrize("agent_name", ["coder", "reviewer", "security-reviewer"])
def test_run_session_subprocess_env_always_redirects_the_git_credential_helper(
        agentctl, tmp_path, monkeypatch, agent_name):
    """Every role, not only reviewer/security-reviewer, gets the unconditional
    GH_CONFIG_DIR/GIT_CONFIG_GLOBAL/GIT_CONFIG_SYSTEM/GIT_CONFIG_NOSYSTEM/
    GIT_TERMINAL_PROMPT redirect — a coder's git credential helper must be as
    unreachable as a reviewer's."""
