def _run_repo_session_full(agentctl, tmp_path, monkeypatch, *, repo, agent=None,
                            policy=None, agent_name="reviewer", label=None):
    """Like `_run_repo_session` above, but captures BOTH the constructed argv and
    the subprocess's real environment in one drive of `_run_session`, and
    optionally pins `_resolve_run_policy` to a synthetic `Policy` — needed to
    exercise policy shapes (no MCP tool allowed, a kb-only allow) no real
    roster agent resolves to today. `policy=None` leaves `_resolve_run_policy`
    untouched, exercising whatever the real roster + Library-stub resolve to
    for `agent_name` (the live path, for the private-dispatch case where the
    point under test is `--mcp-config`'s absence, not a particular policy)."""
    import shlex
    import types

    label = label or repo
    run_dir = tmp_path / f"run-{label}"
    run_dir.mkdir()
    worktree = tmp_path / f"wt-{label}"
    worktree.mkdir()
    argv_file = tmp_path / f"argv-{label}.txt"
    env_file = tmp_path / f"env-{label}.txt"
    stub = tmp_path / f"claude-stub-{label}"
    stub.write_text(
        "#!/bin/sh\n"
        f"printf '%s\\n' \"$@\" > {shlex.quote(str(argv_file))}\n"
        f"env > {shlex.quote(str(env_file))}\n"
        "printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"x\"}'\n"
        "exit 0\n"
    )
    stub.chmod(0o755)
    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_preflight_python_worktree", lambda wt: None)
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", lambda entry: None)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda run_id, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    if policy is not None:
        monkeypatch.setattr(agentctl, "_resolve_run_policy",
                             lambda agent_name, repo, agent, model, **_kw: policy)
    args = types.SimpleNamespace(agent=agent_name, task="t", parent=None,
                                 dry_run=False, label=None, model=None,
                                 review_sha=None)
    agentctl._run_session(
        args=args, agent=agent if agent is not None else {"body": "sys", "model_alias": "sonnet"},
        run_id=f"run-{label}", run_dir=run_dir, worktree=worktree, profile="p",
        repo=repo, started_at="2026-08-18T00:00:00Z", user_prompt="u")
    argv = argv_file.read_text().splitlines()
    env_lines = env_file.read_text().splitlines()
    env_map = dict(line.split("=", 1) for line in env_lines if "=" in line)
    return argv, env_map


def _tools_arg(argv):
    """The values passed after `--tools`, up to the next flag (`--mcp-config`,
    `--strict-mcp-config` or `--model`, whichever comes first) — mirrors how
    `--allowedTools`/`--disallowedTools` are already read elsewhere in this file."""
    if "--tools" not in argv:
        return None
    i = argv.index("--tools") + 1
    out = []
    while i < len(argv) and not argv[i].startswith("--"):
        out.append(argv[i])
        i += 1
    return out


@pytest.mark.parametrize("agent_name", ["reviewer", "coder"])
def test_dispatch_always_carries_the_claudeai_connector_wall_and_cache_ttl(
        agentctl, tmp_path, monkeypatch, agent_name):
    """ENABLE_CLAUDEAI_MCP_SERVERS=false and the 5-minute prompt-cache TTL are
    unconditional on every dispatch — reviewer and coder alike, independent of
    tool-surface/MCP narrowing, which is why this is checked against the real
    (unmocked) policy path rather than a synthetic one."""
    _, env = _run_repo_session_full(agentctl, tmp_path, monkeypatch, repo="agent-platform",
                                     agent_name=agent_name, label=f"env-{agent_name}")
    assert env.get("ENABLE_CLAUDEAI_MCP_SERVERS") == "false"
    assert env.get("CLAUDE_CODE_PROMPT_CACHE_TTL") == "5m"


def test_dispatch_tool_surface_and_mcp_servers_for_reviewer_shaped_policy(
        agentctl, tmp_path, monkeypatch):
    """A reviewer-shaped policy keeps the `ops` server attached (its two
    `mcp__ops__` rules) but drops `kb` (no `mcp__kb__` rule) — `--mcp-config`
    reflects that, and `--strict-mcp-config` is still present. `--tools` IS
    passed, narrowed to the policy's built-ins PLUS `ToolSearch`: measured
    (issue_01M4BT13RP23KRTA80VM6R7HNF), restricting `--tools` while `ops`
    stays attached only blows up `ops`'s own schema to full size when
    `ToolSearch` is left OUT of the restricted set — with `ToolSearch` added,
    the same restriction measured 14,786 first-turn tokens, below the 38,944
    unrestricted baseline, not above it. `verdict` (knowledge#793) is present
    too — `reviewer` is review-class, so `_dispatch_mcp_config_json` folds it
    in after the kb/ops narrowing, unconditionally."""
    policy = _policy(
        agentctl,
        allowed=("Read", "Grep", "Glob", "Write", "mcp__ops__issue_get",
                  "mcp__ops__issue_list", "Bash(git diff:*)", "Bash(gh pr view:*)"))
