def test_dispatch_does_not_widen_allowedtools_from_the_roster_grant(
        agentctl, tmp_path, monkeypatch):
    """The union fix widens the tool SURFACE (`--tools`/`--mcp-config`), never
    the PERMISSION layer: `--allowedTools` under `dontAsk` stays exactly
    `policy.allowed`, with no `mcp__kb__` rule added just because the agent's
    own roster names one. Calling `kb_search` under enforcement is a separate,
    pre-existing gap in `tool_policy.py`'s `_READ_SURFACE` this PR does not
    touch."""
    monkeypatch.setattr(agentctl, "_enforce_tool_policy", lambda: True)
    policy = _policy(
        agentctl,
        allowed=("Read", "Grep", "Glob", "Write", "mcp__ops__issue_get",
                  "mcp__ops__issue_list", "Bash(git diff:*)", "Bash(gh pr view:*)"))
    argv, _ = _run_repo_session_full(
        agentctl, tmp_path, monkeypatch, repo="agent-platform", policy=policy,
        agent_name="reviewer",
        agent={"body": "sys", "model_alias": "sonnet",
               "tools": ["Read", "Grep", "Glob", "Write", "mcp__kb__kb_search",
                         "mcp__ops__issue_get", "mcp__ops__issue_list"]},
        label="reviewer-no-permission-widen")
    assert "--allowedTools" in argv
    i = argv.index("--allowedTools") + 1
    allowed_arg = []
    while i < len(argv) and argv[i] not in ("--strict-mcp-config", "--mcp-config", "--tools"):
        allowed_arg.append(argv[i])
        i += 1
    assert "mcp__kb__kb_search" not in allowed_arg
    assert set(allowed_arg) == set(policy.allowed)


def test_dispatch_local_roster_wrapped_tools_grant_yields_whole_rule_names_and_attaches_kb(
        agentctl, tmp_path, monkeypatch):
    """End-to-end CFO/EA-style local dispatch (security-reviewer, PR #811
    round 2, issue_01M4BT13RP23KRTA80VM6R7HNF): `reviewer`'s roster file on
    disk uses the folded-scalar `tools:` shape every real EA agent file
    uses, resolved through `--agents-dir` (not `repo=EA`/`CFO`, which are
    both registered private crews — using either here would drop
    `--mcp-config` entirely regardless of this fix, testing the wrong
    thing). Dispatched with a policy that itself grants no `mcp__kb__` rule,
    `--tools` must carry whole rule names (no single-character entries from
    exploding a string) and `--mcp-config` must still attach `kb` — the
    union round 1 restored, now proven through the real local-roster
    parsing path rather than a hand-built agent dict. Against `ed9f4d19`,
    `_tools_arg` would contain single-character entries and `kb` would be
    missing from `mcpServers`."""
    path = tmp_path / "reviewer.md"
    path.write_text(
        "---\n"
        "model: sonnet\n"
        "tools: Read, Grep, Glob, Bash(git diff:*), Bash(git log:*),\n"
        "  Bash(agentctl review-post:*), Bash(gh pr comment:*),\n"
        "  mcp__kb__kb_search, mcp__kb__kb_get\n"
        "---\n"
        "You are a test agent.\n")
    agent = agentctl.resolve_agent("reviewer", repo="agent-platform", agents_dir=str(tmp_path))
    assert all(len(t) > 1 for t in agent["tools"])  # parsing bug would already show here
    policy = _policy(
        agentctl,
        allowed=("Read", "Grep", "Glob", "Write", "mcp__ops__issue_get",
                  "mcp__ops__issue_list", "Bash(git diff:*)", "Bash(gh pr view:*)"))
    argv, _ = _run_repo_session_full(
        agentctl, tmp_path, monkeypatch, repo="agent-platform", policy=policy,
        agent_name="reviewer", agent=agent, label="local-roster-wrapped-tools")
    tools_arg = _tools_arg(argv)
    assert tools_arg is not None
    assert all(len(t) > 1 for t in tools_arg)
    assert set(tools_arg) >= {"Read", "Grep", "Glob", "Write", "Bash", "ToolSearch"}
    assert "--mcp-config" in argv
    config = json.loads(argv[argv.index("--mcp-config") + 1])
    assert "kb" in config["mcpServers"]


def test_dispatch_refuses_a_malformed_resolved_tools_shape(agentctl, tmp_path, monkeypatch):
    """A `tools` value that resolved to a bare string (what the unfixed
    parser left behind, or what a served record could carry) must refuse
    the dispatch rather than let the spawn site's `tuple()` explode it into
    single characters and silently narrow `--mcp-config` wrong."""
    policy = _policy(
        agentctl,
        allowed=("Read", "Grep", "Glob", "Write", "mcp__ops__issue_get",
                  "mcp__ops__issue_list"))
    with pytest.raises(SystemExit, match="reviewer.*not a list of strings"):
        _run_repo_session_full(
            agentctl, tmp_path, monkeypatch, repo="agent-platform", policy=policy,
            agent_name="reviewer",
            agent={"body": "sys", "model_alias": "sonnet",
                   "tools": "Read, Grep, mcp__kb__kb_search"},
            label="malformed-tools-shape")


# --- a policy `builtins:` list sets --tools directly, enforced or not -------
#
# issue_01M4C04GYC3R9NPZCK9RTYPASZ (CQ·426). #811 only narrows `--tools` from
# an ENFORCED agent's allow-list, so a coder — `tool_policy.ENFORCEABLE_AGENTS`
# never includes a build-class agent, since an allow-list permissive enough
# for arbitrary shell is equivalent to full Bash — keeps every built-in. An
# allow-list is the wrong control for a coder, but which built-ins LOAD is a
# separate axis from what's PERMITTED, and `builtins:` sets only that axis,
# directly, regardless of `policy.enforced`.

def test_resolved_agent_builtins_absent_key_is_none(agentctl):
    """No `builtins` key at all — the overwhelming majority of agents today —
    reads as `None`, the "no override" signal `_builtin_tool_surface` falls
    back on."""
    assert agentctl._resolved_agent_builtins({"tools": ["Read"]}, "coder") is None
    assert agentctl._resolved_agent_builtins({}, "coder") is None
    assert agentctl._resolved_agent_builtins(None, "coder") is None


def test_resolved_agent_builtins_explicit_none_is_none(agentctl):
    assert agentctl._resolved_agent_builtins({"builtins": None}, "coder") is None


def test_resolved_agent_builtins_accepts_a_list(agentctl):
    assert agentctl._resolved_agent_builtins(
        {"builtins": ["Bash", "Read", "Edit", "Write", "Glob", "Grep", "ToolSearch"]},
        "coder") == ("Bash", "Read", "Edit", "Write", "Glob", "Grep", "ToolSearch")


def test_resolved_agent_builtins_accepts_an_explicit_empty_list(agentctl):
    """An explicit `[]` is a real answer — "no built-ins" — distinct from the
    key's absence, the same distinction `_builtin_tool_surface`'s own `()`
    vs `None` makes for an enforced policy's `allowed`."""
    assert agentctl._resolved_agent_builtins({"builtins": []}, "coder") == ()


def test_resolved_agent_builtins_refuses_a_string_shape(agentctl):
    with pytest.raises(SystemExit, match="coder.*not a list of strings"):
        agentctl._resolved_agent_builtins({"builtins": "Bash, Read"}, "coder")


def test_resolved_agent_builtins_refuses_a_non_string_element(agentctl):
    with pytest.raises(SystemExit, match="not a list of strings"):
        agentctl._resolved_agent_builtins({"builtins": ["Read", 7]}, "coder")


def test_builtin_tool_surface_agent_builtins_overrides_unenforced_policy(agentctl):
    """The exact gap #811 left: a coder-shaped policy (`enforced=False`) has no
    allow-list to narrow BY, so `_builtin_tool_surface` would return `None`
    (today's full built-in surface) — UNLESS `agent_builtins` is given, in
    which case that list is the answer, policy untouched."""
    policy = _policy(agentctl, allowed=(), enforced=False)
    surface = agentctl._builtin_tool_surface(
        policy, (), ("Bash", "Read", "Edit", "Write", "Glob", "Grep"))
    assert surface == ("Bash", "Read", "Edit", "Write", "Glob", "Grep")


def test_builtin_tool_surface_agent_builtins_overrides_an_enforced_allow_list_too(agentctl):
    """When both `builtins:` and an enforced allow-list are present, `builtins:`
    wins — the policy's own `allowed`-derived surface is never consulted."""
    policy = _policy(agentctl, allowed=("Read", "Grep", "mcp__ops__issue_get"))
    surface = agentctl._builtin_tool_surface(policy, (), ("Bash", "Write"))
    assert surface == ("Bash", "Write")


def test_builtin_tool_surface_no_agent_builtins_keeps_811_behaviour(agentctl):
    """`agent_builtins=None` (the default) must not change a single existing
    `_builtin_tool_surface` answer — the reviewer-shaped and coder-shaped
    cases from #811's own tests, repeated here as this change's regression
    pin."""
    reviewer_policy = _policy(
        agentctl, allowed=("Read", "Grep", "Glob", "Write", "mcp__ops__issue_get",
                           "mcp__ops__issue_list", "Bash(git diff:*)"))
    assert agentctl._builtin_tool_surface(reviewer_policy) == (
        "Bash", "Glob", "Grep", "Read", "Write")
    coder_policy = _policy(agentctl, allowed=(), enforced=False)
    assert agentctl._builtin_tool_surface(coder_policy) is None


