# --- repo-local agent resolution (ARCH-177) ----------------------------------


def _boom(*a, **k):
    raise AssertionError("the shared knowledge index was touched on a local path")


def _write_agent(path, model="sonnet"):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(f"---\nmodel: {model}\ntools: [Read, Bash]\n---\nYou are a test agent.\n")


def _served(doc_id, *, model="sonnet", tools=("Read", "Bash"), model_floor=None,
            status="current", body="You are a test agent."):
    """An agent document as `GET /reference/documents/{id}` serves it (E9·5): the
    body and the five agent fields `doc_dict` carries, with None for an absent key."""
    return {"id": doc_id, "source_ref": f"projects/{doc_id}.md", "kind": "agent",
            "project": doc_id.split("/")[0], "status": status, "model": model,
            "tools": list(tools), "trigger": None, "role": doc_id.rsplit("/", 1)[-1],
            "model_floor": model_floor, "body": body}


class _Served(io.BytesIO):
    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False


class _CutOff:
    """A response whose body stops short: reading it raises IncompleteRead, as
    http.client does when the server closes before Content-Length is reached."""

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False

    def read(self):
        import http.client
        raise http.client.IncompleteRead(b'{"documents": [', 200)


def _http_error(code):
    """A reply that fails the way urllib does for a non-2xx answer."""
    def reply(url):
        import urllib.error
        raise urllib.error.HTTPError(url, code, "answered", None, None)
    return reply


def _without(key):
    """A `_FakeLibrary.edit_listing` that drops `key` from every listing page."""
    return lambda page: {k: v for k, v in page.items() if k != key}


class _FakeLibrary:
    """Stands in for the Library's fixed-address opener. `docs` is the served
    record per document id; `unreachable` fails every call the way a refused
    connection does. `page_size` pages the agent listing (None serves every row
    on one page). `edit_listing` rewrites each listing page before it is served.
    `replies` maps a request path to a callable that takes the URL and returns the
    answer to serve instead. Every requested URL is kept in `requests`."""

    def __init__(self):
        self.docs: dict[str, dict] = {}
        self.unreachable = False
        self.page_size: int | None = None
        self.edit_listing = None
        self.replies: dict[str, object] = {}
        self.requests: list[str] = []

    def open(self, req, timeout=None):
        import urllib.error
        import urllib.parse
        self.requests.append(req.full_url)
        if self.unreachable:
            raise urllib.error.URLError(ConnectionRefusedError("refused"))
        parts = urllib.parse.urlsplit(req.full_url)
        if parts.path in self.replies:
            return self.replies[parts.path](req.full_url)
        if parts.path == "/reference/documents":
            return self._listing(urllib.parse.parse_qs(parts.query))
        doc_id = urllib.parse.unquote(parts.path[len("/reference/documents/"):])
        if doc_id not in self.docs:
            raise urllib.error.HTTPError(req.full_url, 404, "not found", None, None)
        return _Served(json.dumps(self.docs[doc_id]).encode())

    def _listing(self, query):
        rows = [{k: d.get(k) for k in ("id", "kind", "project", "status")}
                for d in self.docs.values()]
        offset = int(query.get("offset", ["0"])[0])
        size = self.page_size or len(rows)
        page = rows[offset:offset + size]
        payload = {"documents": page, "count": len(page), "total": len(rows),
                   "offset": offset, "truncated": offset + size < len(rows)}
        if self.edit_listing is not None:
            payload = self.edit_listing(payload)
        return _Served(json.dumps(payload).encode())


@pytest.fixture
def library(agentctl, tmp_path, monkeypatch):
    """The Library's served agent documents. The knowledge index and checkout are
    pointed at paths that do not exist, and the index cannot be opened, so a
    resolve that reads either one fails loudly instead of answering."""
    import issue_client
    token = tmp_path / "agent-platform-token"
    token.write_text("test-token\n")
    monkeypatch.setattr(agentctl.SC, "TOKEN_FILE", token)
    fake = _FakeLibrary()
    monkeypatch.setattr(issue_client, "pinned_opener", lambda: fake)
    monkeypatch.setattr(agentctl, "KB_INDEX", tmp_path / "no-index" / "index.db")
    monkeypatch.setattr(agentctl, "KNOWLEDGE_ROOT", tmp_path / "no-checkout")
    monkeypatch.setattr(agentctl.sqlite3, "connect", _boom)
    return fake


