def test_write_cost_partial_checkpoint_prefers_gateway_spend_log(agentctl, tmp_path):
    """The checkpoint sources a gateway run's partial from gateway_spend.jsonl
    — the same source `_resolve_cost` reads at finalisation — not from
    usage_by_model, so the two can never disagree in method."""
    run_dir = tmp_path / "run-test"
    run_dir.mkdir()
    (run_dir / "meta.json").write_text(json.dumps({"model": "deepseek/deepseek-v4-flash"}))
    (run_dir / "gateway_spend.jsonl").write_text(
        json.dumps({"usd": 0.0012, "tokens_in": 100, "tokens_out": 50, "ts": "x"}) + "\n")
    # usage_by_model carries a different (wrong-for-gateway) figure to prove
    # the spend log wins over it, not just that it's used when usage is empty.
    agentctl._write_cost_partial_checkpoint(
        run_dir, {"deepseek/deepseek-v4-flash": {"input_tokens": 999999, "output_tokens": 999999,
                                                 "cache_creation_input_tokens": 0,
                                                 "cache_read_input_tokens": 0}})
    partial = json.loads((run_dir / "cost-partial.json").read_text())
    assert partial["cost_source"] == "gateway_spend_log"
    assert partial["usd"] == pytest.approx(0.0012)
    assert partial["by_model"]["deepseek/deepseek-v4-flash"]["tokens_in"] == 100


