class _FakeStreamProc:
    """A subprocess.Popen stand-in for `_stream_transcript`: `.stdout` yields
    pre-baked stream-json lines: no real `claude` child needed."""

    def __init__(self, events):
        self.stdout = [json.dumps(ev).encode() + b"\n" for ev in events]

    def terminate(self):
        pass

    def wait(self, timeout=None):
        pass

    def kill(self):
        pass


def _assistant_event(*, msg_id="msg_1", request_id="req_1", model="claude-opus-4-7",
                     input_tokens=100, output_tokens=20, cache_creation=None) -> dict:
    usage = {"input_tokens": input_tokens, "output_tokens": output_tokens,
             "cache_creation_input_tokens": 0, "cache_read_input_tokens": 0}
    if cache_creation is not None:
        usage["cache_creation"] = cache_creation
    return {
        "type": "assistant", "requestId": request_id,
        "message": {
            "id": msg_id, "model": model,
            "usage": usage,
            "content": [],
        },
    }


def test_stream_transcript_checkpoints_a_partial_once_the_interval_elapses(
        agentctl, tmp_path, monkeypatch):
    """_stream_transcript accumulates per-turn usage from assistant events and
    checkpoints cost-partial.json once `_COST_PARTIAL_WRITE_INTERVAL_S`
    elapses — deduping a byte-identical repeat of the same message (same
    message.id + requestId, ARCH-383) rather than double-counting it, exactly
    like cost_join.co_main_loop_node does for the same shape of event. Claude
    Code writes the same response up to 4x in a long session, so repeat it
    4x here rather than the minimal 2x."""
    monkeypatch.setattr(agentctl, "_COST_PARTIAL_WRITE_INTERVAL_S", 0.0)
    run_dir = tmp_path / "run-test"
    run_dir.mkdir()
    events = [_assistant_event()] * 4   # byte-identical repeats — must not 4x count
    agentctl._stream_transcript(_FakeStreamProc(events), run_dir)
    partial = json.loads((run_dir / "cost-partial.json").read_text())
    assert partial["cost_source"] == "estimate_fallback"
    assert partial["tokens_in"] == 100
    assert partial["tokens_out"] == 20


