def test_finalize_api_error_records_status_and_message(agentctl, tmp_path, monkeypatch):
    """A run that dies on terminal_reason=api_error records status and message in outcome.json.

    Normal exit_status='errored' is preserved so existing readers don't break; the new
    fields (terminal_reason, api_error_status, api_error_message) are the discriminator.
    """
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    rd, wt = _mk_run_dir(tmp_path)

    final_event = {
        "type": "result", "subtype": "success",
        "is_error": True,
        "terminal_reason": "api_error",
        "api_error_status": 403,
        "result": "403 Authentication method not allowed for this endpoint",
        "total_cost_usd": 4.50,
        "usage": {"input_tokens": 100, "output_tokens": 34000,
                  "cache_creation_input_tokens": 0, "cache_read_input_tokens": 5000000},
    }
    agentctl._finalize_run(
        run_dir=rd, worktree=wt, run_id="run-test",
        exit_code=1, final_event=final_event,
        profile="agent-platform/daytime",
        agent={"model_alias": "opus"},
    )
    outcome = json.loads((rd / "outcome.json").read_text())
    assert outcome["exit_status"] == "errored"
    assert outcome["terminal_reason"] == "api_error"
    assert outcome["api_error_status"] == 403
    assert outcome["api_error_message"] == "403 Authentication method not allowed for this endpoint"


