def test_ci_is_green_classifies_rollup_states(agentctl):
    g = agentctl._ci_is_green
    assert g([]) is True                                              # no checks: vacuously green
    assert g([{"conclusion": "SUCCESS"}, {"conclusion": "SKIPPED"}]) is True
    assert g([{"state": "SUCCESS"}]) is True                         # legacy StatusContext
    assert g([{"conclusion": "SUCCESS"}, {"conclusion": "FAILURE"}]) is False
    assert g([{"conclusion": "SUCCESS"}, {"status": "IN_PROGRESS", "conclusion": ""}]) is False
    assert g([{"state": "PENDING"}]) is False


def _ns(**kw):
    import types
    kw.setdefault("label", None)  # argparse always supplies --label (default None)
    return types.SimpleNamespace(**kw)


def test_review_post_dry_run_stamps_from_env(agentctl, tmp_path, monkeypatch, capsys):
    # the authoritative commit + run-id come from the harness env (the Phase-1
    # pin), NOT typed by the agent — review-post must read them off the env.
    body = tmp_path / "review.md"
    body.write_text("Looks correct. CI green.\n")
    full_sha = "abc123def456789abc123def456789abc123def4"  # 40-char; no normalization needed
    monkeypatch.setenv("AGENTCTL_REVIEW_SHA", full_sha)
    monkeypatch.setenv("AGENTCTL_RUN_ID", "run-ea0e")
    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="APPROVE", agent="reviewer", body_file=str(body),
        reviewed_commit=None, run_id=None, repo="convivy/agent-platform", dry_run=True))
    out = capsys.readouterr().out
    assert rc == 0
    # the rendered comment carries a parseable stamp at the pinned commit
    stamp = agentctl.RP.parse(out)
    assert stamp is not None
    assert stamp.reviewed_commit == full_sha and stamp.run_id == "run-ea0e"
    assert stamp.verdict == "APPROVE" and stamp.agent == "reviewer"


def test_resolve_parent_defaults_to_agentctl_run_id(agentctl, monkeypatch):
    """--parent auto-defaults to the dispatching run's AGENTCTL_RUN_ID, so an
    orchestrator's late close-loop / cycle-2 dispatch nests under it instead of
    orphaning as a standalone /activity row (ARCH-284 follow-up)."""
    monkeypatch.delenv("AGENTCTL_RUN_ID", raising=False)
    assert agentctl._resolve_parent(None) is None                  # co spawn: no env → no parent
    assert agentctl._resolve_parent("run-explicit") == "run-explicit"
    monkeypatch.setenv("AGENTCTL_RUN_ID", "run-orch123")
    assert agentctl._resolve_parent(None) == "run-orch123"         # orchestrator dispatch auto-nests
    assert agentctl._resolve_parent("run-explicit") == "run-explicit"  # explicit --parent wins


def _seed_run_dir(agentctl, T, tmp_path, monkeypatch, run_id, *, origin):
    """Create a real run dir with a recorded origin, wired through RUNS_ROOT so
    `_find_run_dir` / `_origin_of_run` can discover it by run-id alone — the
    same way a live parent run's meta.json would be found."""
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = T.create_run_dir(run_id, date="2026-08-25")
    T.write_meta(d, run_id=run_id, agent="coder", task="t",
                 started_at=T.now_iso(), repo="agent-platform", worktree=str(tmp_path),
                 profile="p", model="claude-sonnet-4-6", origin=origin)
    return d


def test_run_origin_inherits_from_parent_regardless_of_env(agentctl, tmp_path, monkeypatch):
    """issue_01M0VJ8KDMKQYD1HJVXC78FT5J: a run cannot place itself outside
    CAPPED_ORIGINS by mutating its own environment. Once a spawn HAS a resolved
    parent, its origin comes from the PARENT's recorded meta.json, never from
    this process's own AGENT_RUN_ORIGIN — clearing, unsetting, or misspelling
    that env var must not escape the cap."""
    import telemetry as T
    _seed_run_dir(agentctl, T, tmp_path, monkeypatch, "run-parent01", origin="scheduled")

    monkeypatch.delenv("AGENT_RUN_ORIGIN", raising=False)
    assert agentctl._run_origin("run-parent01") == "scheduled"

    monkeypatch.setenv("AGENT_RUN_ORIGIN", "interactive")   # cleared/misspelled by a descendant
    assert agentctl._run_origin("run-parent01") == "scheduled"

    monkeypatch.setenv("AGENT_RUN_ORIGIN", "not-a-real-origin")
    assert agentctl._run_origin("run-parent01") == "scheduled"


def test_run_origin_parentless_dispatch_still_resolves_interactive(agentctl, monkeypatch):
    """The flip side, and the regression this fix must not cause: a genuinely
    top-level dispatch (no parent at all — a fresh human `co` session) must
    still resolve `interactive`, or every co-session dispatch would start
    getting capped, which is a worse regression than the bug this fixes."""
    monkeypatch.delenv("AGENT_RUN_ORIGIN", raising=False)
    assert agentctl._run_origin(None) == "interactive"
    # the root of the inheritance chain (the launchd launcher itself) is still
    # trusted verbatim — there is nothing else for it to inherit from
    monkeypatch.setenv("AGENT_RUN_ORIGIN", "scheduled")
    assert agentctl._run_origin(None) == "scheduled"


def test_run_origin_unreadable_parent_fails_into_the_capped_pool(agentctl, tmp_path, monkeypatch):
    """A parent that's supposed to exist (this spawn HAS a resolved parent) but
    whose record can't be read must fail INTO the capped pool (`scheduled`),
    not out of it — an unreadable parent record is exactly what an escape
    attempt would produce, the opposite direction from the parentless
    fallback above."""
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    assert agentctl._run_origin("run-does-not-exist") == "scheduled"


def test_budget_gate_inherits_parent_origin_when_env_is_cleared(agentctl, tmp_path, monkeypatch):
    """End to end: `_budget_gate` must not skip the cap just because
    AGENT_RUN_ORIGIN is missing on a nested dispatch — a worker that clears or
    misspells the env var before calling `agentctl spawn` must still gate
    against its parent's (scheduled) pool (issue_01M0VJ8KDMKQYD1HJVXC78FT5J)."""
    import telemetry as T
    from types import SimpleNamespace
    _seed_run_dir(agentctl, T, tmp_path, monkeypatch, "run-orch-parent", origin="scheduled")
    monkeypatch.delenv("AGENT_RUN_ORIGIN", raising=False)

    seen = {}

    def _status(pool="overnight", **kw):
        seen["pool"] = pool
        return {"pool": pool, "soft_usd": 30.0, "hard_usd": 80.0,
                "spent_today_usd": 999.0, "interactive_today_usd": 0.0,
                "soft_crossed": True, "hard_crossed": True}

    monkeypatch.setattr(agentctl.B, "status", _status)
    monkeypatch.setattr(agentctl, "_budget_refuse_and_record", lambda *a, **k: 3)

    args = SimpleNamespace(budget_warn=None, parent="run-orch-parent")
    assert agentctl._budget_gate(args, {}, "convivy/x", "p") == 3
    assert seen["pool"] == "overnight"


def test_run_origin_parent_cannot_lower_the_callers_own_cap(agentctl, tmp_path, monkeypatch):
    """security-reviewer's blocking finding on PR #438: `--parent` is a public,
    unauthenticated CLI flag, so a scheduled worker can point it at any known
    run-id — including a real interactive run's id read off a past PR's
    review-post comment — and `_origin_of_run` will happily read back that
    run's genuinely-recorded `interactive` origin. A spawn whose OWN
    AGENTCTL_RUN_ID names a scheduled run must still resolve `scheduled` even
    when --parent explicitly names a recorded interactive run: the caller's
    own capped origin wins over whatever --parent claims."""
    import telemetry as T
    _seed_run_dir(agentctl, T, tmp_path, monkeypatch, "run-scheduled-self", origin="scheduled")
    _seed_run_dir(agentctl, T, tmp_path, monkeypatch, "run-public-interactive", origin="interactive")
    monkeypatch.setenv("AGENTCTL_RUN_ID", "run-scheduled-self")

    assert agentctl._run_origin("run-public-interactive") == "scheduled"

    # An uncapped caller (a real interactive co session) does NOT get its
    # spawn's origin displaced just because it names a differently-originated
    # parent — the override only ever fires to protect a caller's OWN cap,
    # never to override in the other direction.
    monkeypatch.setenv("AGENTCTL_RUN_ID", "run-public-interactive")
    assert agentctl._run_origin("run-scheduled-self") == "scheduled"


def test_review_post_refuses_without_a_reviewed_commit(agentctl, tmp_path, monkeypatch, capsys):
    body = tmp_path / "review.md"
    body.write_text("body\n")
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)
    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="APPROVE", agent="reviewer", body_file=str(body),
        reviewed_commit=None, run_id="r", repo="convivy/x", dry_run=True))
    assert rc == 2
    err = capsys.readouterr().err
    assert "no reviewed commit" in err
    # The refusal tells a reviewer to dispatch with --pr; a --review-sha dispatch with no
    # PR records no PR, so its stamp never counts.
    assert "--pr <N>" in err and "records no PR" in err


# --- write-time SHA normalization: hex-guard (security-reviewer round 2) ------

def test_review_post_non_hex_sha_skips_normalization(agentctl, tmp_path, monkeypatch, capsys):
    """A non-hex reviewed_commit (e.g. a path-traversal value) must not be
    interpolated into the gh api URL. The guard must warn on stderr and leave
    the value unchanged rather than calling subprocess."""
    body = tmp_path / "review.md"
    body.write_text("body\n")
    calls = []

    import subprocess as _subprocess
    original_run = _subprocess.run

    def spy_run(cmd, **kw):
        if "gh" in cmd and "api" in cmd:
            calls.append(cmd)
        return original_run(["true"], **{k: v for k, v in kw.items()
                                         if k in ("capture_output", "text", "timeout")})

    monkeypatch.setattr("subprocess.run", spy_run)
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)
    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="REQUEST_CHANGES", agent="reviewer", body_file=str(body),
        reviewed_commit="../../../other-endpoint", run_id="r", repo="convivy/x",
        dry_run=True))
    assert rc == 0
    assert not calls, "gh api must not be called for a non-hex reviewed_commit"
    err = capsys.readouterr().err
    assert "not a hex SHA" in err


def test_review_post_hex_sha_still_normalizes(agentctl, tmp_path, monkeypatch, capsys):
    """A well-formed abbreviated hex SHA must still be expanded via gh api."""
    body = tmp_path / "review.md"
    body.write_text("body\n")
    full = "a" * 40
    abbrev = "a" * 9

    import subprocess as _subprocess

    def fake_run(cmd, **kw):
        r = _subprocess.CompletedProcess(cmd, 0)
        r.stdout = full + "\n"
        r.stderr = ""
        return r

    monkeypatch.setattr("subprocess.run", fake_run)
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)
    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="REQUEST_CHANGES", agent="reviewer", body_file=str(body),
        reviewed_commit=abbrev, run_id="r", repo="convivy/x", dry_run=True))
    assert rc == 0
    out = capsys.readouterr().out
    stamp = agentctl.RP.parse(out)
    assert stamp is not None
    assert stamp.reviewed_commit == full, (
        f"abbreviation {abbrev!r} should have been expanded to {full!r}, got {stamp.reviewed_commit!r}")


def test_review_post_sha_normalization_uppercase_hex_normalized(agentctl, tmp_path, monkeypatch, capsys):
    """An uppercase hex abbreviation must be accepted and normalized to lowercase
    before the gh api call (AGENTCTL_REVIEW_SHA is set externally and may carry mixed case).
    The stamp must carry the full lowercase SHA returned by gh."""
    body = tmp_path / "review.md"
    body.write_text("body\n")
    full = "a" * 40
    abbrev_upper = "A" * 9  # valid hex, uppercase

    import subprocess as _subprocess

    def fake_run(cmd, **kw):
        r = _subprocess.CompletedProcess(cmd, 0)
        r.stdout = full + "\n"
        r.stderr = ""
        return r

    monkeypatch.setattr("subprocess.run", fake_run)
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)
    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="REQUEST_CHANGES", agent="reviewer", body_file=str(body),
        reviewed_commit=abbrev_upper, run_id="r", repo="convivy/x", dry_run=True))
    assert rc == 0
    out = capsys.readouterr().out
    stamp = agentctl.RP.parse(out)
    assert stamp is not None
    assert stamp.reviewed_commit == full, (
        f"uppercase abbreviation {abbrev_upper!r} should have been expanded to {full!r}")


def test_review_post_sha_normalization_nonzero_returncode_fails_closed(agentctl, tmp_path, monkeypatch, capsys):
    """A non-zero gh api exit (e.g. 422 Ambiguous) is a clean subprocess exit, not an
    exception. Review-post must detect it explicitly and refuse to write the stamp rather
    than silently carrying the abbreviated SHA (collision-assisted prefix forgery via
    _sha_match). Return code must be non-zero; no stamp must appear in stdout."""
    body = tmp_path / "review.md"
    body.write_text("body\n")
    abbrev = "abc1234ef"  # 9 hex chars — valid prefix, ambiguous on gh

    import subprocess as _subprocess

    def fake_run_nonzero(cmd, **kw):
        r = _subprocess.CompletedProcess(cmd, 422)
        r.stdout = ""
        r.stderr = "422 Ambiguous commit\n"
        return r

    monkeypatch.setattr("subprocess.run", fake_run_nonzero)
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)
    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="REQUEST_CHANGES", agent="reviewer", body_file=str(body),
        reviewed_commit=abbrev, run_id="r", repo="convivy/x", dry_run=True))
    captured = capsys.readouterr()
    assert rc != 0, "must fail closed when gh api returns non-zero"
    assert agentctl.RP.parse(captured.out) is None, "no stamp must be written when normalization fails"
    assert "normalization failed" in captured.err or "422" in captured.err


def test_review_post_sha_normalization_exception_fails_closed(agentctl, tmp_path, monkeypatch, capsys):
    """When subprocess.run raises (e.g. timeout, FileNotFoundError), review-post must
    refuse to write the stamp and return non-zero. Warn on stderr; no stamp in stdout."""
    body = tmp_path / "review.md"
    body.write_text("body\n")
    abbrev = "abc1234ef"

    def raising_run(cmd, **kw):
        raise FileNotFoundError("gh not found")

    monkeypatch.setattr("subprocess.run", raising_run)
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)
    rc = agentctl.cmd_review_post(_ns(
        pr="7", verdict="REQUEST_CHANGES", agent="reviewer", body_file=str(body),
        reviewed_commit=abbrev, run_id="r", repo="convivy/x", dry_run=True))
    captured = capsys.readouterr()
    assert rc != 0, "must fail closed when subprocess raises"
    assert agentctl.RP.parse(captured.out) is None, "no stamp must be written when normalization raises"
    assert "normalization failed" in captured.err


def _fake_pr_view(agentctl, monkeypatch, *, head, comments=None, rollup, is_draft=False):
    """Patch agentctl._gh_pr_json to return a canned PR view (no gh subprocess)."""
    def fake(pr, fields, repo=None):
        return {"headRefOid": head, "comments": comments or [], "statusCheckRollup": rollup,
                "state": "OPEN", "isDraft": is_draft,
                "mergeable": "MERGEABLE", "mergeStateStatus": "CLEAN",
                "baseRefName": "main"}
    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)


def _stamp_comment(agentctl, agent, commit, verdict="APPROVE", *, run_id="r"):
    return {"body": agentctl.RP.render_header(
        pr="7", repo="convivy/x", reviewed_commit=commit, verdict=verdict,
        agent=agent, run_id=run_id)}


def _trust_all_stamps(agentctl, monkeypatch):
    """Tests of the gate LOGIC (stale/CI) aren't testing authenticity — treat
    every parsed stamp as authentic so run-id resolution doesn't drop the canned
    stamps (whose run-id 'r' has no run dir). Authenticity has its own tests below."""
    monkeypatch.setattr(agentctl.RP, "authenticate", lambda *a, **k: None)


def test_an_authenticated_stamp_carries_its_runs_pin_and_a_comment_cannot_set_it(agentctl, monkeypatch):
    """The merge gate reads a stamp's head from `pinned_sha`, so it must come from the run's
    meta.json. A comment that writes a `pinned-sha` line is an unknown header key and is
    ignored, and a run that pins no sha carries the empty pin."""
    pin, forged = "a" * 40, "f" * 40
    runs = {"run-pinned": agentctl.RP.RunFacts(found=True, agent="reviewer",
                                               repo="convivy/x", review_sha=pin,
                                               posted_verdict="APPROVE", posted_pr="7"),
            "run-unpinned": agentctl.RP.RunFacts(found=True, agent="security-reviewer",
                                                 repo="convivy/x", review_sha="",
                                                 posted_verdict="APPROVE", posted_pr="7")}
    monkeypatch.setattr(agentctl, "_resolve_run_facts", lambda rid: runs[rid])

    def block(agent, run_id, extra=""):
        return {"body": (f"<!-- agentctl-review\nv: 1\npr: 7\nrepo: convivy/x\n"
                         f"reviewed-commit: {pin}\nverdict: APPROVE\nagent: {agent}\n"
                         f"run-id: {run_id}\n{extra}-->")}

    stamps = agentctl._authenticated_stamps(
        {"headRefOid": pin, "comments": [block("reviewer", "run-pinned",
                                               extra=f"pinned-sha: {forged}\n"),
                                         block("security-reviewer", "run-unpinned")]},
        allow_unverified=False, echo=False, repo="convivy/x", pr="7")
    assert [(s.agent, s.pinned_sha) for s in stamps] == [("reviewer", pin),
                                                        ("security-reviewer", "")]


