# --- stamp authenticity wiring (ARCH-193) ------------------------------------

def test_review_status_drops_forged_worker_stamp(agentctl, monkeypatch, capsys):
    # A worker (bypassPermissions → has gh pr comment) posts a stamp claiming
    # agent=reviewer but with its OWN run-id, which resolves to a coder run. The
    # gate must drop it → reviewer has no valid APPROVE → FAIL.
    head = "f" * 40
    facts = {"run-forge": agentctl.RP.RunFacts(found=True, agent="coder",
                                               repo="convivy/x", review_sha=head),
             "run-sec": agentctl.RP.RunFacts(found=True, agent="security-reviewer",
                                             repo="convivy/x", review_sha=head)}
    monkeypatch.setattr(agentctl, "_resolve_run_facts",
                        lambda rid: facts.get(rid, agentctl.RP.RunFacts(found=False)))
    _fake_pr_view(agentctl, monkeypatch, head=head, rollup=[{"conclusion": "SUCCESS"}],
                  comments=[_stamp_comment(agentctl, "reviewer", head, run_id="run-forge"),
                            _stamp_comment(agentctl, "security-reviewer", head, run_id="run-sec")])
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1 and "FAIL" in out
    assert "ignoring unauthenticated stamp" in out and "not a review-class agent" in out
    assert "no review posted by reviewer" in out


def test_review_status_refuses_a_stamp_whose_run_id_is_a_planted_duplicate(
        agentctl, monkeypatch, tmp_path, capsys):
    """End-to-end (no mocked `_resolve_run_facts`): the WHY section of
    issue_01M1JWB7M75SZ160VRJRCGARBF, reproduced. `run-dup-rev`'s real run was a
    coder (not review-class) — it never should authenticate a reviewer stamp. The
    same worker plants a future-dated directory under its OWN run-id, forging
    `agent: "reviewer"` with matching repo/review_sha. Under the old first-match
    resolver the forged, newer-sorted directory would win and the forged stamp
    would authenticate; the gate must instead refuse the run-id as ambiguous. The
    security-reviewer's own unambiguous run is untouched, so only the forged stamp
    is dropped and the overall verdict stays FAIL rather than a false PASS."""
    import telemetry as T
    head = _SHA
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)

    real = T.create_run_dir("run-dup-rev", date="2026-08-03")
    T.write_meta(real, run_id="run-dup-rev", agent="coder", task="t",
                started_at="2026-08-03T00:00:00Z", repo="convivy/x",
                worktree=str(tmp_path), profile="p", model="claude-opus-4-7")
    planted = T.create_run_dir("run-dup-rev", date="2099-01-01")  # the forged plant
    T.write_meta(planted, run_id="run-dup-rev", agent="reviewer", task="t",
                started_at="2099-01-01T00:00:00Z", repo="convivy/x",
                worktree=str(tmp_path), profile="p", model="claude-opus-4-7",
                review_sha=head, pr="7")

    sec = T.create_run_dir("run-sec-ok", date="2026-08-03")
    T.write_meta(sec, run_id="run-sec-ok", agent="security-reviewer", task="t",
                started_at="2026-08-03T00:00:00Z", repo="convivy/x",
                worktree=str(tmp_path), profile="p", model="claude-opus-4-7",
                review_sha=head, pr="7")
    T.update_meta(sec, review_verdict="APPROVE", review_pr="7")  # what review-post records

    _fake_pr_view(agentctl, monkeypatch, head=head, rollup=[{"conclusion": "SUCCESS"}],
                  comments=[_stamp_comment(agentctl, "reviewer", head, run_id="run-dup-rev"),
                            _stamp_comment(agentctl, "security-reviewer", head,
                                          run_id="run-sec-ok")])
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1 and "FAIL" in out
    assert "no review posted by reviewer" in out
    assert "no review posted by security-reviewer" not in out, (
        "the unambiguous security-reviewer stamp must still authenticate")


def test_review_status_reports_head_advanced_not_stale_replay(agentctl, monkeypatch, capsys):
    """The benign race (issue_01KYRQBNXRHB2PT8BKKNEW745V): the reviewer was pinned to
    `pin` at spawn; the PR head advanced to a descendant while it was in flight, and
    its stamp names the new head. The compare API proves the head advanced past the
    pin, so review-status must report a re-dispatch, not a stale replay. The stamp is
    still dropped — the gate must not count a review of a superseded commit."""
    pin, head = "a" * 40, "f" * 40
    monkeypatch.setattr(
        agentctl, "_resolve_run_facts",
        lambda rid: agentctl.RP.RunFacts(
            found=True, agent="reviewer", repo="convivy/x", review_sha=pin)
        if rid == "run-old"
        else agentctl.RP.RunFacts(
            found=True, agent="security-reviewer", repo="convivy/x", review_sha=head))
    _fake_pr_view(agentctl, monkeypatch, head=head, rollup=[{"conclusion": "SUCCESS"}],
                  comments=[_stamp_comment(agentctl, "reviewer", head, run_id="run-old"),
                            _stamp_comment(agentctl, "security-reviewer", head,
                                           run_id="run-sec")])

    class _Ahead:
        returncode = 0
        stdout = "ahead"          # compare says: every pin commit is in the head
        stderr = ""

    monkeypatch.setattr(agentctl.subprocess, "run", lambda cmd, **kw: _Ahead())
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=True, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1, "a stamp on a superseded commit must still fail the gate"
    assert "head advanced during review" in out
    assert "stale replay" not in out


def test_review_status_keeps_stale_replay_when_head_diverged(agentctl, monkeypatch, capsys):
    """The Dependabot rebase case must NOT be softened: a rebase rewrites the branch,
    so the new head is not a descendant of the pin — the compare API says `diverged`,
    and the pin is the only record of what the run was dispatched to read. FAIL CLOSED:
    the rejection keeps its original wording (issue_01KYRQBNXRHB2PT8BKKNEW745V)."""
    pin, head = "a" * 40, "f" * 40
    monkeypatch.setattr(
        agentctl, "_resolve_run_facts",
        lambda rid: agentctl.RP.RunFacts(
            found=True, agent="reviewer", repo="convivy/x", review_sha=pin))
    _fake_pr_view(agentctl, monkeypatch, head=head, rollup=[{"conclusion": "SUCCESS"}],
                  comments=[_stamp_comment(agentctl, "reviewer", head, run_id="run-old")])

    class _Diverged:
        returncode = 0
        stdout = "diverged"       # rebased: neither commit is an ancestor of the other
        stderr = ""

    monkeypatch.setattr(agentctl.subprocess, "run", lambda cmd, **kw: _Diverged())
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=True, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1
    assert "stale replay" in out
    assert "head advanced during review" not in out


def test_review_status_disambiguation_tracks_marker_constant(agentctl, monkeypatch, capsys):
    """The caller recognises the commit-binding rejection by its NAMED marker, not
    the message's prose (PR #330 review suggestion). A message refactor rewrites the
    token value on both sides of the seam (as the sync test requires), and the
    head-advance disambiguation must still fire. A caller that hardcoded the old
    prose would silently stop disambiguating here while the gate stayed closed."""
    pin, head = "a" * 40, "f" * 40
    monkeypatch.setattr(
        agentctl, "_resolve_run_facts",
        lambda rid: agentctl.RP.RunFacts(
            found=True, agent="reviewer", repo="convivy/x", review_sha=pin))
    _fake_pr_view(agentctl, monkeypatch, head=head, rollup=[{"conclusion": "SUCCESS"}],
                  comments=[_stamp_comment(agentctl, "reviewer", head, run_id="run-old")])

    class _Ahead:
        returncode = 0
        stdout = "ahead"          # compare says: every pin commit is in the head
        stderr = ""

    monkeypatch.setattr(agentctl.subprocess, "run", lambda cmd, **kw: _Ahead())
    monkeypatch.setattr(agentctl, "_STALE_REPLAY_MARKER", "commit-binding rejection")
    monkeypatch.setattr(agentctl.RP, "STALE_REPLAY_MARKER", "commit-binding rejection")
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=True, allow_unverified=False))
    out = capsys.readouterr().out
    assert rc == 1, "a stamp on a superseded commit must still fail the gate"
    assert "head advanced during review" in out, (
        "reworded marker must still trigger the disambiguation; a prose-matching "
        f"caller would have printed the raw rejection instead: {out!r}")
    assert "commit-binding rejection" not in out


def test_head_advanced_beyond_pin_maps_compare_status(agentctl, monkeypatch):
    # `ahead` is the one status that proves the pin is an ancestor of the head;
    # every other compare outcome leaves the caller to fail closed.
    statuses = iter(["ahead", "diverged", "behind", "identical"])
    monkeypatch.setattr(agentctl.subprocess, "run", lambda cmd, **kw: type(
        "R", (), {"returncode": 0, "stdout": next(statuses), "stderr": ""})())
    assert agentctl._head_advanced_beyond_pin("a" * 40, "f" * 40, "convivy/x") is True
    assert agentctl._head_advanced_beyond_pin("a" * 40, "f" * 40, "convivy/x") is False
    assert agentctl._head_advanced_beyond_pin("a" * 40, "f" * 40, "convivy/x") is False
    assert agentctl._head_advanced_beyond_pin("a" * 40, "f" * 40, "convivy/x") is False


def test_head_advanced_beyond_pin_fails_closed(agentctl, monkeypatch):
    # empty inputs and a gh failure all mean "cannot prove forward movement" → None,
    # which the caller maps to the stale-replay rejection (issue_...).
    assert agentctl._head_advanced_beyond_pin("", "f" * 40, "convivy/x") is None
    assert agentctl._head_advanced_beyond_pin("a" * 40, "", "convivy/x") is None
    assert agentctl._head_advanced_beyond_pin("a" * 40, "f" * 40, "") is None
    monkeypatch.setattr(agentctl.subprocess, "run", lambda cmd, **kw: type(
        "R", (), {"returncode": 1, "stdout": "", "stderr": "gh: not found"})())
    assert agentctl._head_advanced_beyond_pin("a" * 40, "f" * 40, "convivy/x") is None


