def test_collect_run_descendants_handles_parent_cycle(agentctl, monkeypatch):
    """A pathological parent cycle must not loop forever (seen-set guard)."""
    runs = [_run("run-x", parent="run-y"), _run("run-y", parent="run-x")]
    monkeypatch.setattr(agentctl.R, "list_runs", lambda: runs)
    got = {r["run_id"] for r in agentctl._collect_run_descendants("run-x")}
    assert got == {"run-x", "run-y"}


def test_cmd_kill_tree_reaps_descendants_first_then_root(agentctl, monkeypatch):
    order = []
    monkeypatch.setattr(agentctl, "_collect_run_descendants",
                        lambda root: [_run("run-grand", parent="run-root"),
                                      _run("run-child", parent="run-root")])

    def fake_terminate(rid, final):
        order.append((rid, final))
        return 0

    monkeypatch.setattr(agentctl, "_terminate_run", fake_terminate)
    from types import SimpleNamespace
    rc = agentctl.cmd_kill(SimpleNamespace(run_id="run-root", final=True, tree=True))
    assert rc == 0
    # descendants reaped before the root, --final propagated to each
    assert order == [("run-grand", True), ("run-child", True), ("run-root", True)]


def test_cmd_kill_tree_succeeds_when_root_already_deregistered(agentctl, monkeypatch, capsys):
    """Orphan-reap success: root gone (terminate -> 1) but we reaped a live child."""
    monkeypatch.setattr(agentctl, "_collect_run_descendants",
                        lambda root: [_run("run-orphan", parent="run-root")])
    monkeypatch.setattr(agentctl, "_terminate_run",
                        lambda rid, final: 0 if rid == "run-orphan" else 1)
    from types import SimpleNamespace
    rc = agentctl.cmd_kill(SimpleNamespace(run_id="run-root", final=True, tree=True))
    assert rc == 0
    assert "reaped 1 live descendant" in capsys.readouterr().out


def test_cmd_kill_without_tree_still_errors_on_missing_root(agentctl, monkeypatch, capsys):
    """Regression guard: a plain kill of a missing run keeps the old 1/error."""
    monkeypatch.setattr(agentctl, "_terminate_run", lambda rid, final: 1)
