# --- P0: worktree-class detection guards the empty-task → primary trap (2026-07-04) ---

def test_architect_does_not_collide_with_its_spawning_triage_stage(agentctl):
    """issue_01KYQ9N00Q7HJYSETBV8TPY3D9: arch-produce died every arch-led night.

    `architect` was absent from `_DEDICATED_WORKTREE_WORKERS`, so `derive_purpose`
    returned None and it resolved to the PRIMARY checkout — which `overnight-triage`
    already holds for the length of its stage. Triage is what spawns the architect,
    so the parent held the tree its own child needed: `worktree busy — held by
    run-<triage>`. Sous Chef went 7 days without an arch pass.

    The regression is invisible from the outside: WorktreeBusy is a refusal, not a
    crash, so the ledger records every stage `done` and only a digest `fyi` line
    mentions it. Assert the purpose is resolved and distinct rather than trusting
    that a night "completed".
    """
    purpose = agentctl.derive_purpose("architect", "review the directions subsystem")
    assert purpose is not None, (
        "architect resolves to purpose=None, which means the primary checkout — the "
        "collision that blocked arch-produce")
    # Triage still resolves to the primary; the point is that the architect no longer
    # lands in the same place. If triage is ever moved too, this stays true.
    assert purpose != agentctl.derive_purpose("overnight-triage", "triage the queue")


def test_is_worktree_class(agentctl):
    # Workers and orchestrators that MUST get a dedicated worktree, never the primary.
    for name in ("coder", "refactorer", "test-writer", "reviewer",
                 "security-reviewer", "explainer", "bug-fixer", "bug-investigator",
                 "planning-orchestrator", "architect"):
        assert agentctl._is_worktree_class(name), name
    # Internal-app prefixes strip to the underlying role (ARCH-177).
    assert agentctl._is_worktree_class("hollis-coder")
    assert agentctl._is_worktree_class("pa-reviewer")
    # Agents that do NOT use the P0 guard: no isolation required.
    for name in ("planner", "curator"):
        assert not agentctl._is_worktree_class(name), name


def test_derive_purpose_blank_task_returns_none(agentctl):
    # The P0 trigger: a worktree-class worker with an empty task loses derive_purpose's
    # `and task` slug and returns None (→ primary). The cmd_spawn guard rejects this
    # before allocation; a real task yields a dedicated purpose.
    assert agentctl.derive_purpose("coder", "") is None
    assert agentctl.derive_purpose("coder", None) is None
    assert agentctl.derive_purpose("coder", "implement the thing") is not None


# --- P1c: run-id resolves identically for a live and a finished run (2026-07-04) ---

def test_resolve_worktree_by_run_registry_then_meta(agentctl, tmp_path, monkeypatch):
    reg_wt = tmp_path / "wt_reg"
    meta_wt = tmp_path / "wt_meta"

    # Live run: registry hit → registry worktree (fast path).
    monkeypatch.setattr(
        agentctl.R, "get_run",
        lambda rid: {"worktree": str(reg_wt)} if rid == "run-live" else None)
    assert agentctl._resolve_worktree_by_run("run-live") == reg_wt.resolve()

    # Finished run: registry entry deleted at finalize, but the run dir persists →
    # fall back to meta.json (the case that used to fail `publish --run`).
    runs_root = tmp_path / "agent-runs"
    rd = runs_root / "2026-07-04" / "run-done"
    rd.mkdir(parents=True)
    (rd / "meta.json").write_text(
        json.dumps({"run_id": "run-done", "worktree": str(meta_wt)}))
    monkeypatch.setattr(agentctl, "RUNS_ROOT", runs_root)
    assert agentctl._resolve_worktree_by_run("run-done") == meta_wt.resolve()

    # Neither registry nor run dir → None.
    assert agentctl._resolve_worktree_by_run("run-missing") is None


# --- P1b: cmd_status derives done-state from ground truth (2026-07-04) ---

def test_cmd_status_ground_truth_ended_state(agentctl, tmp_path, monkeypatch, capsys, runs_root):
    from types import SimpleNamespace
    run_dirs_root = tmp_path / "agent-runs"
    day = run_dirs_root / "2026-07-04"
    monkeypatch.setattr(agentctl, "RUNS_ROOT", run_dirs_root)

    def make_run(rid, *, meta_extra=None, outcome=False):
        rd = day / rid
        rd.mkdir(parents=True)
        meta = {"run_id": rid, "agent": "coder", "task": "t", "repo": "sous-chef",
                "worktree": "/wt", "profile": "p", "model": "m",
                "started_at": "2026-07-04T00:00:00Z", "pid": 999999}
        meta.update(meta_extra or {})
        (rd / "meta.json").write_text(json.dumps(meta))
        if outcome:
            (rd / "outcome.json").write_text(json.dumps({"exit_status": "completed"}))

    # (1) ended_at present → show it verbatim.
    make_run("run-a", meta_extra={"ended_at": "2026-07-04T01:00:00Z"})
    agentctl.cmd_status(SimpleNamespace(run_id="run-a"))
    assert "2026-07-04T01:00:00Z" in capsys.readouterr().out

    # (2) no ended_at but outcome.json on disk → finalized (the P1b fix — this used
    # to read "(still running)").
    make_run("run-b", outcome=True)
    agentctl.cmd_status(SimpleNamespace(run_id="run-b"))
    assert "finalized" in capsys.readouterr().out

    # (3) no ended_at, no outcome, pid dead → killed-not-finalized, NOT "still running".
    monkeypatch.setattr(agentctl, "_pid_alive", lambda pid: False)
    make_run("run-c")
    agentctl.cmd_status(SimpleNamespace(run_id="run-c"))
    out = capsys.readouterr().out
    assert "still running" not in out
    assert "not finalized" in out

    # (4) pid alive, but the OS has recycled it: the start time recorded at
    # spawn doesn't match what that pid shows now. A bare pid match would read
    # this as "still running" forever (security review, PR #457) — the
    # corroborated check must call it not-finalized instead, the same verdict
    # `agentctl wait` reaches via `_run_process_gone`. The recorded start time
    # lives in the registry, not meta.json (round 2 of the same finding —
    # see `_run_process_gone`'s docstring).
    import registry as R
    monkeypatch.setattr(agentctl, "_pid_alive", lambda pid: True)
    monkeypatch.setattr(agentctl, "_pid_start_time", lambda pid: "Tue Jan  2 00:00:00 2024")
    make_run("run-d")
    R.add_run({"run_id": "run-d", "agent": "coder", "task": "t",
               "started_at": "2026-07-04T00:00:00Z", "repo": "sous-chef",
               "worktree": "/wt", "pid": 999999,
               "pid_started_at": "Mon Jan  1 00:00:00 2024"})
    agentctl.cmd_status(SimpleNamespace(run_id="run-d"))
    out = capsys.readouterr().out
    assert "still running" not in out
    assert "not finalized" in out


def test_cmd_status_reports_ambiguity_with_both_directories_named(
        agentctl, tmp_path, monkeypatch, capsys):
    """A run-id planted under a second date directory (issue_01M1JWB7M75SZ160VRJRCGARBF)
    must read as an ambiguity naming both directories, not the generic "no run dir"
    an operator would otherwise mistake for a typo'd or expired run-id."""
    from types import SimpleNamespace
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    real = T.create_run_dir("run-status-dup", date="2026-07-04")
    planted = T.create_run_dir("run-status-dup", date="2099-01-01")

    rc = agentctl.cmd_status(SimpleNamespace(run_id="run-status-dup"))

    err = capsys.readouterr().err
    assert rc == 1
    assert "ambiguous" in err
    assert str(real) in err and str(planted) in err
    assert "no run dir for" not in err


# --- --on: no inference from ambient state; --pr requires it explicitly ----
# issue_01M1RZ3DTAN0PE1DDR3KMK2YVD: `agentctl spawn security-reviewer --pr 488`
# run inside the agent-platform checkout read PR 488 from convivy/constance —
# `--on` defaulted to the literal string "constance" regardless of cwd. That
# time it refused (constance#488 was merged); had constance carried an OPEN
# PR #488 the dispatch would have pinned a reviewer to the wrong repo's
# branch and commit.
#
# ROUND 1 (security review, PR #723): the first fix derived the repo from
# `git remote get-url origin`, which lives in the repo's SHARED
# `.git/config` — a linked worktree can rewrite what every other worktree of
# the same repo, including the primary checkout, reads back.
#
# ROUND 2: replaced `origin` with `git rev-parse --git-common-dir`, which for
# a linked worktree is itself sourced from
# `<primary>/.git/worktrees/<name>/commondir` — a file in that same shared,
# worker-writable `.git` tree — and separately inherited GIT_DIR /
# GIT_COMMON_DIR / GIT_WORK_TREE from the process environment unscrubbed.
#
# ROUND 3: removed the git call and read the resolved cwd PATH instead — but
# `Path.cwd()` is re-resolved by the kernel on every call, not cached from
# `chdir` time, so renaming an ancestor of another live process's cwd (an
# ordinary same-user write under `worktrees/`, no sandbox between workers)
# changes what that OTHER process's next spawn resolves to, with zero
# interaction from it.
#
# ROUND 4: every one of the three inferences read state some other same-user
# process can write, so this round removes the inference instead of
# hardening it again. `--on` omitted stays "constance" — unchanged from
# main's behaviour before PR #723 — for every spawn except one: `--pr N`
# needs to know which repo's PR N to read, so it refuses rather than
# guessing when `--on` is missing.

def _setup_registered_primary(agentctl, monkeypatch, root, name):
    """A `root/<name>` primary repo with one commit, registered as a dispatch
    target by pointing `W.CONVIVY_ROOT` at `root` — the same registry
    `W.is_dispatch_target` / `_primary_for` use to validate `--on`. Used here
    only to prove the cwd is NEVER consulted, even from inside one of these."""
    for k, v in {"GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@example.com",
                "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@example.com",
                "GIT_CONFIG_GLOBAL": os.devnull, "GIT_CONFIG_NOSYSTEM": "1"}.items():
        monkeypatch.setenv(k, v)
    primary = root / name
    primary.mkdir(parents=True, exist_ok=True)
    _git_ok(primary, "init", "-q", "-b", "main")
    (primary / "README.md").write_text("x\n")
    _git_ok(primary, "add", "-A")
    _git_ok(primary, "commit", "-q", "-m", "one")
    monkeypatch.setattr(agentctl.W, "CONVIVY_ROOT", root)
    return primary


def _spawn_args(**overrides):
    """Minimal args.Namespace for `_spawn_dispatch`, defaulting to a plain
    `agentctl spawn reviewer --task ...` with no --on and no --pr."""
    import types
    base = dict(agent="reviewer", task="review it", on=None, parent=None,
                agents_dir=None, model=None, reason=None, issue=None,
                pr=None, review_sha=None, profile=None)
    base.update(overrides)
    return types.SimpleNamespace(**base)


