# --- CQ·418: a per-run GitHub credential, minted before any side effect --------------

def _stub_spawn_preflight(agentctl, monkeypatch):
    """The minimal stub set that lets a plain `reviewer --task ...` dispatch (no --pr,
    no --issue, no --model override) reach the worktree-allocation `try:` block, without
    touching the real Library, registry or filesystem along the way."""
    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent",
                        lambda name, repo=None, agents_dir=None: {"model_alias": "sonnet"})
    monkeypatch.setattr(agentctl, "default_profile", lambda repo, name: f"{repo}/daytime")


def test_mint_failure_refuses_before_the_worktree_is_allocated(agentctl, monkeypatch, capsys):
    """A minting failure must refuse the spawn before `W.allocate_worktree`/
    `allocate_on_branch` — the first real side effect — ever runs, and must never fall
    back to spawning without a token. Fails against a planted implementation that mints
    after the worktree already exists, or that swallows the failure and proceeds."""
    _stub_spawn_preflight(agentctl, monkeypatch)
    monkeypatch.setattr(agentctl, "_mint_run_github_token",
                        lambda repo: (None, "no App key at /nonexistent/bosun-app.pem"))

    def _boom(*a, **kw):
        raise AssertionError("the worktree must not be allocated after a mint failure")
    monkeypatch.setattr(agentctl.W, "allocate_worktree", _boom)
    monkeypatch.setattr(agentctl.W, "allocate_on_branch", _boom)

    args = _spawn_args(agent="reviewer", task="review it")
    exit_code, run_id = agentctl._spawn_dispatch(args)

    assert exit_code != 0
    assert run_id is None
    err = capsys.readouterr().err
    assert "no App key" in err
    assert "operator's git credential helper" in err


def test_a_dry_run_never_calls_the_real_mint(agentctl, monkeypatch):
    """`--dry-run` mints nothing — the one caller-reachable path that must never invoke
    `_mint_run_github_token`, which is what can reach the network or the App's private
    key. Stopped at worktree allocation (stubbed to raise a sentinel) rather than run to
    completion, since dry-run's own contract still allocates a worktree path; only the
    mint itself is asserted never to have run."""
    _stub_spawn_preflight(agentctl, monkeypatch)

    def _boom(*a, **kw):
        raise AssertionError("a dry run must never call the real mint")
    monkeypatch.setattr(agentctl, "_mint_run_github_token", _boom)

    def _stop(*a, **kw):
        raise _StoppedAtWorktreeAllocation()
    monkeypatch.setattr(agentctl.W, "allocate_worktree", _stop)
    monkeypatch.setattr(agentctl.W, "allocate_on_branch", _stop)

    args = _spawn_args(agent="reviewer", task="review it", dry_run=True)
    with pytest.raises(_StoppedAtWorktreeAllocation):
        agentctl._spawn_dispatch(args)


def test_a_real_spawn_does_call_the_mint_before_worktree_allocation(agentctl, monkeypatch):
    """The mirror of the dry-run test: a real (non-dry-run) dispatch DOES mint before
    the worktree is allocated — proving the dry-run skip above is actually gated on
    `dry_run`, not on the mint call having been removed altogether."""
    _stub_spawn_preflight(agentctl, monkeypatch)
