def test_approve_blocked_when_ci_cannot_be_read(agentctl, monkeypatch):
    """FAIL CLOSED. A missing answer is not a green one — the failure mode this whole
    change exists to close is a verdict outrunning its evidence."""
    def boom(pr, fields, repo=None):
        raise RuntimeError("gh: API rate limit exceeded")
    monkeypatch.setattr(agentctl, "_gh_pr_json", boom)
    code, why = agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA)
    assert "could not read CI" in why and "--ignore-ci" in why
    # A transient API blip is RETRYABLE and must be distinguishable from a real red
    # check, so an orchestrator can retry the first and route the second.
    assert code == agentctl.CI_BLOCK_UNKNOWN
    assert agentctl.CI_BLOCK_UNKNOWN != agentctl.CI_BLOCK_RED


def test_approve_blocked_when_head_moved_under_the_reviewer(agentctl, monkeypatch):
    """The rollup describes the head. If the head moved, it is not evidence about the
    commit actually reviewed — and that APPROVE fails the merge gate anyway (ARCH-184)."""
    new_head = "9999999999999999999999999999999999999999"
    _patch_view(agentctl, monkeypatch, _GREEN, head=new_head)
    code, why = agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA)
    assert code == agentctl.CI_BLOCK_RED and "head moved" in why
    # THE RECOVERY PATH MUST NOT BE THE LOOP. The advice names --pr, not a sha: `spawn
    # --pr` pins the live head itself, so no abbreviated sha can reach AGENTCTL_REVIEW_SHA
    # and fire "head moved" again. A --review-sha dispatch with no PR records no PR, so
    # its stamp would never count (CQ·399).
    assert "--pr 1" in why and "--review-sha" not in why


def test_no_ci_at_all_is_vacuously_green(agentctl, monkeypatch):
    """Prose/knowledge repos have no required checks. They must keep working — this
    matches _ci_is_green's existing contract rather than inventing a second rule."""
    _patch_view(agentctl, monkeypatch, [])
    assert agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA) is None


def test_pending_wait_polls_rest_and_reads_graphql_only_on_settle(agentctl, monkeypatch):
    """The optimization proper. While REST reports the suite still moving, the loop
    must NOT spend a GraphQL read; it re-reads the authoritative GraphQL rollup only
    once REST reports settled. This is what keeps a long pending suite off the shared
    GraphQL pool a day of review work exhausts (REST has its own idle pool)."""
    graphql_reads = []

    def gql(pr, fields, repo=None):
        graphql_reads.append(1)
        rollup = ([{"name": "tests", "status": "IN_PROGRESS"}] if len(graphql_reads) == 1
                  else [{"name": "tests", "status": "COMPLETED", "conclusion": "SUCCESS"}])
        return {"statusCheckRollup": rollup, "headRefOid": _SHA}
    monkeypatch.setattr(agentctl, "_gh_pr_json", gql)
    monkeypatch.setattr(agentctl.time, "sleep", lambda _s: None)

    rest_probes = []
    settled_seq = [False, False, True]

    def rest(repo, sha):
        rest_probes.append(1)
        return settled_seq[min(len(rest_probes) - 1, len(settled_seq) - 1)]
    monkeypatch.setattr(agentctl, "_ci_settled_rest", rest)

    assert agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA,
                                           wait_secs=600) is None
    assert len(graphql_reads) == 2, "exactly two GraphQL reads: initial pending + post-settle"
    assert len(rest_probes) == 3, "REST carried the polling while the suite ran, not GraphQL"


def test_pending_wait_falls_back_to_graphql_when_rest_unreadable(agentctl, monkeypatch):
    """REST failing must not stall the wait. When _ci_settled_rest returns None,
    _await_ci_settle returns after one sleep and the loop re-reads GraphQL, exactly
    the pre-change cadence — an unreadable REST budget is a fallback, never a wedge."""
    views = [
        [{"name": "tests", "status": "IN_PROGRESS"}],
        [{"name": "tests", "status": "COMPLETED", "conclusion": "SUCCESS"}],
    ]
    calls = []

    def fake(pr, fields, repo=None):
        calls.append(1)
        return {"statusCheckRollup": views[min(len(calls) - 1, len(views) - 1)],
                "headRefOid": _SHA}
    monkeypatch.setattr(agentctl, "_gh_pr_json", fake)
    monkeypatch.setattr(agentctl.time, "sleep", lambda _s: None)
    monkeypatch.setattr(agentctl, "_ci_settled_rest", lambda repo, sha: None)
    assert agentctl._approve_blocked_by_ci(pr="1", repo="r/r", reviewed_commit=_SHA,
                                           wait_secs=60) is None
    assert len(calls) == 2, "falls back to a GraphQL re-read when REST cannot be read"


def test_ci_settled_rest_true_when_completed_and_no_legacy_status(agentctl, monkeypatch):
    """The live-data case that MUST be right, or every finished PR reads as
    forever-running: all check runs completed, and an Actions-only repo's combined
    status is `pending` with ZERO contexts (its permanent default). Empty-and-pending
    counts as settled."""
    def api(path):
        if "check-runs" in path:
            return {"check_runs": [{"name": "python", "status": "completed",
                                    "conclusion": "success"}]}
        return {"state": "pending", "statuses": []}
    monkeypatch.setattr(agentctl, "_gh_api_json", api)
    assert agentctl._ci_settled_rest("o/r", _SHA) is True


