# --- publish is PR-aware (ARCH-347, footgun 1) -------------------------------

def _repo_on_branch(tmp_path, branch):
    """A real git repo checked out on `branch` with one commit — the worktree publish
    inspects. `.git` is a directory here (a plain repo), which publish accepts."""
    import subprocess
    wt = tmp_path / "wt"
    wt.mkdir()

    def g(*a):
        return subprocess.run(
            ["git", "-C", str(wt), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True)

    g("init", "-q", "-b", branch)
    (wt / "f.py").write_text("v = 1\n")
    g("add", ".")
    g("commit", "-qm", "c1")
    return wt


def _fake_gh(tmp_path, monkeypatch, head_ref_name):
    """A `gh` shim on PATH that answers `gh pr view … -q .headRefName` with a fixed
    branch — lets publish's PR-branch resolve run without a network or a real PR."""
    import os
    gh = tmp_path / "gh"
    gh.write_text("#!/bin/sh\necho '%s'\n" % head_ref_name)
    gh.chmod(0o755)
    monkeypatch.setenv("PATH", f"{tmp_path}:{os.environ['PATH']}")


def test_publish_refuses_when_worktree_branch_is_not_the_pr_branch(agentctl, tmp_path,
                                                                   monkeypatch, capsys):
    """The #923 footgun: a round-fix on `agent/coder-roundfix-x` while PR #923 is on
    `agent/coder-fix-y`. Publishing the former FF's a branch no PR points at and reports
    success, leaving the PR head stale. The guard must REFUSE before any push."""
    import types
    wt = _repo_on_branch(tmp_path, "agent/coder-roundfix-x")
    _fake_gh(tmp_path, monkeypatch, "agent/coder-fix-y")           # PR is on a DIFFERENT branch
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    args = types.SimpleNamespace(worktree=str(wt), run=None, repo=None, purpose=None,
                                 pr="923", dry_run=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err and "no PR points at" in err


def test_publish_infers_pr_from_pr_link_json_and_refuses_mismatch(agentctl, tmp_path,
                                                                  monkeypatch, capsys):
    """The REAL orchestration path: `publish --run <id>` with no explicit --pr, where the
    run was started by `spawn --pr N` (which stamps pr-link.json). publish must READ that
    link, resolve the PR branch, and refuse a divergent worktree — the explicit-`--pr`
    tests don't exercise the pr-link.json inference or the `_find_run_dir` hop."""
    import json
    import types
    wt = _repo_on_branch(tmp_path, "agent/coder-roundfix-x")
    _fake_gh(tmp_path, monkeypatch, "agent/coder-fix-y")          # PR is on a DIFFERENT branch
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    run_dir = tmp_path / "run-rf"
    run_dir.mkdir()
    (run_dir / "pr-link.json").write_text(json.dumps({"pr_number": 923,
                                                      "branch": "agent/coder-fix-y"}))
    monkeypatch.setattr(agentctl, "_find_run_dir", lambda rid: run_dir)
    monkeypatch.setattr(agentctl, "_resolve_worktree_by_run", lambda rid: wt)
    args = types.SimpleNamespace(worktree=None, run="run-rf", repo=None, purpose=None,
                                 pr=None, dry_run=False)          # PR inferred, not passed
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err and "923" in err


def test_publish_allows_when_worktree_branch_matches_the_pr_branch(agentctl, tmp_path,
                                                                   monkeypatch, capsys):
    """The guard must be a scalpel, not a wall: when the worktree IS on the PR branch it
    passes cleanly through to the normal push path (asserted here via --dry-run, which
    returns 0 only after the branch check has passed)."""
    import types
    wt = _repo_on_branch(tmp_path, "agent/coder-fix-y")
    _fake_gh(tmp_path, monkeypatch, "agent/coder-fix-y")           # same branch → match
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    args = types.SimpleNamespace(worktree=str(wt), run=None, repo=None, purpose=None,
                                 pr="923", dry_run=True)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 0
    assert "REFUSED" not in err


def test_publish_refused_message_names_on_with_the_resolved_repo(agentctl, tmp_path,
                                                                  monkeypatch, capsys):
    """The mismatch REFUSED message tells the operator to dispatch the round-fix with
    `agentctl spawn <coder> --pr N` — a command `spawn` itself now refuses without `--on`
    naming the repo (PR #723 round 4: `--pr` requires `--on` explicitly, since every
    ambient-state inference `spawn` could have used to guess it was forgeable). The
    printed suggestion must carry `--on <repo>`, using the repo `publish` already
    resolved for this worktree (`args.repo`, else the worktree-naming convention), not a
    bare placeholder that fails exactly as printed."""
    import types
    wt = _repo_on_branch(tmp_path, "agent/coder-roundfix-x")
    _fake_gh(tmp_path, monkeypatch, "agent/coder-fix-y")
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    args = types.SimpleNamespace(worktree=str(wt), run=None, repo=None, purpose=None,
                                 pr="923", dry_run=False)
    rc = agentctl.cmd_publish(args)
    err = capsys.readouterr().err
    assert rc == 1
    assert f"--on {wt.name} --pr 923" in err


# --- publish refuses an empty worktree (vivy co, 2026-07-18) ------------------
#
# The bug this guards: a worker writes into the main checkout instead of its worktree,
# leaving the worktree with zero commits beyond base. publish's in-sync early-return then
# prints "already in sync" and exits 0 — success over lost work. Three collisions in one
# vivy session, once an entire 293-line slice, plus a crossed PR body on merged #978.


def _repo_with_base(tmp_path, branch, *, commits_beyond_base=0):
    """A repo with a real `main` base and a `branch` cut from it, so publish's base
    resolution finds something to count against. `commits_beyond_base` controls exactly
    the quantity the guard keys on."""
    import subprocess
    wt = tmp_path / "wt"
    wt.mkdir()

    def g(*a):
        return subprocess.run(
            ["git", "-C", str(wt), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True)

    g("init", "-q", "-b", "main")
    (wt / "f.py").write_text("v = 1\n")
    g("add", ".")
    g("commit", "-qm", "base")
    if branch != "main":
        g("checkout", "-q", "-b", branch)
    for i in range(commits_beyond_base):
        (wt / f"w{i}.py").write_text(f"w = {i}\n")
        g("add", ".")
        g("commit", "-qm", f"work {i}")
    return wt


def test_publish_refuses_inside_a_dispatched_runs_own_object_redirected_env(
        agentctl, tmp_path, monkeypatch, capsys):
    """CQ·477 (run-421dd904, 2026-10-12): a coder's own `agentctl publish`, run from
    inside its own live run's shell on its own worktree, reached
    `import_leftover_private_objects`, which found nothing missing from the shared
    store and ran `shutil.rmtree` on the private store that SAME run's own git was
    still pointed at — breaking every git call for the rest of the run.
    `publish` must refuse up front, before any git call or import, whenever its own
    process carries the redirect a dispatched run's shell always does
    (`dispatch_env`'s `GIT_OBJECT_DIRECTORY`/`GIT_ALTERNATE_OBJECT_DIRECTORIES`).
    `publish` is the orchestrator's own step, run after the run has ended."""
    monkeypatch.setenv("GIT_OBJECT_DIRECTORY", str(tmp_path / "private"))
    calls = []
    monkeypatch.setattr(agentctl.subprocess, "run",
                        lambda *a, **k: calls.append(("subprocess.run", a, k)))
    monkeypatch.setattr(agentctl.W, "import_leftover_private_objects",
                        lambda *a, **k: calls.append(("import_leftover_private_objects", a, k)))
    monkeypatch.setattr(agentctl.RS, "import_private_objects",
                        lambda *a, **k: calls.append(("import_private_objects", a, k)))

    # A worktree that doesn't even exist — the refusal must fire before this
    # (or any other) path is even resolved, let alone touched.
    rc = agentctl.cmd_publish(_publish_args(tmp_path / "nonexistent-wt"))

    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err
    assert "orchestrator's step" in err
    assert calls == [], "no subprocess call and no import before the refusal"


def _publish_args(wt, **over):
    import types
    base = dict(worktree=str(wt), run=None, repo=None, purpose=None, pr=None, dry_run=True)
    base.update(over)
    return types.SimpleNamespace(**base)


def test_publish_refuses_a_worktree_with_no_commits_beyond_base(agentctl, tmp_path,
                                                                monkeypatch, capsys):
    """The vivy #978 class: the worktree was allocated and its branch cut, but the worker
    wrote into the main checkout, so nothing landed here. Publishing must REFUSE rather
    than report the in-sync success that made this silent."""
    wt = _repo_with_base(tmp_path, "agent/coder-x", commits_beyond_base=0)
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    rc = agentctl.cmd_publish(_publish_args(wt))
    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err and "NO commits beyond" in err
    # The message must point at the actual cause, or the operator re-runs it and moves on.
    assert "main checkout" in err


def test_publish_refuses_when_the_worker_ran_on_the_base_branch_itself(agentctl, tmp_path,
                                                                       monkeypatch, capsys):
    """The other shape of the same bug: the worker ran in the main checkout on `main`, so
    HEAD *is* base. Zero commits beyond base catches this too — and it is the shape that
    makes publish's `remote_before == head` early-return report success."""
    wt = _repo_with_base(tmp_path, "main", commits_beyond_base=0)
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    rc = agentctl.cmd_publish(_publish_args(wt))
    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err and "NO commits beyond" in err


def test_publish_allows_a_worktree_that_carries_work(agentctl, tmp_path, monkeypatch,
                                                     capsys):
    """A scalpel, not a wall: one commit beyond base is a normal publish and must pass
    through untouched. Without this the guard would break every real dispatch."""
    wt = _repo_with_base(tmp_path, "agent/coder-x", commits_beyond_base=1)
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    rc = agentctl.cmd_publish(_publish_args(wt))
    err = capsys.readouterr().err
    assert rc == 0
    assert "REFUSED" not in err


def test_publish_does_not_block_when_the_base_cannot_be_resolved(agentctl, tmp_path,
                                                                 monkeypatch, capsys):
    """Fail-open on an UNDETERMINABLE base. `_repo_on_branch` has no origin and no `main`,
    so there is nothing to count against — the guard must skip rather than refuse a
    publish on a check it could not make."""
    wt = _repo_on_branch(tmp_path, "agent/coder-x")
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    rc = agentctl.cmd_publish(_publish_args(wt))
    err = capsys.readouterr().err
    assert rc == 0
    assert "REFUSED" not in err


def test_publish_pushes_a_commit_the_run_made_in_its_own_private_object_store(
        agentctl, tmp_path, monkeypatch, capsys):
    """Caller 1 of knowledge#793 round 6's item 3: `agentctl publish` runs in a later,
    unsandboxed `agentctl` invocation, with no object-store env of its own — it finds the
    run's commit only because `import_private_objects` already rejoined it into the shared
    store before this ever runs (`_run_session`'s own post-exit step, simulated here
    directly). A real (non-dry-run) push, so the bare "origin" below must receive the
    actual blob content, not just a moved ref."""
    import run_sandbox as RS
    origin = tmp_path / "origin.git"
    subprocess.run(["git", "init", "-q", "--bare", "-b", "main", str(origin)], check=True)
    primary = tmp_path / "primary"
    subprocess.run(["git", "init", "-q", "-b", "main", str(primary)], check=True)

    def g(*a, cwd=primary, env=None):
        return subprocess.run(
            ["git", "-C", str(cwd), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True, env=env)

    g("commit", "-q", "--allow-empty", "-m", "base")
    g("remote", "add", "origin", str(origin))
    g("push", "-q", "origin", "main")
    wt = tmp_path / "wt"
    g("worktree", "add", "-q", "-b", "agent/private-store-test", str(wt))

    git_dir = RS.git_common_dir(wt)
    private_dir = RS.run_private_objects_dir(wt, git_dir)
    private_dir.mkdir()
    env = {**os.environ, "GIT_OBJECT_DIRECTORY": str(private_dir),
          "GIT_ALTERNATE_OBJECT_DIRECTORIES": str(git_dir / "objects")}
    (wt / "f.py").write_text("made in the private store\n")
    g("add", ".", cwd=wt, env=env)
    g("commit", "-qm", "private-store work", cwd=wt, env=env)
    head = g("rev-parse", "HEAD", cwd=wt).stdout.strip()
    # Simulates _run_session's own post-exit step, between the run's claude exiting and
    # _finalize_run — this is what makes the commit visible to the SEPARATE, later,
    # unsandboxed `agentctl publish` invocation below.
    RS.import_private_objects(git_dir, private_dir)

    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    monkeypatch.setattr(agentctl, "_content_scan_gate", lambda *a, **k: 0)
    rc = agentctl.cmd_publish(_publish_args(wt, dry_run=False))
    err = capsys.readouterr().err
    assert rc == 0, err
    assert "REFUSED" not in err and "FAILED" not in err

    shown = subprocess.run(
        ["git", "--git-dir", str(origin), "show", f"{head}:f.py"],
        capture_output=True, text=True, check=True).stdout
    assert shown == "made in the private store\n"


def test_publish_imports_a_commit_its_dispatcher_died_before_importing(
        agentctl, tmp_path, monkeypatch, capsys):
    """Round 7 (reviewer round 6, blocking): the test above assumes the dispatcher's own
    end-of-run `import_private_objects` call already ran before `publish` does. If the
    dispatcher process itself died first (a documented recurring incident, P1b
    2026-07-04) that call never happens, and `publish` — a separate, later, unsandboxed
    invocation with no object-store env of its own — must fold the leftover private
    store in itself, or the push (and every read before it) fails against a commit
    object it cannot resolve. Identical fixture to the test above, with the
    `RS.import_private_objects` call deliberately OMITTED before `cmd_publish` runs."""
    import run_sandbox as RS
    origin = tmp_path / "origin.git"
    subprocess.run(["git", "init", "-q", "--bare", "-b", "main", str(origin)], check=True)
    primary = tmp_path / "primary"
    subprocess.run(["git", "init", "-q", "-b", "main", str(primary)], check=True)

    def g(*a, cwd=primary, env=None):
        return subprocess.run(
            ["git", "-C", str(cwd), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True, env=env)

    g("commit", "-q", "--allow-empty", "-m", "base")
    g("remote", "add", "origin", str(origin))
    g("push", "-q", "origin", "main")
    wt = tmp_path / "wt"
    g("worktree", "add", "-q", "-b", "agent/dead-dispatcher-test", str(wt))

    git_dir = RS.git_common_dir(wt)
    private_dir = RS.run_private_objects_dir(wt, git_dir)
    private_dir.mkdir()
    env = {**os.environ, "GIT_OBJECT_DIRECTORY": str(private_dir),
          "GIT_ALTERNATE_OBJECT_DIRECTORIES": str(git_dir / "objects")}
    (wt / "f.py").write_text("made in the private store, dispatcher died\n")
    g("add", ".", cwd=wt, env=env)
    g("commit", "-qm", "private-store work, never imported", cwd=wt, env=env)
    head = g("rev-parse", "HEAD", cwd=wt).stdout.strip()
    # Deliberately NO RS.import_private_objects call — the dispatcher never ran it.

    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    monkeypatch.setattr(agentctl, "_content_scan_gate", lambda *a, **k: 0)
    rc = agentctl.cmd_publish(_publish_args(wt, dry_run=False))
    err = capsys.readouterr().err
    assert rc == 0, err
    assert "REFUSED" not in err and "FAILED" not in err

    shown = subprocess.run(
        ["git", "--git-dir", str(origin), "show", f"{head}:f.py"],
        capture_output=True, text=True, check=True).stdout
    assert shown == "made in the private store, dispatcher died\n"


def test_publish_imports_private_objects_only_when_head_is_unreadable(
        agentctl, tmp_path, monkeypatch, capsys):
    """The targeted gate (issue_01M4RP1K026XJE740DMQ7AP31M, round 2 of the
    knowledge#793 family): publish imports the run's private objects when, and only
    when, `git cat-file -e HEAD^{commit}` fails — the exact check `rev-parse HEAD`
    cannot make, since it reads the ref file and never the object. Same fixture as
    the test above; this one SPIES on `RS.import_private_objects` (delegating to the
    real call) to pin that it ran, and with `remove=False` — a push that failed
    right after must not have already deleted the one copy of the commit it just
    proved exists."""
    import run_sandbox as RS
    origin = tmp_path / "origin.git"
    subprocess.run(["git", "init", "-q", "--bare", "-b", "main", str(origin)], check=True)
    primary = tmp_path / "primary"
    subprocess.run(["git", "init", "-q", "-b", "main", str(primary)], check=True)

    def g(*a, cwd=primary, env=None):
        return subprocess.run(
            ["git", "-C", str(cwd), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True, env=env)

    g("commit", "-q", "--allow-empty", "-m", "base")
    g("remote", "add", "origin", str(origin))
    g("push", "-q", "origin", "main")
    wt = tmp_path / "wt"
    g("worktree", "add", "-q", "-b", "agent/unreadable-head-test", str(wt))

    git_dir = RS.git_common_dir(wt)
    private_dir = RS.run_private_objects_dir(wt, git_dir)
    private_dir.mkdir()
    # A dispatched test run's OWN PATH carries a `git` wrapper (`dispatch_env.py`)
    # that drops GIT_OBJECT_DIRECTORY/GIT_ALTERNATE_OBJECT_DIRECTORIES for any
    # repository other than that run's own (compared against
    # AGENTCTL_OWN_GIT_COMMON_DIR) — this fixture's `wt` is never that run's own
    # repository, so without this the wrapper would silence the redirect for
    # EVERY git call below, this test's own setup and `RS.import_private_objects`'s
    # real internal calls alike, and "made only in the private store" would
    # silently land in the shared store like any other commit. Pointing the var at
    # THIS fixture's own `git_dir` makes every call below match it instead.
    monkeypatch.setenv("AGENTCTL_OWN_GIT_COMMON_DIR", str(git_dir))
    env = {**os.environ, "GIT_OBJECT_DIRECTORY": str(private_dir),
          "GIT_ALTERNATE_OBJECT_DIRECTORIES": str(git_dir / "objects")}
    (wt / "f.py").write_text("made in the private store only\n")
    g("add", ".", cwd=wt, env=env)
    g("commit", "-qm", "private-store work", cwd=wt, env=env)
    head = g("rev-parse", "HEAD", cwd=wt).stdout.strip()
    # No import call at all yet — HEAD is unreadable from the shared store.

    calls = []
    real_import = RS.import_private_objects

    def _spy(gd, pd, **kw):
        calls.append((gd, pd, kw))
        return real_import(gd, pd, **kw)
    monkeypatch.setattr(agentctl.RS, "import_private_objects", _spy)
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    monkeypatch.setattr(agentctl, "_content_scan_gate", lambda *a, **k: 0)
    rc = agentctl.cmd_publish(_publish_args(wt, dry_run=False))
    err = capsys.readouterr().err
    assert rc == 0, err
    assert "REFUSED" not in err and "FAILED" not in err

    assert calls == [(git_dir, private_dir, {"remove": False})]
    shown = subprocess.run(
        ["git", "--git-dir", str(origin), "show", f"{head}:f.py"],
        capture_output=True, text=True, check=True).stdout
    assert shown == "made in the private store only\n"


def test_publish_does_not_import_when_head_is_already_readable(
        agentctl, tmp_path, monkeypatch, capsys):
    """The other half of the same gate: an ORDINARY push, with no dead run and no
    private store involved at all, must not fork the four git subprocesses
    `import_private_objects` makes on every single publish — only when HEAD is
    actually unreadable."""
    origin = tmp_path / "origin.git"
    subprocess.run(["git", "init", "-q", "--bare", "-b", "main", str(origin)], check=True)
    primary = tmp_path / "primary"
    subprocess.run(["git", "init", "-q", "-b", "main", str(primary)], check=True)

    def g(*a, cwd=primary, env=None):
        return subprocess.run(
            ["git", "-C", str(cwd), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True, env=env)

    g("commit", "-q", "--allow-empty", "-m", "base")
    g("remote", "add", "origin", str(origin))
    g("push", "-q", "origin", "main")
    wt = tmp_path / "wt"
    g("worktree", "add", "-q", "-b", "agent/readable-head-test", str(wt))
    (wt / "f.py").write_text("made directly in the shared store\n")
    g("add", ".", cwd=wt)
    g("commit", "-qm", "ordinary work", cwd=wt)
    head = g("rev-parse", "HEAD", cwd=wt).stdout.strip()
    # HEAD is readable from the shared store straight away — no dead run involved.

    calls = []
    monkeypatch.setattr(agentctl.RS, "import_private_objects",
                        lambda *a, **k: calls.append((a, k)))
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    monkeypatch.setattr(agentctl, "_content_scan_gate", lambda *a, **k: 0)
    rc = agentctl.cmd_publish(_publish_args(wt, dry_run=False))
    err = capsys.readouterr().err
    assert rc == 0, err
    assert "REFUSED" not in err and "FAILED" not in err
    assert calls == [], "head was already readable — the import must not be called"

    shown = subprocess.run(
        ["git", "--git-dir", str(origin), "show", f"{head}:f.py"],
        capture_output=True, text=True, check=True).stdout
    assert shown == "made directly in the shared store\n"


def test_default_base_falls_back_to_main_when_origin_head_is_unset(agentctl):
    """`origin/HEAD` is unset on plenty of clones; abbrev-ref then yields "HEAD", which is
    not a branch. pr-open and the empty-worktree guard both read this."""
    class R:
        def __init__(self, out):
            self.stdout = out
    assert agentctl._default_base(lambda *a: R("HEAD\n")) == "main"
    assert agentctl._default_base(lambda *a: R("origin/trunk\n")) == "trunk"
    assert agentctl._default_base(lambda *a: R("\n")) == "main"


# --- session-dir (agent-platform#141) -----------------------------------------
#
# The naming bug this replaces: a vivy co composed `co-vivy-<HHMM>` itself,
# inferred local time by converting a UTC instant through "Mountain Time", picked
# up a DST offset Arizona does not observe, and named its handoff dir an hour
# into the future. The skill already told it to call `date`; it skipped that. So
# these pin that the NAME now comes from one code path, not from a model.


def _session_dir(agentctl, monkeypatch, tmp_path, product="vivy", print_="path", env=None):
    monkeypatch.setattr(agentctl.T, "RUNS_ROOT", tmp_path)
    monkeypatch.delenv(agentctl.SESSION_DIR_ENV, raising=False)
    # A pytest run inside a co session inherits CLAUDE_CODE_SESSION_ID, which
    # would route these calls through the per-session pointer under the real HOME.
    monkeypatch.delenv("CLAUDE_CODE_SESSION_ID", raising=False)
    for k, v in (env or {}).items():
        monkeypatch.setenv(k, v)
    args = type("A", (), {"product": product, "print_": print_})()
    return args


def test_session_dir_creates_the_canonical_dir_and_prints_it(agentctl, monkeypatch,
                                                             tmp_path, capsys):
    args = _session_dir(agentctl, monkeypatch, tmp_path)
    assert agentctl.cmd_session_dir(args) == 0
    out = capsys.readouterr().out.strip()
    d = Path(out)
    assert d.is_dir()
    assert d.parent.name == agentctl.T.platform_day()
    assert d.name.startswith("co-vivy-")


def test_session_dir_name_uses_the_local_clock_not_a_utc_conversion(agentctl, monkeypatch,
                                                                    tmp_path, capsys):
    """The #141 regression, pinned: the HHMM in the name must match this machine's
    own local wall clock. A dir name computed from a converted UTC instant is
    exactly what produced a name an hour into the future."""
    # The clock is frozen rather than read twice: reading it again after the
    # command runs makes this fail whenever the two reads straddle a minute
    # boundary, and a spurious failure on the #141 regression pin is exactly the
    # noise that would let a real regression through.
    # NAIVE, deliberately. datetime.now() returns naive local time, and the code
    # under test calls .astimezone() on it to attach the local offset. Freezing an
    # AWARE value instead makes .astimezone() CONVERT it: on a UTC runner
    # 23:22-07:00 becomes 06:22, so the pin passed on this machine (whose zone
    # already matched the frozen offset) and failed on CI — precisely the runner
    # where it needs to catch a reintroduced regression.
    frozen = datetime(2026, 7, 18, 23, 22)

    class _Clock(datetime):
        @classmethod
        def now(cls, tz=None):
            return frozen if tz is None else frozen.astimezone(tz)

    monkeypatch.setattr(agentctl, "datetime", _Clock)
    args = _session_dir(agentctl, monkeypatch, tmp_path)
    agentctl.cmd_session_dir(args)
    d = Path(capsys.readouterr().out.strip())
    # 23:22 MST — the exact wall-clock the #141 session rendered as 23:22 MDT
    # after converting a UTC instant through a DST-observing zone.
    assert d.name == "co-vivy-2322"
    assert d.parent.name == "2026-07-18"


def test_session_dir_is_idempotent_when_the_env_pins_it(agentctl, monkeypatch,
                                                        tmp_path, capsys):
    """handoff-leave and a claim taken hours earlier must agree on the session's
    identity — re-deriving it from the clock would not."""
    pinned = tmp_path / "pinned-session"
    pinned.mkdir()
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={agentctl.SESSION_DIR_ENV: str(pinned)})
    assert agentctl.cmd_session_dir(args) == 0
    assert capsys.readouterr().out.strip() == str(pinned)
    # and it did NOT create a second, clock-named directory
    assert not list(tmp_path.glob("*/co-vivy-*"))


def test_session_dir_rejects_a_pinned_path_that_is_not_a_directory(agentctl, monkeypatch,
                                                                   tmp_path, capsys):
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={agentctl.SESSION_DIR_ENV: str(tmp_path / "nope")})
    assert agentctl.cmd_session_dir(args) == 1


def test_two_sessions_in_the_same_minute_get_separate_dirs(agentctl, monkeypatch,
                                                           tmp_path, capsys):
    """Sharing one directory would interleave two sessions' handoffs."""
    args = _session_dir(agentctl, monkeypatch, tmp_path)
    agentctl.cmd_session_dir(args)
    first = capsys.readouterr().out.strip()
    agentctl.cmd_session_dir(args)
    second = capsys.readouterr().out.strip()
    assert first != second
    assert Path(first).is_dir() and Path(second).is_dir()


def test_session_dir_print_id_is_date_qualified_and_unique(agentctl, monkeypatch,
                                                           tmp_path, capsys):
    """The claim owner. A bare `co-vivy-2322` repeats daily, so it cannot identify
    a session; qualifying it with the run-dir date makes it unique and sortable."""
    args = _session_dir(agentctl, monkeypatch, tmp_path, print_="id")
    assert agentctl.cmd_session_dir(args) == 0
    sid = capsys.readouterr().out.strip()
    assert sid.startswith(f"{agentctl.T.platform_day()}/co-vivy-")


def test_session_dir_rejects_a_product_that_is_not_a_slug(agentctl, monkeypatch,
                                                          tmp_path, capsys):
    """`product` lands in a filesystem path, so a path-traversing or shell-shaped
    value must be refused rather than sanitized into something surprising."""
    for bad in ("Bad Product", "../escape", "vivy/../..", "", "  "):
        args = _session_dir(agentctl, monkeypatch, tmp_path, product=bad)
        assert agentctl.cmd_session_dir(args) == 2, bad


def test_one_claude_session_gets_the_same_directory_on_every_call(agentctl, monkeypatch,
                                                                  tmp_path, capsys):
    """`/handoff-leave` and `bin/co-rollover` each ask for the session's directory.
    A second call that minted another one would leave the rollover reading a
    different directory from the one the handoff was written into."""
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(tmp_path / "home"),
                             "CLAUDE_CODE_SESSION_ID": "sess-agentctl-1"})
    assert agentctl.cmd_session_dir(args) == 0
    first = capsys.readouterr().out.strip()
    assert agentctl.cmd_session_dir(args) == 0
    second = capsys.readouterr().out.strip()
    assert first == second
    assert len(list(tmp_path.glob("*/co-vivy-*"))) == 1


def test_convivy_session_dir_wins_over_a_recorded_pointer(agentctl, monkeypatch, tmp_path, capsys):
    """CONVIVY_SESSION_DIR overrides the recorded pointer in `session-dir` only. The
    ops MCP `handoff_write` tool never reads the variable, so a session that exports a
    directory other than its recorded one gets a co-rollover that looks in the exported
    directory, does not find the handoff the tool wrote, and refuses to start. This test
    pins the precedence; it does not make the two directories agree."""
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(tmp_path / "home"),
                             "CLAUDE_CODE_SESSION_ID": "sess-precedence"})
    assert agentctl.cmd_session_dir(args) == 0
    recorded = capsys.readouterr().out.strip()
    explicit = tmp_path / "explicit-dir"
    explicit.mkdir()
    monkeypatch.setenv(agentctl.SESSION_DIR_ENV, str(explicit))
    assert agentctl.cmd_session_dir(args) == 0
    assert capsys.readouterr().out.strip() == str(explicit)
    assert str(explicit) != recorded


def test_a_vanished_recorded_directory_exits_1_with_the_message_on_stderr(agentctl, monkeypatch,
                                                                          tmp_path, capsys):
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(tmp_path / "home"),
                             "CLAUDE_CODE_SESSION_ID": "sess-vanished"})
    assert agentctl.cmd_session_dir(args) == 0
    recorded = Path(capsys.readouterr().out.strip())
    recorded.rmdir()
    assert agentctl.cmd_session_dir(args) == 1
    captured = capsys.readouterr()
    assert captured.out == ""
    assert "is missing" in captured.err and str(recorded) in captured.err


@pytest.mark.parametrize("shape", ["dangling-symlink", "directory"])
def test_an_unreadable_recorded_pointer_exits_1_with_the_message_on_stderr(
        agentctl, monkeypatch, tmp_path, capsys, shape):
    """A dangling symlink used to come back as None, and a directory raised an OSError
    that nothing here caught. Both must refuse with a message on stderr."""
    home = tmp_path / "home"
    pointer = home / ".local" / "state" / "convivy" / "session-dirs" / "sess-unreadable"
    pointer.parent.mkdir(parents=True)
    if shape == "dangling-symlink":
        pointer.symlink_to(tmp_path / "nowhere")
    else:
        pointer.mkdir()
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(home), "CLAUDE_CODE_SESSION_ID": "sess-unreadable"})
    assert agentctl.cmd_session_dir(args) == 1
    captured = capsys.readouterr()
    assert captured.out == ""
    assert str(pointer) in captured.err


def test_two_claude_sessions_in_one_minute_get_separate_directories(agentctl, monkeypatch,
                                                                    tmp_path, capsys):
    args = _session_dir(agentctl, monkeypatch, tmp_path,
                        env={"HOME": str(tmp_path / "home"),
                             "CLAUDE_CODE_SESSION_ID": "sess-one"})
    assert agentctl.cmd_session_dir(args) == 0
    first = capsys.readouterr().out.strip()
    monkeypatch.setenv("CLAUDE_CODE_SESSION_ID", "sess-two")
    assert agentctl.cmd_session_dir(args) == 0
    second = capsys.readouterr().out.strip()
    assert first != second


def test_concurrent_callers_never_share_a_session_dir(agentctl, monkeypatch, tmp_path):
    """The collision loop must be atomic, not check-then-act.

    exists()-then-mkdir leaves a gap: two callers for the same product in the
    same minute both see the path free, and one dies on FileExistsError while
    the other takes a directory the first believed it owned. mkdir IS the claim.
    Single-threaded assertions cannot show this, so this drives it concurrently.
    """
    import threading

    monkeypatch.setattr(agentctl.T, "RUNS_ROOT", tmp_path)
    monkeypatch.delenv(agentctl.SESSION_DIR_ENV, raising=False)
    monkeypatch.delenv("CLAUDE_CODE_SESSION_ID", raising=False)

    # Assert on the filesystem, not on captured stdout: sys.stdout is global, so
    # redirecting it per-thread would have the threads capture each other.
    errors = []
    start = threading.Barrier(8)

    def go():
        args = type("A", (), {"product": "vivy", "print_": "path"})()
        try:
            start.wait(timeout=5)
            agentctl.cmd_session_dir(args)
        except Exception as e:  # a raised FileExistsError is the regression
            errors.append(e)

    threads = [threading.Thread(target=go) for _ in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=10)

    assert not errors, errors
    made = sorted(d.name for d in (tmp_path / agentctl.T.platform_day()).iterdir())
    assert len(made) == 8, f"callers shared a directory: {made}"


# --- pr-open opens drafts by default (ARCH-364) --------------------------------

_PR_SHA = "a" * 40


def _pr_open_worktree(tmp_path):
    """A worktree shaped enough for cmd_pr_open: a .git dir and a non-empty body."""
    wt = tmp_path / "wt"
    (wt / ".git").mkdir(parents=True)
    (wt / "pr-body.md").write_text("## What\n\nA change.\n")
    return wt


def _fake_run_for_pr_open(created):
    """Stand in for every git/gh call cmd_pr_open makes, recording `gh pr create`."""
    class R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            a = cmd[3:]  # strip ["git", "-C", <wt>]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return R("pr-body.md\n")
            if a[0] == "fetch":
                return R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return R(_PR_SHA + "\n")  # origin == HEAD, so ARCH-055 passes
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return R("origin/main\n")
            return R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                return R("[]\n")  # no open PR
            if cmd[1:3] == ["pr", "view"]:
                return R("", rc=1)  # no PR at all on this branch
            if cmd[1:3] == ["pr", "create"]:
                created.append(cmd)
                return R("https://github.com/convivy/agent-platform/pull/1\n")
        return R()

    return run


def test_pr_open_refuses_inside_a_dispatched_runs_own_object_redirected_env(
        agentctl, tmp_path, monkeypatch, capsys):
    """Same guard as `publish` (CQ·477): `cmd_pr_open` also calls
    `W.import_leftover_private_objects` (default `remove=True`) on the resolved
    worktree, unconditionally, with no in-use check of its own — the second
    unguarded path to the same deletion. Refuses up front, before that call or any
    git/gh subprocess, on the same signal `publish` refuses on."""
    wt = _pr_open_worktree(tmp_path)
    monkeypatch.setenv("GIT_ALTERNATE_OBJECT_DIRECTORIES", str(tmp_path / "shared"))
    calls = []
    monkeypatch.setattr(agentctl.subprocess, "run",
                        lambda *a, **k: calls.append(("subprocess.run", a, k)))
    monkeypatch.setattr(agentctl.W, "import_leftover_private_objects",
                        lambda *a, **k: calls.append(("import_leftover_private_objects", a, k)))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err
    assert "orchestrator's step" in err
    assert calls == [], "no subprocess call and no import before the refusal"


def test_pr_open_opens_a_draft_by_default(agentctl, monkeypatch, tmp_path):
    """ARCH-364: CI runs a cheap lint lane on drafts and the full suite only on
    mark-ready. If pr-open stopped passing --draft the gating would be inert —
    every worker PR would land ready and run the full suite immediately."""
    wt = _pr_open_worktree(tmp_path)
    created = []
    monkeypatch.setattr(agentctl.subprocess, "run", _fake_run_for_pr_open(created))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 0
    assert len(created) == 1, "exactly one `gh pr create`"
    assert "--draft" in created[0]


def test_pr_open_ready_flag_opts_out_of_draft(agentctl, monkeypatch, tmp_path):
    """The escape hatch for a PR that needs the full suite immediately."""
    wt = _pr_open_worktree(tmp_path)
    created = []
    monkeypatch.setattr(agentctl.subprocess, "run", _fake_run_for_pr_open(created))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing", "--ready"])

    assert rc == 0
    assert "--draft" not in created[0]


def _fake_gh_only(created):
    """Like `_fake_run_for_pr_open`, but defers every `git` argv to the REAL
    `subprocess.run` — only `gh` is faked. For a test that needs pr-open's own git reads
    (fetch, rev-parse, show-ref) to run for real against a real worktree."""
    real_run = subprocess.run

    class R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            return real_run(cmd, **kw)
        if cmd[1:3] == ["pr", "list"]:
            return R("[]\n")
        if cmd[1:3] == ["pr", "view"]:
            return R("", rc=1)
        if cmd[1:3] == ["pr", "create"]:
            created.append(cmd)
            return R("https://github.com/convivy/agent-platform/pull/1\n")
        return R()

    return run


def test_pr_open_finds_a_commit_pushed_from_a_runs_private_object_store(
        agentctl, monkeypatch, tmp_path):
    """Caller 2 of knowledge#793 round 6's item 3: pr-open's own ARCH-055 ordering check
    (`git fetch` + comparing `origin/<branch>` against HEAD) is a real git read, run here
    for real — it must not choke on a worktree whose one commit was made through the
    run's private object store and rejoined by `import_private_objects` before this ran,
    the same way `agentctl publish`'s real push already had to."""
    import run_sandbox as RS
    origin = tmp_path / "origin.git"
    subprocess.run(["git", "init", "-q", "--bare", "-b", "main", str(origin)], check=True)
    primary = tmp_path / "primary"
    subprocess.run(["git", "init", "-q", "-b", "main", str(primary)], check=True)

    def g(*a, cwd=primary, env=None):
        return subprocess.run(
            ["git", "-C", str(cwd), "-c", "user.email=t@t", "-c", "user.name=t", *a],
            check=True, capture_output=True, text=True, env=env)

    g("commit", "-q", "--allow-empty", "-m", "base")
    g("remote", "add", "origin", str(origin))
    g("push", "-q", "origin", "main")
    wt = tmp_path / "wt"
    g("worktree", "add", "-q", "-b", "agent/private-store-pr-open", str(wt))

    git_dir = RS.git_common_dir(wt)
    private_dir = RS.run_private_objects_dir(wt, git_dir)
    private_dir.mkdir()
    env = {**os.environ, "GIT_OBJECT_DIRECTORY": str(private_dir),
          "GIT_ALTERNATE_OBJECT_DIRECTORIES": str(git_dir / "objects")}
    (wt / "f.py").write_text("made in the private store\n")
    g("add", ".", cwd=wt, env=env)
    g("commit", "-qm", "private-store work", cwd=wt, env=env)
    RS.import_private_objects(git_dir, private_dir)
    g("push", "-q", "origin", "agent/private-store-pr-open", cwd=wt)

    # The exact path `cmd_pr_open`'s own `git rev-parse --git-path pr-body.md` resolves
    # to — a per-worktree gitdir file, same as pr-open's own docstring describes.
    body_rel = g("rev-parse", "--git-path", "pr-body.md", cwd=wt).stdout.strip()
    (wt / body_rel).resolve().write_text("## What\n\nA change.\n")

    created = []
    monkeypatch.setattr(agentctl.subprocess, "run", _fake_gh_only(created))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: private store work"])

    assert rc == 0
    assert len(created) == 1, "exactly one `gh pr create`"


def test_pr_open_folds_in_a_worktrees_leftover_private_store_before_reading_it(
        agentctl, monkeypatch, tmp_path):
    """Round 7 (reviewer round 6, blocking — family fix, not a reproduced defect of
    `pr-open` on its own): `pr-open`'s own checks (`rev-parse HEAD`, `show-ref
    --verify --hash` on the remote-tracking ref) are ref/string reads, never a local
    object read, so they do not independently reproduce the dead-dispatcher class the
    way `publish`'s real push does — confirmed by running this exact scenario against
    the pre-round-7 code with `gh` stubbed and a real push through the private-store
    env: it already passed. The orchestrator's brief names `pr-open` in the same
    family on the invariant this establishes regardless ("every place that reads a
    worktree a run may have used must first import its leftover private store"), so
    this pins the WIRING — `cmd_pr_open` calls `W.import_leftover_private_objects` on
    the resolved worktree before doing anything else with it — rather than a behavioral
    difference this command does not currently have."""
    wt = _pr_open_worktree(tmp_path)
    created = []
    monkeypatch.setattr(agentctl.subprocess, "run", _fake_run_for_pr_open(created))
    calls = []
    monkeypatch.setattr(agentctl.W, "import_leftover_private_objects",
                        lambda path: calls.append(path))

    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 0
    assert len(created) == 1, "exactly one `gh pr create`"
    assert calls == [wt.resolve()]


def test_pr_open_refuses_a_merged_pr(agentctl, monkeypatch, tmp_path):
    """A branch whose only PR is merged must be refused (issue 01KYRC81…)."""
    wt = _pr_open_worktree(tmp_path)

    # Reuse the standard git mocks from _fake_run_for_pr_open, but make gh pr
    # view return a merged PR instead of "no PR".
    class _R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            a = cmd[3:]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return _R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return _R("pr-body.md\n")
            if a[0] == "fetch":
                return _R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return _R("origin/main\n")
            return _R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                return _R("[]\n")  # no open PR — triggers the fallback merged check
            if cmd[1:3] == ["pr", "view"]:
                return _R('{"url":"https://github.com/convivy/agent-platform/pr/42","state":"MERGED"}\n')
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 1  # refused — the branch's only PR is merged


