def test_pr_open_resolves_branch_with_both_merged_and_open(agentctl, monkeypatch, tmp_path, capsys):
    """When a branch carries both a merged and an open PR, pr-open resolves to the
    open one rather than the merged one (gh pr list --state open, not gh pr view)."""
    wt = _pr_open_worktree(tmp_path)

    class _R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    def run(cmd, **kw):
        if cmd[0] == "git":
            a = cmd[3:]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return _R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return _R("pr-body.md\n")
            if a[0] == "fetch":
                return _R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return _R("origin/main\n")
            return _R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                # --state open finds the open one
                return _R('[{"url":"https://github.com/convivy/agent-platform/pr/99"}]\n')
            if cmd[1:3] == ["pr", "view"]:
                # Fallback — would return the MERGED one, but is never reached
                return _R('{"url":"https://github.com/convivy/agent-platform/pr/42","state":"MERGED"}\n')
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert rc == 0  # resolved to the open PR (pr/99), not the merged one (pr/42)
    out, _ = capsys.readouterr()
    assert "pr/99" in out, "stamped URL should be the open PR, not the merged one"


def test_pr_open_fallback_finds_open_pr_after_list_glitch(agentctl, monkeypatch, tmp_path, capsys):
    """When gh pr list fails transiently but an open PR exists, the gh pr view
    fallback must treat state=OPEN as idempotent (return 0), not refuse."""
    wt = _pr_open_worktree(tmp_path)

    class _R:
        def __init__(self, out="", rc=0):
            self.stdout, self.stderr, self.returncode = out, "", rc

    called_pr_view = False

    def run(cmd, **kw):
        nonlocal called_pr_view
        if cmd[0] == "git":
            a = cmd[3:]
            if a[:2] == ["rev-parse", "--abbrev-ref"] and a[2] == "HEAD":
                return _R("feat/thing\n")
            if a == ["rev-parse", "HEAD"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--git-path"]:
                return _R("pr-body.md\n")
            if a[0] == "fetch":
                return _R()
            if a[:3] == ["show-ref", "--verify", "--hash"]:
                return _R(_PR_SHA + "\n")
            if a[:2] == ["rev-parse", "--abbrev-ref"]:
                return _R("origin/main\n")
            return _R()
        if cmd[0] == "gh":
            if cmd[1:3] == ["pr", "list"]:
                # Simulate a transient API glitch: non-zero rc and empty stdout
                return _R("", rc=1)
            if cmd[1:3] == ["pr", "view"]:
                called_pr_view = True
                return _R('{"url":"https://github.com/convivy/agent-platform/pr/88","state":"OPEN"}\n')
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])

    assert called_pr_view, "should fall back to gh pr view"
    assert rc == 0, "should idempotently return 0 for an open PR"
    out, _ = capsys.readouterr()
    assert "pr/88" in out


