def test_review_post_library_refusal_writes_a_marker_for_finalize_to_read(
        agentctl, monkeypatch, tmp_path, capsys):
    """ARCH-397's downgrade (`_finalize_run`) needs to tell a Library refusal
    apart from every other reason a called review-post could leave no stamp, or
    it falls back to blaming the PR head moving — the wrong cause for this one
    (issue_01M3830J6EKZ394Q8AVYRQGN40 round 2). review-post itself must drop the
    reason where finalize will look, and must stop pointing solely at the
    ephemeral body file, which does not survive the worktree reap (ARCH-344)."""
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    rd = T.create_run_dir("run-lib-refuse", date="2026-08-03")
    body = _review_post_body(tmp_path)
    import issue_client
    monkeypatch.setattr(
        issue_client, "post_review_record",
        lambda *a, **kw: {"status": "error:422", "error": "at most 20 paths entries",
                          "record": {}})
    posted = []
    _no_gh_comment(agentctl, monkeypatch, posted)

    rc = agentctl.main(["review-post", "--pr", "5", "--verdict", "REQUEST_CHANGES",
                        "--agent", "reviewer", "--body-file", str(body),
                        "--repo", "convivy/agent-platform", "--reviewed-commit", _SHA,
                        "--run-id", "run-lib-refuse"])
    assert rc != 0
    assert not posted

    marker = rd / agentctl._LIBRARY_REFUSAL_MARKER_FILENAME
    assert marker.exists(), "finalize has nothing to read the refusal reason from otherwise"
    assert json.loads(marker.read_text()) == {
        "status": "error:422", "error": "at most 20 paths entries"}

    err = capsys.readouterr().err
    assert str(rd / "unposted-review.md") in err, (
        "the re-post instructions must name the durable rescue path, which "
        "survives the worktree reap, not only the ephemeral body file")
    assert "--allow-rescued" in err
    assert f"--reviewed-commit {_SHA}" in err, (
        "run exactly as printed, outside this run's own process, the command "
        "has no AGENTCTL_REVIEW_SHA pin to fall back on and hits the "
        "'no reviewed commit' refusal before --allow-rescued is ever reached "
        "(reviewer, PR #722)")
    assert "--run-id run-lib-refuse" in err


def test_review_post_library_refusal_command_reposts_past_the_no_commit_check(
        agentctl, monkeypatch, tmp_path, capsys):
    """The command review-post PRINTS on a Library refusal must actually work when
    run as printed, outside the original run's process — the exact failure mode
    the reviewer found (PR #722): parse it out of stderr, clear the pin env vars
    a real re-post would not have, stub the Library to succeed this time, and run
    it for real."""
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    rd = T.create_run_dir("run-lib-refuse2", date="2026-08-03")
    body = _review_post_body(tmp_path)
    import issue_client
    monkeypatch.setattr(
        issue_client, "post_review_record",
        lambda *a, **kw: {"status": "error:422", "error": "at most 20 paths entries",
                          "record": {}})
    posted = []
    _no_gh_comment(agentctl, monkeypatch, posted)
    monkeypatch.delenv("AGENTCTL_REVIEW_SHA", raising=False)
    monkeypatch.delenv("AGENTCTL_RUN_ID", raising=False)

    rc = agentctl.main(["review-post", "--pr", "5", "--verdict", "REQUEST_CHANGES",
                        "--agent", "reviewer", "--body-file", str(body),
                        "--repo", "convivy/agent-platform", "--reviewed-commit", _SHA,
                        "--run-id", "run-lib-refuse2"])
    assert rc != 0 and not posted

    err = capsys.readouterr().err
    m = re.search(r"`(agentctl review-post [^`]+)`", err)
    assert m, f"no backtick-quoted command found in: {err!r}"
    printed_cmd = m.group(1).split()
    assert printed_cmd[0] == "agentctl"

    # ARCH-397 (_finalize_run, not exercised here) is what actually writes this
    # file at run end; simulate its result directly, the way it is written.
    rescued_path = rd / "unposted-review.md"
    rescued_path.write_text(
        f"{agentctl.RESCUED_REVIEW_MARKER}\n"
        f"# Review written by run-lib-refuse2 and never posted\n\nLooks good.\n")

    # Same run-id, this time the Library accepts — the printed command must reach
    # this write at all, which means it got past the no-reviewed-commit check
    # AND the rescued-body refusal.
    sent = {}
    monkeypatch.setattr(
        issue_client, "post_review_record",
        lambda fields, **kw: sent.update(fields) or {"status": "ok", "record": {"id": "r1"}})
    monkeypatch.setattr(agentctl.subprocess, "run",
                        lambda cmd, **kw: type("R", (), {
                            "returncode": 0, "stdout": "https://x/2", "stderr": ""})())

    rc2 = agentctl.main(printed_cmd[1:])
    assert rc2 == 0, f"the printed command failed as printed: {capsys.readouterr().err}"
    assert sent["reviewed_ref"] == _SHA
    assert sent["run_id"] == "run-lib-refuse2"


