def test_unexpanded_matrix_template_placeholder_is_ignored(agentctl):
    """A draft-gated matrix job leaves an un-expanded `${{ }}` template check-run
    (conclusion SKIPPED) that lingers on the head after pr-ready expands the real
    shards (which run under DIFFERENT names — `shard 1/4`…). The placeholder is
    never a real result and must not enter the required set, or every matrix-CI
    PR false-negatives under the draft-first flow (constance-co note, ARCH-384)."""
    rollup = [
        {"name": "Backend tests (shard ${{ matrix.group }}/4)", "conclusion": "SKIPPED"},
        {"name": "Backend tests (shard 1/4)", "conclusion": "SUCCESS"},
        {"name": "Backend tests (shard 2/4)", "conclusion": "SUCCESS"},
        {"name": "Migrations clean", "conclusion": "SUCCESS"},
    ]
    assert agentctl._skipped_checks(rollup) == [], "the ${{ }} placeholder must not count as a skip"
    assert agentctl._ci_is_green(rollup) is True


def test_ci_is_green_tolerates_skips_so_the_gate_reports_once(agentctl):
    """Pins _ci_is_green, NOT the approve path — cmd_review_post never calls it.

    Its skip-tolerance matters to review-status: evaluate_gate receives
    ci_green=True and _skipped_checks reports the skip separately, so the reader
    gets one precise reason instead of two overlapping ones.
    """
    assert agentctl._ci_is_green([{"name": "build-test", "conclusion": "SKIPPED"}]) is True


def test_split_rollup_tolerates_skips_so_drafts_stay_approvable(agentctl):
    """THE APPROVE PATH'S ACTUAL PIN.

    review-post reaches CI through _approve_blocked_by_ci -> _split_rollup, not
    through _ci_is_green. Reviewers approve while the PR is a DRAFT, which is
    precisely when the expensive jobs skip — so if _split_rollup ever treated
    SKIPPED as red (a tempting change, given the bug this PR fixes), every draft
    would become unapprovable and nothing would have caught it.
    """
    red, pending = agentctl._split_rollup([{"name": "build-test", "conclusion": "SKIPPED"}])
    assert red == []
    assert pending == []


