# --- the injection vector: a same-named job from another workflow -------------

def _wf_entry(name, workflow, concl, started):
    return {"name": name, "workflowName": workflow, "conclusion": concl,
            "startedAt": started}


def test_an_injected_success_cannot_shadow_a_real_failure(agentctl, monkeypatch, capsys):
    """THE MERGE-GATE BYPASS THIS PINS (security review, round 3).

    Keying the collapse by name alone let a PR branch add a second workflow with
    a job ALSO named `python` that echoes ok and finishes after the real suite:
    'newest wins' picked the injected SUCCESS and dropped the real FAILURE. Keying
    by (workflow, name) makes them different keys, so the real failure stands.
    """
    _trust_all_stamps(agentctl, monkeypatch)
    head = "f" * 40
    _fake_pr_view(agentctl, monkeypatch, head=head, is_draft=False,
                  rollup=[_wf_entry("python", "ci", "FAILURE", "2026-07-20T10:00:00Z"),
                          _wf_entry("python", "sneaky", "SUCCESS", "2026-07-20T10:05:00Z")],
                  comments=[_stamp_comment(agentctl, "reviewer", head),
                            _stamp_comment(agentctl, "security-reviewer", head)])
    rc = agentctl.cmd_review_status(_ns(pr="7", repo="convivy/x", required=None,
                                        ignore_ci=False, allow_unverified=False))
    assert rc == 1, "an injected same-named job must not shadow the real failure"


