def test_skip_checks_is_logged(agentctl, tmp_path, monkeypatch):
    """The gates exist because instructions did not hold. An escape hatch nobody
    can count would decay the same way, so it is logged like a model override."""
    log = tmp_path / "skipped.jsonl"
    monkeypatch.setattr(agentctl, "SKIPPED_CHECKS_LOG", log)
    agentctl._log_skipped_checks(wt=tmp_path / "wt", branch="agent/thing")
    rec = json.loads(log.read_text().strip())
    assert rec["branch"] == "agent/thing" and rec["worktree"].endswith("wt")


def test_skip_checks_flag_matches_what_publish_reads(agentctl):
    """The flag's argparse `dest` and the attribute `cmd_publish` reads must agree.

    `--skip-checks` would otherwise parse to `skip_checks` while a reader looking
    for anything else silently gets the `getattr(..., False)` default — the flag
    would appear to work and gate nothing. Review flagged the untested wiring;
    this pins the seam rather than the whole command, which needs a real worktree.
    """
    import inspect
    parser = agentctl.build_parser() if hasattr(agentctl, "build_parser") else None
    if parser is not None:
        args = parser.parse_args(["publish", ".", "--skip-checks"])
        assert getattr(args, "skip_checks", None) is True
    src = inspect.getsource(agentctl.cmd_publish)
    assert 'getattr(args, "skip_checks", False)' in src, (
        "cmd_publish must read the same attribute argparse writes")


# --- deployed-tree check at dispatch (ARCH-229/issue_01KYQ9NDT0ZEC) -----------
#
# When the deployed platform checkout is on a non-main branch or behind
# origin/main, every agentctl spawn runs stale code without anyone knowing.
# _warn_deployed_tree warns at spawn time, non-blocking, so the condition is
# surfaced at the moment it matters (dispatch) rather than buried in the
# autopull log.


def _make_deployed_repo(tmp_path) -> tuple[Path, Path]:
    """Set up a fake primary checkout + origin for testing _warn_deployed_tree.

    Returns (repo_root, origin_path) where repo_root is a git checkout on main
    with one commit, and origin_path is a bare repo pushed to (so origin/main
    resolves).  The caller adds commits to origin and pulls to create the
    "behind" scenario, or creates a non-main branch for the "off-main" check.
    """
    origin = tmp_path / "origin.git"
    subprocess.run(["git", "init", "-q", "--bare", str(origin)], check=True)
    subprocess.run(["git", "-C", str(origin), "symbolic-ref", "HEAD", "refs/heads/main"],
                    check=True)

    repo = tmp_path / "deployed"
    repo.mkdir()
    subprocess.run(["git", "init", "-q", "--initial-branch=main", str(repo)], check=True)
    subprocess.run(["git", "-C", str(repo), "config", "user.email", "t@t.t"], check=True)
    subprocess.run(["git", "-C", str(repo), "config", "user.name", "t"], check=True)
    (repo / "file.py").write_text("code\n")
    subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
    subprocess.run(["git", "-C", str(repo), "commit", "-qm", "init"], check=True)
    subprocess.run(["git", "-C", str(repo), "remote", "add", "origin", str(origin)], check=True)
    subprocess.run(["git", "-C", str(repo), "push", "-q", "-u", "origin", "main"], check=True)
    return repo, origin


def test_warn_deployed_tree_stays_quiet_on_clean_tree(agentctl, tmp_path, monkeypatch, capsys):
    """On main, up to date with origin/main — nothing to warn about."""
    repo, _ = _make_deployed_repo(tmp_path)
    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: repo)
    agentctl._warn_deployed_tree()
    assert capsys.readouterr().err == ""


def test_warn_deployed_tree_warns_on_off_main_branch(agentctl, tmp_path, monkeypatch, capsys):
    """Off-main branch → warn, short-circuit before the behind-count check."""
    repo, _ = _make_deployed_repo(tmp_path)
    subprocess.run(["git", "-C", str(repo), "checkout", "-q", "-b", "stray-branch"], check=True)
    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: repo)
    agentctl._warn_deployed_tree()
    err = capsys.readouterr().err
    assert "not 'main'" in err
    assert "stray-branch" in err


def test_warn_deployed_tree_warns_when_behind_origin_main(agentctl, tmp_path, monkeypatch, capsys):
    """Behind origin/main → warn with the commit count."""
    repo, origin = _make_deployed_repo(tmp_path)
    # Advance origin/main past the checkout: commit directly on origin.
    origin_checkout = tmp_path / "origin-copy"
    subprocess.run(["git", "clone", "-q", str(origin), str(origin_checkout)], check=True)
    subprocess.run(["git", "-C", str(origin_checkout), "config", "user.email", "t@t.t"], check=True)
    subprocess.run(["git", "-C", str(origin_checkout), "config", "user.name", "t"], check=True)
    (origin_checkout / "new.py").write_text("new\n")
    subprocess.run(["git", "-C", str(origin_checkout), "add", "-A"], check=True)
    subprocess.run(["git", "-C", str(origin_checkout), "commit", "-qm", "advance"], check=True)
    subprocess.run(["git", "-C", str(origin_checkout), "push", "-q", "origin", "main"], check=True)
    # Fetch so the deployed tree's origin/main ref is updated.
    subprocess.run(["git", "-C", str(repo), "fetch", "-q", "origin"], check=True)

    monkeypatch.setattr(agentctl, "_deployed_platform_path", lambda: repo)
    agentctl._warn_deployed_tree()
    err = capsys.readouterr().err
