def test_spawn_lib_gate_refuses_when_lib_mismatches_canonical(agentctl, tmp_path, monkeypatch, capsys):
    """This process's own lib does NOT match the canonical one — the shape of
    `<worktree>/bin/agentctl spawn ...`, invoked directly rather than via the
    bare `agentctl` on PATH. Must refuse (exit code 2), naming both paths."""
    other_lib = tmp_path / "primary-checkout" / "lib" / "agent-platform"
