def test_spawn_lib_gate_escape_hatch_allows_and_warns(agentctl, tmp_path, monkeypatch, capsys):
    """AGENTCTL_ALLOW_WORKTREE_SPAWN bypasses the refusal, loudly."""
    other_lib = tmp_path / "primary-checkout" / "lib" / "agent-platform"
