def test_run_session_preflight_failure_leaves_no_meta_nor_slot(
        agentctl, tmp_path, monkeypatch):
    """When the preflight fires (SystemExit) it does so before T.write_meta and
    R.reserve_slot — no meta.json and no ghost reservation. Regression guard for
    the preflight relocation from after reserve_slot to before write_meta."""
    import types

    run_dir = tmp_path / "run-pf"
    run_dir.mkdir()
    worktree = tmp_path / "wt"
    worktree.mkdir()
    # .venv dir with no bin/python — triggers the real preflight SystemExit
    (worktree / ".venv").mkdir()
    stub = tmp_path / "claude-stub"
    stub.write_text(
        "#!/bin/sh\n"
        "printf '%s\\n' '{\"type\":\"result\",\"subtype\":\"success\",\"model\":\"x\"}'\n"
        "exit 0\n"
    )
    stub.chmod(0o755)

    slot_called = False

    def track_reserve(*_a, **_kw):
        nonlocal slot_called
        slot_called = True
        return None

    monkeypatch.setattr(agentctl, "CLAUDE_BIN", str(stub))
    monkeypatch.setattr(agentctl, "_gateway_virtual_key", lambda: "vk-test")
    monkeypatch.setattr(agentctl, "_gateway_url", lambda: "http://127.0.0.1:9")
    monkeypatch.setattr(agentctl, "_run_origin", lambda parent=None: "interactive")
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    monkeypatch.setattr(agentctl.R, "reserve_slot", track_reserve)
    monkeypatch.setattr(agentctl.R, "attach_pid", lambda rid, pid, pid_started_at=None, **_kw: None)
    monkeypatch.setattr(agentctl.R, "remove_run", lambda rid: True)
    # Do NOT mock _preflight_python_worktree — let it fire

    args = types.SimpleNamespace(
        agent="reviewer", task="t", parent=None,
        dry_run=False, label=None, model=None)

    with pytest.raises(SystemExit):
        agentctl._run_session(
            args=args, agent={"body": "sys", "model_alias": "opus"},
            run_id="run-pf", run_dir=run_dir, worktree=worktree,
            profile="p", repo="agent-platform",
            started_at="2026-06-11T00:00:00Z", user_prompt="u")

    # Preflight runs before write_meta and reserve_slot — neither should fire
    assert not slot_called, \
        "reserve_slot was called — preflight should fire before slot reservation"
    assert not (run_dir / "meta.json").exists(), \
        "meta.json written before preflight — preflight should fire before write_meta"


# --- a dispatch that FAILED must not read as one that finished ----------------
#
# The waiter is how a co (and the overnight orchestrator) learns a detached run
# ended, and the harness reports the WAITER's exit code. Exiting 0 on a run that
# died meant "completed (exit code 0)" for a review that never posted — seven
# runs on 2026-08-02, two of them exactly that shape.


def _finished_run(agentctl, T, root, run_id, status, **outcome_kw):
    """A finalized run dir under `root` with the given exit_status."""
    d = T.create_run_dir(run_id, date="2026-08-02")
    T.write_meta(d, run_id=run_id, agent="reviewer", task="t",
                 started_at=T.now_iso(), repo="convivy/x", worktree=str(root),
                 profile="p", model="claude-sonnet-4-6")
    T.write_outcome(d, exit_status=status, **outcome_kw)
    return d


def test_wait_names_a_failover_that_actually_happened_even_though_it_succeeded(
        agentctl, tmp_path, monkeypatch, capsys):
    """The action half of the same bullet, and the one the failure loop misses.

    Across June-August 2026, 68 runs failed over and 64 COMPLETED — so they never
    entered the failure branch and the waiter printed a plain success line. A run
    that quietly finished at a different provider was indistinguishable from one
    that finished where it was sent, which is the 2026-07-19 incident verbatim.
    """
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = _finished_run(agentctl, T, tmp_path, "run-fo01", "completed")
    T.update_meta(d, fallback_from="claude-sonnet-5",
                  model="deepseek/deepseek-chat",
                  fallback_reason="exit_code=1")
    rc = agentctl._wait_for_runs(["run-fo01"], timeout=5, poll=0.01)
    err = capsys.readouterr().err
    assert rc == 0, "it completed; the exit code must not change"
    assert "FAILED OVER" in err
    assert "deepseek/deepseek-chat" in err, "name where it actually ran"
    assert "claude-sonnet-5" in err, "and where it was sent"


def test_wait_is_silent_about_failover_for_a_run_that_never_swapped(
        agentctl, tmp_path, monkeypatch, capsys):
    """Otherwise every successful run grows a line, which is how a real signal
    turns into wallpaper."""
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    _finished_run(agentctl, T, tmp_path, "run-fo02", "completed")
    assert agentctl._wait_for_runs(["run-fo02"], timeout=5, poll=0.01) == 0
    assert "FAILED OVER" not in capsys.readouterr().err


def test_a_broken_meta_does_not_stop_the_waiter_reporting_the_batch(
        agentctl, tmp_path, monkeypatch, capsys):
    """`_failover_note` reads a file the run itself writes.

    Raising there would let one agent suppress the waiter's whole report by
    leaving broken JSON behind — a suppression primitive handed to the party
    being reported on, in the one line a co reads to decide whether a review
    landed."""
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = _finished_run(agentctl, T, tmp_path, "run-fo03", "completed")
    (d / "meta.json").write_text("{not json")
    _finished_run(agentctl, T, tmp_path, "run-fo04", "completed")
    assert agentctl._wait_for_runs(["run-fo03", "run-fo04"], timeout=5,
                                   poll=0.01) == 0
    out = capsys.readouterr().out
    assert "run-fo03" in out and "run-fo04" in out, "both runs must still report"


def test_a_meta_that_is_valid_json_but_not_an_object_is_named_not_swallowed(
        agentctl, tmp_path, monkeypatch, capsys):
    """`read_meta` does not raise on `[]` — it returns a list, and `.get` on a
    list raises later, somewhere less convenient.

    The `isinstance` check is what stops that, and without a test it is exactly
    the guard a future edit reorders past the `.get()` with everything still
    green. "Not an object" must also read differently from "no fail-over".
    """
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = _finished_run(agentctl, T, tmp_path, "run-list01", "errored")
    (d / "meta.json").write_text("[]")
    rc = agentctl._wait_for_runs(["run-list01"], timeout=5, poll=0.01)
    err = capsys.readouterr().err
    assert rc == agentctl.EXIT_RUN_FAILED
    assert "run-list01 FAILED" in err, "the failure itself still reports"
    assert "not an object" in err, "and the reason it could not be read is named"


def test_a_run_that_never_failed_over_reads_differently_from_one_that_cannot_be_read(
        agentctl, tmp_path, monkeypatch, capsys):
    """Absent is not false.

    A run that quietly completed at a provider nobody chose is exactly what this
    change exists to surface, so "it did not fail over" and "I could not tell"
    producing identical silent output would hand that run a one-file way to look
    ordinary."""
    import telemetry as T
    monkeypatch.setattr(agentctl, "RUNS_ROOT", tmp_path)
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
