# --- subscription overage: the signal that reached the transcript and no further

def _rl(d, **info):
    """Append one `rate_limit_event` the way the CLI emits it."""
    import json as _json
    with (d / "transcript.jsonl").open("a") as f:
        f.write(_json.dumps({"type": "rate_limit_event", "uuid": "u",
                             "rate_limit_info": info}) + "\n")


def test_a_run_that_never_reported_quota_records_nothing(agentctl, tmp_path,
                                                         monkeypatch):
    """Absent and false mean different things — "we never heard" versus "we heard
    and it was inside the plan". A run whose stream carried no rate_limit_event
    must not claim a confident `false`, or an overage report counts it as
    evidence of being under the cap."""
    import telemetry as T
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = T.create_run_dir("run-rl-none", date="2026-08-03")
    assert agentctl._scan_rate_limits(d) == {}


def test_overage_is_recorded_when_any_event_reports_it(agentctl, tmp_path,
                                                       monkeypatch):
    """ANY event, not the last: the quota can flip mid-run, and a run that spent
    part of its life in overage is what the ARCH-174 question asks about."""
    import telemetry as T
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = T.create_run_dir("run-rl-over", date="2026-08-03")
    _rl(d, status="allowed", isUsingOverage=False, rateLimitType="five_hour")
    _rl(d, status="rejected", isUsingOverage=True, rateLimitType="five_hour")
    _rl(d, status="allowed", isUsingOverage=False, rateLimitType="five_hour")
    got = agentctl._scan_rate_limits(d)
    assert got["overage_seen"] is True
    assert got["rate_limit_status"] == "rejected"       # the WORST seen, not the last


def test_a_run_entirely_inside_the_plan_records_false(agentctl, tmp_path,
                                                      monkeypatch):
    import telemetry as T
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = T.create_run_dir("run-rl-in", date="2026-08-03")
    _rl(d, status="allowed", isUsingOverage=False, rateLimitType="five_hour")
    got = agentctl._scan_rate_limits(d)
    assert got == {"overage_seen": False, "rate_limit_status": "allowed"}


def test_peak_utilization_is_the_max_and_absent_when_never_reported(
        agentctl, tmp_path, monkeypatch):
    """Only two of the six observed payload shapes carry `utilization`, so its
    absence is the common case and must not read as 0.0 — which would report a
    saturated window as an empty one."""
    import telemetry as T
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = T.create_run_dir("run-rl-peak", date="2026-08-03")
    _rl(d, status="allowed", isUsingOverage=False, utilization=0.4)
    _rl(d, status="allowed_warning", isUsingOverage=False, utilization=0.96)
    _rl(d, status="allowed", isUsingOverage=False, utilization=0.5)
    assert agentctl._scan_rate_limits(d)["peak_utilization"] == 0.96

    d2 = T.create_run_dir("run-rl-nopeak", date="2026-08-03")
    _rl(d2, status="allowed", isUsingOverage=False, overageStatus="allowed")
    assert "peak_utilization" not in agentctl._scan_rate_limits(d2)


def test_the_scan_survives_a_transcript_truncated_mid_write(agentctl, tmp_path,
                                                            monkeypatch):
    """Same reason as the retry gate's scan: the transcript is appended live, so a
    process that died mid-flush leaves a partial last line. Losing that line must
    not lose the events before it."""
    import telemetry as T
