def test_every_observed_payload_shape_parses(agentctl, tmp_path, monkeypatch):
    """The six shapes actually present across the box's transcripts. Only
    `isUsingOverage` appears in all of them, which is why it is the field the
    overage answer rests on."""
    import telemetry as T
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    shapes = [
        dict(isUsingOverage=False, overageResetsAt=1, overageStatus="allowed",
             rateLimitType="five_hour", resetsAt=1, status="allowed"),
        dict(isUsingOverage=False, rateLimitType="seven_day", resetsAt=1,
             status="allowed_warning", surpassedThreshold=0.75, utilization=0.96),
        dict(isUsingOverage=False, overageDisabledReason="x", overageStatus="rejected",
             rateLimitType="five_hour", resetsAt=1, status="allowed"),
        dict(isUsingOverage=False, rateLimitType="five_hour", resetsAt=1,
             status="allowed", utilization=0.25),
        dict(isUsingOverage=False, status="allowed"),
        dict(isUsingOverage=True, overageInUse=True, overageResetsAt=1,
             overageStatus="allowed", rateLimitType="five_hour", resetsAt=1,
             status="rejected"),
    ]
    for i, shape in enumerate(shapes):
        d = T.create_run_dir(f"run-rl-shape{i}", date="2026-08-03")
        _rl(d, **shape)
        got = agentctl._scan_rate_limits(d)
        assert "overage_seen" in got, shape
    # the last shape is the only one carrying overage
    assert agentctl._scan_rate_limits(
        T.run_dir("run-rl-shape5", date="2026-08-03"))["overage_seen"] is True


def test_write_outcome_rejects_an_unknown_rate_limit_status(tmp_path, monkeypatch):
    """Same posture as exit_status: an unrecognised value is a typo or a new state
    nobody has decided about, and either way it must not land in the record."""
    import pytest as _pytest
    import telemetry as T
    monkeypatch.setattr(T, "RUNS_ROOT", tmp_path)
    d = T.create_run_dir("run-rl-bad", date="2026-08-03")
    with _pytest.raises(ValueError, match="invalid rate_limit_status"):
        T.write_outcome(d, exit_status="completed", rate_limit_status="throttled")
    T.write_outcome(d, exit_status="completed", rate_limit_status="rejected",
                    overage_seen=True, peak_utilization=0.96)
    o = T.read_outcome(d)
    assert o["overage_seen"] is True and o["peak_utilization"] == 0.96
    assert o["rate_limit_status"] == "rejected"


