def test_the_leak_report_attributes_it_to_this_run_when_the_worktree_echoes_it(
        agentctl, tmp_path, monkeypatch, capsys):
    """The concurrent-run problem, end to end. On a 20-worker night one real leak
    lands in every overlapping run's window; the file existing at the same
    relative path inside THIS run's worktree is what separates author from
    bystander."""
    import primary_guard as PG
    monkeypatch.setattr(agentctl, "_changed_files", lambda *a: ([], [], []))
    monkeypatch.setattr(agentctl.W, "unpublished_commits", lambda wt: 0)
    root = tmp_path / "Convivy"
    root.mkdir()
    primary = _mk_primary_for_guard(root, "vivy")
    monkeypatch.setattr(PG, "CONVIVY_ROOT", root)

    rd, wt = _mk_run_dir(tmp_path)
    (wt / "leaked.py").write_text("# the same write, right root")
    agentctl._baseline_primaries(rd, wt)
    (primary / "leaked.py").write_text("# the same write, wrong root")
    agentctl._finalize_run(run_dir=rd, worktree=wt, run_id="run-test", exit_code=0,
                           final_event={"type": "result", "subtype": "success"},
                           profile="agent-platform/daytime",
                           agent={"model_alias": "sonnet"})

    assert _status(rd) == "primary_mutated"
    assert "THIS RUN" in capsys.readouterr().err
    detail = json.loads((rd / "primary_mutations.json").read_text())
    assert detail["mutations"][0]["echoed_in_worktree"] == ["leaked.py"]


