def _orphan_the_head(p):
    """Move HEAD to a new root commit and delete `main`, so the baseline commit is on no ref. The
    tree is unchanged, so this is an orphan-only mutation: no added path, no removed path."""
    import subprocess as sp
    for args in (("checkout", "-q", "--orphan", "fresh"), ("commit", "-qm", "fresh"),
                 ("branch", "-D", "main")):
        sp.run(["git", "-C", str(p), *args], check=True, capture_output=True)


def test_an_orphaning_reset_after_an_additive_leak_the_same_day_logs_its_own_signal(
        agentctl, tmp_path, monkeypatch):
    """An orphan-only HEAD move has an empty removed set, so the removed-set key matched every
    additive-only change that day and answered `duplicate`: a commit lost to `reset --hard` reached
    no signal. The orphaned commit's id is part of the key now, so this logs its own signal."""
    signals = _stub_guard_signals(monkeypatch)
    additive, orphan = tmp_path / "additive", tmp_path / "orphan"
    additive.mkdir()
    orphan.mkdir()
    _guard_run(agentctl, additive, monkeypatch,
               leak=lambda p: (p / "ci.yml").write_text("# leak"))
    _guard_run(agentctl, orphan, monkeypatch, leak=_orphan_the_head)

    assert [s["status"] for s in signals] == ["created", "created"]
    assert signals[0]["dedup_key"] != signals[1]["dedup_key"]
    assert "ORPHANED" in signals[1]["body"], "positive control: the orphan was detected"


