def test_the_guard_logs_a_signal_on_its_stream_and_never_creates_an_item(
        agentctl, tmp_path, monkeypatch):
    """A monitor logs a signal, never a work item (platform/decisions/0073). The item client is
    replaced with a mock so an item creation, if one were reintroduced, would be recorded."""
    import sys
    from unittest import mock
    fake_items = mock.MagicMock()
    monkeypatch.setitem(sys.modules, "issue_client", fake_items)
    signals = _stub_guard_signals(monkeypatch)
    _guard_run(agentctl, tmp_path, monkeypatch,
               leak=lambda p: (p / "orphan.py").write_text("# unowned"))

