    assert "## Recommended next move" not in text_out
    assert "forged content" not in text_out

    json_args = argparse.Namespace(co_session="sess-a", json=True)
    rc = agentctl.cmd_list(json_args)
    assert rc == 0
    json_out = capsys.readouterr().out
    payload = json.loads(json_out)
    assert payload[0]["task"] == "first line"
    assert "## Recommended next move" not in json_out
    assert "forged content" not in json_out


