def _publishable(tmp_path, monkeypatch, agentctl):
    """A worktree with a real bare `origin`, so `cmd_publish` can actually push.

    Stubs `_content_scan_gate`: every caller here builds a throwaway repo with
    no Shipwright checkout anywhere nearby, and this fixture is about the push
    mechanics (repair commits, decoy refs, verification), not the content scan —
    that gate has its own tests, below."""
    import subprocess as sp
    bare = tmp_path / "origin.git"
    sp.run(["git", "init", "-q", "--bare", "-b", "main", str(bare)], check=True)
    primary = tmp_path / "repo"
    primary.mkdir()
    sp.run(["git", "init", "-q", "-b", "main"], cwd=primary, check=True)
    for k, v in (("user.email", "t@t.t"), ("user.name", "t")):
        sp.run(["git", "config", k, v], cwd=primary, check=True)
    (primary / "AGENTS.md").write_text("never push to main\n")
    (primary / "app.py").write_text("code\n")
    sp.run(["git", "add", "-A"], cwd=primary, check=True)
    sp.run(["git", "commit", "-qm", "init"], cwd=primary, check=True)
    sp.run(["git", "remote", "add", "origin", str(bare)], cwd=primary, check=True)
    sp.run(["git", "push", "-q", "origin", "main"], cwd=primary, check=True)
    wt = tmp_path / "wt"
    sp.run(["git", "worktree", "add", "-q", "-b", "feature", str(wt)], cwd=primary, check=True)
    for k, v in (("user.email", "t@t.t"), ("user.name", "t")):
        sp.run(["git", "config", k, v], cwd=wt, check=True)
    sp.run(["git", "push", "-q", "-u", "origin", "feature"], cwd=wt, check=True)
    monkeypatch.setattr(agentctl.W, "is_primary_checkout", lambda repo, path: False)
    monkeypatch.setattr(agentctl, "_content_scan_gate", lambda *a, **k: 0)
    return bare, wt


def test_publish_pushes_and_verifies_the_repair_commit(agentctl, tmp_path, monkeypatch, capsys):
    """THE PATH THE WHOLE MECHANISM EXISTS FOR, end to end through cmd_publish.

    Review found that every test called the helper directly, so deleting the
    call site left the suite green — and the call site was where it broke.
    `cmd_publish` read `head` once, before the repair; the repair moved HEAD
    past it; then the in-sync check saw origin matching the stale SHA and
    skipped the push, and the post-push verification compared against that same
    stale SHA and reported VERIFICATION FAILED over a correct push.
    """
    import subprocess as sp
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    agentctl.suppress_repo_instructions("demo", wt)
    git = _git_in(wt)
    (wt / "app.py").write_text("code\nthe agent's work\n")
    git("commit", "-aqm", "fix: the agent's work")
    assert _deletes_agents_md(git)

    args = argparse.Namespace(worktree=str(wt), run=None, repo=None, purpose=None,
                              pr=None, dry_run=False, skip_checks=True, force=False)
    rc = agentctl.cmd_publish(args)
    out = capsys.readouterr()

    assert rc == 0, f"publish must succeed on the repair path; got {rc}\n{out.err}"
    assert "VERIFICATION FAILED" not in out.out + out.err
    pinned = [ln.split(": ", 1)[1].strip() for ln in out.out.splitlines()
              if ln.startswith("published-sha:")]
    assert pinned, "publish must print the review pin"
    remote = sp.run(["git", "-C", str(bare), "rev-parse", "feature"],
                    capture_output=True, text=True).stdout.strip()
    assert remote == pinned[0], "origin must hold exactly the SHA publish pinned"
    # And the repair actually reached origin.
    shown = sp.run(["git", "-C", str(bare), "show", f"{remote}:AGENTS.md"],
                   capture_output=True, text=True)
    assert shown.returncode == 0, "AGENTS.md must exist at the pushed tip"


def test_publish_dry_run_leaves_no_repair_commit(agentctl, tmp_path, monkeypatch, capsys):
    """A dry run must not mutate the branch. The first version committed anyway."""
    _, wt = _publishable(tmp_path, monkeypatch, agentctl)
    agentctl.suppress_repo_instructions("demo", wt)
    git = _git_in(wt)
    (wt / "app.py").write_text("code\nwork\n")
    git("commit", "-aqm", "fix: work")
    before = git("rev-parse", "HEAD").stdout.strip()

    args = argparse.Namespace(worktree=str(wt), run=None, repo=None, purpose=None,
                              pr=None, dry_run=True, skip_checks=True, force=False)
    agentctl.cmd_publish(args)
    capsys.readouterr()

    assert git("rev-parse", "HEAD").stdout.strip() == before, "dry run must not commit"


