def test_run_session_honours_the_model_choice_on_an_autonomous_origin_and_records_it(
        agentctl, tmp_path, monkeypatch):
    """The session half: an item's model_choice skips the origin refusal that a
    typed `--model` meets, writes a row naming the item, the writing client and
    the CLAIMED actor, and the run's own record reads `item_override` —
    most-specific-wins even though the surrounding process's env also carries
    CLAUDECODE (issue_01M3NTZP9W8WEYWVERW2F9NARP): a co relaying a work item's
    choice didn't choose it itself."""
    import json
    calls = []
    monkeypatch.setattr(agentctl, "_announce_item_override", lambda **kw: calls.append(kw))
    monkeypatch.setenv("CLAUDECODE", "1")
    choice = {"model": "opus", "reason": "needs depth", "client": "orient",
              "claimed_actor": "operator", "set_at": ""}
    log = _run_override_session(
        agentctl, tmp_path, monkeypatch, model_alias="sonnet", override="opus",
        reason="needs depth", origin="scheduled",
        extra_args={"_item_model_choice": choice, "issue": "issue_X"})
    row = json.loads(log.read_text().splitlines()[0])
    assert row["issue"] == "issue_X" and row["origin"] == "scheduled"
    assert row["channel"] == "work_item:orient"
    assert row["actor"] == "operator (claimed, unverified)"
    meta = json.loads((tmp_path / "run-ovtest" / "meta.json").read_text())
    assert meta["model_choice"] == "item_override"
    assert meta["model_override_channel"] == "work_item:orient"
    assert meta["model_override_actor"] == "operator (claimed, unverified)"
    assert len(calls) == 1 and calls[0]["run_id"] == "run-ovtest"
    assert calls[0]["client"] == "orient"


