# --- a skipped render must never capture the checkout's document set ----------
# Security review, PR #740 round 2: `_materialized_documents(worktree)` used
# to run unconditionally, even for the two dispatch classes above whose render
# is deliberately skipped. For those, `.claude/.profile-documents.json` in the
# checkout — if present at all — was written by something else (usually `bin/co`
# individuating the primary for the operator's own interactive session), and
# that checkout's own agent subprocess can write to the same file for its
# whole execution window. Each test below seeds a PRE-EXISTING, plausibly
# valid `.profile-documents.json` before dispatching, then proves the capture
# never opens it and the run's own record says why.

_PLAUSIBLE_PRIMARY_ROWS = {
    "documents": [{"id": "agent-platform/agents/co-only", "kind": "agent",
                   "body_sha256": "c" * 64}],
}


def _spy_on_materialized_documents(agentctl, monkeypatch):
    """Returns a list that grows by one worktree Path per real call."""
    calls = []
    real = agentctl._materialized_documents
    monkeypatch.setattr(agentctl, "_materialized_documents",
                        lambda wt: calls.append(wt) or real(wt))
    return calls


def _dispatch_to_completion(agentctl, s, monkeypatch, original_create_run_dir):
    """Undo `_detached_main_setup`'s `_StopAfterRender` stub and run the real
    `_spawn_dispatch` to completion via `--dry-run` (no `claude` subprocess
    needed), so meta.json/docs_consulted.json land on disk for real."""
    monkeypatch.setattr(agentctl.T, "create_run_dir", original_create_run_dir)
    s.args.dry_run = True
    return agentctl._spawn_dispatch(s.args)


def test_an_is_local_dispatch_never_captures_the_primarys_document_set(
        agentctl, tmp_path, monkeypatch, runs_root):
    """CFO's cfo-ingest: is_local, no render, stays in the primary. The
    primary already holds a populated `.profile-documents.json` (the
    operator's own interactive render) — the dispatch must record an empty
    `docs` list and why, and must never open that file."""
    original_create_run_dir = agentctl.T.create_run_dir
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="cfo-ingest",
                             resolved={"local": True})
    (s.primary / "cfo.db").write_text("ledger\n")
    (s.primary / ".gitignore").write_text("cfo.db\n")
    (s.primary / ".claude" / ".profile-documents.json").write_text(
        json.dumps(_PLAUSIBLE_PRIMARY_ROWS))
    calls = _spy_on_materialized_documents(agentctl, monkeypatch)

    rc, run_id = _dispatch_to_completion(agentctl, s, monkeypatch, original_create_run_dir)
    assert rc == 0

    rd = agentctl.T.run_dir(run_id)
    docs = json.loads((rd / "docs_consulted.json").read_text())["docs"]
    assert docs == []
    meta = json.loads((rd / "meta.json").read_text())
    assert meta.get("docs_unavailable_reason") == "render skipped for local/private dispatch"
    assert calls == [], "an is_local dispatch must never open .profile-documents.json"


