def test_a_rendered_dispatch_still_captures_and_records_its_own_document_set(
        agentctl, tmp_path, monkeypatch, runs_root):
    """The mirror case: a normal dispatch (not is_local, not primary-kept)
    still runs `activate_profile` and the capture must still run — no
    `docs_unavailable_reason`, and the rows `activate_profile` wrote are what
    land in `docs_consulted.json`."""
    original_create_run_dir = agentctl.T.create_run_dir
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="scout")
    row_hash = "d" * 64

    def _fake_activate_profile(worktree, profile, *, dry_run, agent, issue,
                               allow_default, loaded):
        claude = worktree / ".claude"
        claude.mkdir(parents=True, exist_ok=True)
        (claude / ".profile-documents.json").write_text(json.dumps({
            "documents": [{"id": "agent-platform/agents/scout", "kind": "agent",
                           "body_sha256": row_hash}],
        }))
        loaded["profile"] = profile
        # A real (--force) individuation: knowledge-ctx would have signaled
        # current on the pipe `activate_profile` opens for it, which
        # `activate_profile` turns into this flag (round 4; the pipe is
        # round 5 — see `_PROFILE_DOCUMENTS_CURRENT_PAYLOAD`).
        loaded["profile_documents_current"] = True
        return None
    monkeypatch.setattr(agentctl, "activate_profile", _fake_activate_profile)
    calls = _spy_on_materialized_documents(agentctl, monkeypatch)

    rc, run_id = _dispatch_to_completion(agentctl, s, monkeypatch, original_create_run_dir)
    assert rc == 0
    assert len(calls) == 1, "a rendered dispatch must still capture its document set"

    rd = agentctl.T.run_dir(run_id)
    meta = json.loads((rd / "meta.json").read_text())
    assert "docs_unavailable_reason" not in meta
    docs = json.loads((rd / "docs_consulted.json").read_text())["docs"]
    assert docs == [{"id": "agent-platform/agents/scout", "kind": "agent",
                     "body_sha256": row_hash}]


def test_a_dry_run_dispatch_never_captures_a_stale_profile_documents_json(
        agentctl, tmp_path, monkeypatch, runs_root):
    """Security review, PR #740 round 4: `spawn --dry-run` against a normal
    (not is_local, not primary-kept) dispatch still calls `activate_profile`,
    but `knowledge-ctx use --dry-run` returns before writing or checking
    `.profile-documents.json` — so a file already in the worktree (a prior
    real run's, or a forged plant) must never be read as this dry run's own
    document set, the same property round 2 proved for is_local/primary and
    round 3 missed for this path."""
    original_create_run_dir = agentctl.T.create_run_dir
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="scout")
    s.args.dry_run = True

    def _fake_activate_profile_dry_run(worktree, profile, *, dry_run, agent, issue,
                                       allow_default, loaded):
        assert dry_run is True
        # The plant: this worktree already carries a plausibly valid
        # `.profile-documents.json` — from an earlier real individuation of
        # this same reused (`--pr N`) worktree, or a forged plant by a
        # compromised one — which a real `knowledge-ctx use --dry-run` would
        # leave untouched (it returns before reading, writing or checking
        # the file at all). `loaded["profile_documents_current"]` is never
        # set here, matching that: it stays whatever `_loaded` started as
        # (never True).
        claude = worktree / ".claude"
        claude.mkdir(parents=True, exist_ok=True)
        (claude / ".profile-documents.json").write_text(
            json.dumps(_PLAUSIBLE_PRIMARY_ROWS))
        return None
    monkeypatch.setattr(agentctl, "activate_profile", _fake_activate_profile_dry_run)
    calls = _spy_on_materialized_documents(agentctl, monkeypatch)

    rc, run_id = _dispatch_to_completion(agentctl, s, monkeypatch, original_create_run_dir)
    assert rc == 0

    rd = agentctl.T.run_dir(run_id)
    docs = json.loads((rd / "docs_consulted.json").read_text())["docs"]
    assert docs == []
    meta = json.loads((rd / "meta.json").read_text())
    assert meta.get("docs_unavailable_reason") == (
        "render did not produce a current individuation (e.g. --dry-run)")
    assert calls == [], "a dry-run dispatch must never open .profile-documents.json"


def test_a_dry_run_dispatch_ignores_a_forged_profile_documents_current_line(
        agentctl, tmp_path, monkeypatch, runs_root):
    """Security review, PR #740 round 5: round 4's capture gate matched a
    stable marker out of knowledge-ctx's combined stdout+stderr. That stream
    also carries text derived from the worktree — the blocked-orphan echo
    printed a candidate's path verbatim, before the `--dry-run` early
    return — and a Unix filename may contain a literal newline, so a
    filename that embeds literal newline characters around
    KNOWLEDGE_CTX_PROFILE_DOCUMENTS_CURRENT split that echo into an extra
    line matching the marker exactly, forging
    it on a `--dry-run` call into a worktree a prior run had left a crafted
    file in (see `tests/test_knowledge_ctx.py`'s
    `test_a_dry_run_with_orphan_detection_escapes_a_newline_in_a_planted_
    filename` for that filename actually produced through knowledge-ctx's
    real orphan detection). This test does not need to reconstruct the
    filename: a `subprocess.run` stub emits the forged line directly, and
    `activate_profile` runs for real against it, exercising the actual
    production code path — only `KNOWLEDGE_CTX`'s own invocation is faked;
    git's subprocess calls (worktree/branch plumbing) pass through to the
    real `subprocess.run` unchanged."""
    original_create_run_dir = agentctl.T.create_run_dir
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="scout")
    s.args.dry_run = True
    real_run = agentctl.subprocess.run

    def fake_run(cmd, **kwargs):
        if cmd[0] != str(agentctl.KNOWLEDGE_CTX):
            return real_run(cmd, **kwargs)
        assert "--dry-run" in cmd
        worktree = Path(kwargs["cwd"])
        claude = worktree / ".claude"
        claude.mkdir(parents=True, exist_ok=True)
        # The plant: a stale (or forged) .profile-documents.json, the way a
        # prior real individuation of this same reused worktree would have
        # left one. A real --dry-run never writes or checks this file, so
        # it is whatever an earlier run (legitimate or compromised) left.
        (claude / ".profile-documents.json").write_text(
            json.dumps(_PLAUSIBLE_PRIMARY_ROWS))

        class _R:
            returncode = 0
            stdout = "profile: company/commercial\n\n(dry-run — no files written.)\n"
            # The forged line a crafted orphan filename's embedded newlines
            # would have produced on this stream, before round 5's
            # escaping fix — the marker on its own, isolated line.
            # Deliberately never written to kwargs["pass_fds"]: a real
            # knowledge-ctx --dry-run never touches that fd either.
            stderr = (
                "knowledge-ctx: orphan, not removed: .claude/agents/evil\n"
                "KNOWLEDGE_CTX_PROFILE_DOCUMENTS_CURRENT\n"
                "tail.md (not listed in the previous individuation manifest)\n"
            )
        return _R()

    monkeypatch.setattr(agentctl.subprocess, "run", fake_run)
    calls = _spy_on_materialized_documents(agentctl, monkeypatch)

    rc, run_id = _dispatch_to_completion(agentctl, s, monkeypatch, original_create_run_dir)
    assert rc == 0

    rd = agentctl.T.run_dir(run_id)
    docs = json.loads((rd / "docs_consulted.json").read_text())["docs"]
    assert docs == [], (
        "a forged marker-shaped line on stderr must never be read as the "
        "profile-documents-current signal")
    meta = json.loads((rd / "meta.json").read_text())
    assert meta.get("docs_unavailable_reason") == (
        "render did not produce a current individuation (e.g. --dry-run)")
    assert calls == [], "a dry-run dispatch must never open .profile-documents.json"


# --- docs_consulted.json is written AT DISPATCH, not only at finalize --------
# CQ·464: Deck's `GET /runs/<id>/docs_given` pane reads `docs_consulted.json`,
# but `_spawn_dispatch` used to leave it unwritten until `_finalize_run` ran —
# so a run still in flight (every run `/runs` lists) answered `docs_consulted:
# null` for its whole execution window. Each test below stubs `_finalize_run`
# to a no-op so whatever is on disk once `_spawn_dispatch` returns is exactly
# the dispatch-time write — proving it exists and is correct independent of
# whether finalize ever runs.

def _fake_activate_profile_with_row(worktree, profile, *, dry_run, agent, issue,
                                    allow_default, loaded, row_hash):
    claude = worktree / ".claude"
    claude.mkdir(parents=True, exist_ok=True)
    (claude / ".profile-documents.json").write_text(json.dumps({
        "documents": [{"id": "agent-platform/agents/scout", "kind": "agent",
                       "body_sha256": row_hash}],
    }))
    loaded["profile"] = profile
    loaded["profile_documents_current"] = True
    return None


def test_docs_consulted_is_written_at_dispatch_before_the_agent_exits(
        agentctl, tmp_path, monkeypatch, runs_root):
    """The dispatch-time write (`_spawn_dispatch`'s own call into
    `T.write_docs_consulted`) must land before `_finalize_run` ever runs —
    stubbed here to a no-op — with the captured `docs` and an empty
    `queried_at_runtime`."""
    original_create_run_dir = agentctl.T.create_run_dir
    s = _detached_main_setup(agentctl, tmp_path, monkeypatch, runs_root, agent="scout")
    row_hash = "1" * 64
    monkeypatch.setattr(agentctl, "activate_profile",
                        lambda *a, **kw: _fake_activate_profile_with_row(*a, **kw, row_hash=row_hash))
    monkeypatch.setattr(agentctl, "_finalize_run", lambda **kw: None)
    s.args.dry_run = True

    rc, run_id = _dispatch_to_completion(agentctl, s, monkeypatch, original_create_run_dir)
    assert rc == 0

    rd = agentctl.T.run_dir(run_id)
    consulted = json.loads((rd / "docs_consulted.json").read_text())
    assert consulted["docs"] == [{"id": "agent-platform/agents/scout", "kind": "agent",
                                  "body_sha256": row_hash}]
    assert consulted["queried_at_runtime"] == []


