# --- origin/<name> read through the exact ref -----------------------------------
# A tag or local branch literally named `origin/<name>` is read before the real
# refs/remotes/origin/<name> by any git command given the short name. publish and
# pr-open decide "is this pushed?" and "is this empty?" from those reads.

def _plant_origin_decoys(git, name, sha):
    """A tag AND a local branch, both named `origin/<name>`, at `sha`."""
    assert git("tag", f"origin/{name}", sha).returncode == 0
    assert git("branch", f"origin/{name}", sha).returncode == 0


def test_publish_refuses_an_empty_worktree_despite_a_tag_named_origin_main(
        agentctl, tmp_path, monkeypatch, capsys):
    """origin/main is at B and the branch is at B: nothing beyond base. A tag named
    `origin/main` on B's parent made `rev-list origin/main..HEAD` count 1 and let the
    empty publish through, the exact failure the guard exists to stop."""
    wt = _repo_with_base(tmp_path, "main", commits_beyond_base=1)
    git = _git_in(wt)
    base_b = git("rev-parse", "HEAD").stdout.strip()
    parent_a = git("rev-parse", "HEAD~1").stdout.strip()
    assert git("update-ref", "refs/remotes/origin/main", base_b).returncode == 0
    assert git("checkout", "-q", "-b", "agent/coder-x").returncode == 0
    _plant_origin_decoys(git, "main", parent_a)
    monkeypatch.setattr(agentctl, "_ruff_format_gate", lambda _wt: 0)
    rc = agentctl.cmd_publish(_publish_args(wt))
    err = capsys.readouterr().err
    assert rc == 1
    assert "REFUSED" in err and "NO commits beyond origin/main" in err


def test_publish_pushes_when_a_tag_named_origin_branch_sits_on_head(
        agentctl, tmp_path, monkeypatch, capsys):
    """The tag on HEAD made `rev-parse origin/feature == HEAD`, so publish printed
    "already in sync" and pushed nothing while origin still lacked the commit."""
    import subprocess as sp
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    git = _git_in(wt)
    (wt / "app.py").write_text("code\nunpushed work\n")
    git("commit", "-aqm", "fix: unpushed work")
    head = git("rev-parse", "HEAD").stdout.strip()
    _plant_origin_decoys(git, "feature", head)
    args = argparse.Namespace(worktree=str(wt), run=None, repo=None, purpose=None,
                              pr=None, dry_run=False, skip_checks=True, force=False)
    rc = agentctl.cmd_publish(args)
    out = capsys.readouterr()
    assert rc == 0, out.err
    assert "already in sync" not in out.out
    remote = sp.run(["git", "-C", str(bare), "rev-parse", "feature"],
                    capture_output=True, text=True).stdout.strip()
    assert remote == head


def test_publish_verification_reads_the_exact_ref(agentctl, tmp_path, monkeypatch, capsys):
    """A push that reports success but moves nothing must fail verification. The tag
    named `origin/feature` on HEAD made the short-name read equal HEAD regardless."""
    import subprocess as sp
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    git = _git_in(wt)
    (wt / "app.py").write_text("code\nunpushed work\n")
    git("commit", "-aqm", "fix: unpushed work")
    head = git("rev-parse", "HEAD").stdout.strip()
    _plant_origin_decoys(git, "feature", head)
    real_run = sp.run

    def run(cmd, *a, **kw):
        if isinstance(cmd, list) and cmd[:1] == ["git"] and "push" in cmd:
            return sp.CompletedProcess(cmd, 0, "", "")
        return real_run(cmd, *a, **kw)

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    args = argparse.Namespace(worktree=str(wt), run=None, repo=None, purpose=None,
                              pr=None, dry_run=False, skip_checks=True, force=False)
    rc = agentctl.cmd_publish(args)
    out = capsys.readouterr()
    assert rc == 1
    assert "VERIFICATION FAILED" in out.err
    assert "pushed + verified" not in out.out


def _never_pushed_with_qualified_decoys(tmp_path, monkeypatch, agentctl):
    """A first publish: `feature` has an unpushed commit, origin has no `feature` and
    there is no refs/remotes/origin/feature. With that ref absent, git resolves the
    qualified name through refs/tags/ (then refs/heads/), so a tag and a branch literally
    named `refs/remotes/origin/feature` on HEAD stand in for it."""
    import subprocess as sp
    bare, wt = _publishable(tmp_path, monkeypatch, agentctl)
    git = _git_in(wt)
    (wt / "app.py").write_text("code\nunpushed work\n")
    git("commit", "-aqm", "fix: unpushed work")
    head = git("rev-parse", "HEAD").stdout.strip()
    assert git("update-ref", "-d", "refs/remotes/origin/feature").returncode == 0
    assert sp.run(["git", "-C", str(bare), "branch", "-qD", "feature"]).returncode == 0
    assert git("tag", "refs/remotes/origin/feature", head).returncode == 0
    assert git("branch", "refs/remotes/origin/feature", head).returncode == 0
    assert git("show-ref", "--verify", "-q", "refs/remotes/origin/feature").returncode != 0
    assert git("rev-parse", "refs/remotes/origin/feature").stdout.strip() == head, \
        "the fixture must make the qualified name resolve to HEAD, or it tests nothing"
    return bare, wt, head, git


def test_publish_pushes_a_never_pushed_branch_despite_a_tag_named_like_the_absent_ref(
        agentctl, tmp_path, monkeypatch, capsys):
    """The ordinary first publish. `rev-parse refs/remotes/origin/feature` on the absent
    ref reads the tag `refs/tags/refs/remotes/origin/feature` and printed "already in
    sync" with nothing pushed; only the exact-ref read (git_refs) sees the ref is absent."""
    import subprocess as sp
    bare, wt, head, _ = _never_pushed_with_qualified_decoys(tmp_path, monkeypatch, agentctl)
    args = argparse.Namespace(worktree=str(wt), run=None, repo=None, purpose=None,
                              pr=None, dry_run=False, skip_checks=True, force=False)
    rc = agentctl.cmd_publish(args)
    out = capsys.readouterr()
    assert rc == 0, out.err
    assert "already in sync" not in out.out
    assert "pushed + verified" in out.out
    remote = sp.run(["git", "-C", str(bare), "rev-parse", "feature"],
                    capture_output=True, text=True).stdout.strip()
    assert remote == head


def test_pr_open_refuses_a_never_pushed_branch_despite_a_tag_named_like_the_absent_ref(
        agentctl, tmp_path, monkeypatch, capsys):
    _, wt, _, git = _never_pushed_with_qualified_decoys(tmp_path, monkeypatch, agentctl)
    body = wt / git("rev-parse", "--git-path", "pr-body.md").stdout.strip()
    body.write_text("## What\n\nA change.\n")
    real_run = subprocess.run

    def run(cmd, *a, **kw):
        if isinstance(cmd, list) and cmd[:1] == ["gh"]:
            return subprocess.CompletedProcess(cmd, 1, "", "gh must not be reached")
        return real_run(cmd, *a, **kw)

    monkeypatch.setattr(agentctl.subprocess, "run", run)
    rc = agentctl.main(["pr-open", str(wt), "--title", "feat: a thing"])
    err = capsys.readouterr().err
    assert rc == 1
    assert "pr-open: refused" in err and "(absent)" in err and "!= HEAD" in err


