# --- `agentctl docs merge` (issue_01M3SGQ4QTQ8FB0DN0X9G54ZXP) -----------------
#
# `docs_merge.refusals()` itself is exercised exhaustively in
# tests/test_docs_merge.py; these tests drive `cmd_docs_merge`'s OWN wiring —
# gathering facts from (stubbed) GitHub, git and `_review_status_decision`,
# and handing them to `refusals()` — with every fact-gathering call stubbed so
# no real network or git is reached.

DOCS_HEAD = "a" * 40
DOCS_REPO = "acme/docs-repo"


def _docs_config(**over):
    import docs_merge as DM
    base = dict(repos=(DOCS_REPO,), owner="acme", app_id="555", key_path=None)
    base.update(over)
    return DM.DocsMergeConfig(**base)


def _docs_change(path="docs/a.md", text="one\n"):
    return KM.Change(None, None, None, path, "100644", text)


def _setup_docs(agentctl, monkeypatch, tmp_path, *, head=DOCS_HEAD, review_head=None,
                review_ok=True, review_reasons=(), config=None, config_error=None,
                policy_documents=True, changes=None, pr_state="OPEN", base_ref="main",
                cross_repo=False, merge_pr_result=(True, "merged as " + "f" * 12)):
    """Stub every fact-gathering call `cmd_docs_merge` makes, so it is driven
    purely through `docs_merge`'s public surface — the same contract
    `test_kb_merge.py`'s `_wire` holds for `cmd_kb_merge`. Returns nothing;
    the caller builds `args` and calls `agentctl.cmd_docs_merge` itself, so a
    test can layer its own monkeypatch (e.g. a call-recording `merge_pr`)
    after this one."""
    import docs_merge as DM
    review_head = head if review_head is None else review_head
    changes = [_docs_change()] if changes is None else changes
    config = _docs_config() if (config is None and config_error is None) else config

    def fake_pr_json(pr, fields, repo=None):
        return {"number": 7, "state": pr_state, "headRefOid": head, "baseRefName": base_ref,
               "isCrossRepository": cross_repo}

    def fake_review(pr, repo, required, allow_unverified=False, ignore_ci=False):
        return agentctl.ReviewStatusResult(
            ok=review_ok, head=review_head, reasons=list(review_reasons),
            stamps=[RP.ReviewStamp(version="1", pr="7", repo=DOCS_REPO, reviewed_commit=review_head,
                                   verdict="APPROVE", agent="reviewer", run_id="run-1"),
                   RP.ReviewStamp(version="1", pr="7", repo=DOCS_REPO, reviewed_commit=review_head,
                                 verdict="APPROVE", agent="security-reviewer", run_id="run-2")])

    class _Fetched:
        returncode = 0

    class _Library:
        def fetch_main(self, root):
            return _Fetched()

    def fake_library_git(who, **kw):
        return _Library(), None

    (tmp_path / ".git").mkdir()

    def fake_load_config(path=None):
        if config_error is not None:
            raise DM.Unreadable(config_error)
        return config

    monkeypatch.setattr(agentctl, "_gh_pr_json", fake_pr_json)
    monkeypatch.setattr(agentctl, "_review_status_decision", fake_review)
    monkeypatch.setattr(agentctl, "_kb_library_git", fake_library_git)
    monkeypatch.setattr(DM, "load_config", fake_load_config)
    monkeypatch.setattr(DM, "read_policy", lambda root: _docs_policy(documents=policy_documents))
    monkeypatch.setattr(DM, "repo_root", lambda repo: tmp_path)
    monkeypatch.setattr(DM, "fetch_pr_and_main", lambda root, number: None)
    monkeypatch.setattr(DM, "read_changes", lambda root, number, head: changes)
    monkeypatch.setattr(DM, "drop_pr_ref", lambda root, number: None)
    monkeypatch.setattr(DM, "key_problem", lambda *a, **k: None)
    monkeypatch.setattr(DM, "app_jwt", lambda *a, **k: "jwt.x.y")
    monkeypatch.setattr(DM, "installation_for", lambda jwt, cfg=None, **k: "inst-1")
    monkeypatch.setattr(DM, "merge_token", lambda jwt, inst, repo, **k: "ghs_scoped")
    monkeypatch.setattr(DM, "merge_pr", lambda number, sha, token, repo, **k: merge_pr_result)


def _docs_policy(documents=True, rounds=5):
    return AP.load(
        f"policy: platform/agent-policy\nschema_version: 1\n"
        f"agents_may_merge_knowledge: false\n"
        f"agents_may_merge_knowledge_instructions: false\n"
        f"agents_may_merge_documents: {str(documents).lower()}\n"
        f"review_rounds_per_role: {rounds}\nmax_concurrent: 16\n"
        f"max_workers_per_team: 4\nmax_live_supervisors: 4\n")


