def test_eval_mode_repoints_tmpdir_at_the_dispatchs_own_scratch_directory(
        agentctl, tmp_path, monkeypatch):
    """Round 8's `allowWrite` no longer covers the shared temp root for an eval
    dispatch (`run_sandbox.settings`'s `eval_scratch_dir` parameter) — so a tool that
    writes wherever `TMPDIR` names (a bare `mkstemp` call, a build tool's own scratch
    file) would hit a path the sandbox now refuses unless `TMPDIR` itself is repointed
    at the dispatch's own directory. Reviewer finding, round 8 revise: this repoint
    (bin/agentctl's `_spawn_claude`) shipped with no test. Fails before that repoint
    existed, where `TMPDIR` is left at whatever the dispatching shell's own ambient
    value was."""
    monkeypatch.setattr(agentctl, "_review_launch_path", lambda: None)
    monkeypatch.setenv("TMPDIR", "/some/ambient/tmpdir/the/repoint/must/override")

    captured = _run_eval_session_capturing_popen(agentctl, tmp_path, monkeypatch)

    assert captured.env.get("TMPDIR") == str(captured.scratch_dir)


def _write_scratch(agentctl, tmp_path, run_id, content):
    """Creates a per-run scratch DIRECTORY under `tmp_path` — standing in for
    `RS.create_eval_scratch_dir`'s return value for this run — and writes
    `content` to its verdict file (`RS.EVAL_VERDICT_FILENAME`, round 8): a
    string, written verbatim, the caller decides whether it's valid JSON.
    `content=None` leaves the directory with no verdict file at all, for the
    missing-file case. Returns the DIRECTORY, not the file:
    `_collect_eval_verdict`'s signature takes the directory directly, and the
    post-exit cleanup test needs the directory's own existence to assert
    against."""
    scratch_dir = tmp_path / f"{run_id}-scratch-dir"
    scratch_dir.mkdir(exist_ok=True)
    if content is not None:
        (scratch_dir / agentctl.RS.EVAL_VERDICT_FILENAME).write_text(content)
    return scratch_dir


_VALID_EVAL_REVIEW = '{"verdict": "APPROVE", "body": "looks fine"}'


def test_collect_eval_verdict_is_none_when_the_scratch_file_is_missing(
        agentctl, tmp_path):
    """A replay that never wrote (died before finishing, or Write wasn't in
    its tool surface) records no verdict — never a pass."""
    scratch_dir = _write_scratch(agentctl, tmp_path, "run-x", None)
    assert agentctl._collect_eval_verdict(
        scratch_dir, run_id="run-x", repo="agent-platform", review_sha="f" * 40,
        agent_name="reviewer", pr=None) is None


