# ---------------------------------------------------------------------------
# CQ-331 round 6. The operator ruled on 2026-10-06 that agents halt during a Keel
# outage: a dispatch whose tool policy the Library does not answer does not run.
# These pin that refusal, and pin that a live answer applies what it always did.
# ---------------------------------------------------------------------------

# A live answer that no deleted path could produce: an operator denial, an explicit
# allow that exempts one categorical target, and a connector server that is in
# neither the floor nor any cache.
_ROUND6_LIVE_RECORD = {
    "agent": "coder", "crew": "bosun", "model": "claude-opus-5-5",
    "explicit": {"Grep": "deny", "WebFetch": "allow"},
    "exfiltration_builtins": ["DesignSync", "WebFetch"],
    "connector_servers": ["claude_ai_Fixture"],
    "default": "allow", "version": 11,
}
_ROUND6_LIVE_DENIALS = ["DesignSync", "Grep", "mcp__claude_ai_Fixture__*"]


class _Opener:
    """Stands in for `issue_client.pinned_opener()`, which the policy fetch reads through."""

    def __init__(self, fn):
        self._fn = fn

    def open(self, req, timeout=None):
        return self._fn(req, timeout=timeout)


def _round6_policy_fetch_raises(monkeypatch, exc):
    """The real `policy_client.resolve` runs, and its urlopen raises `exc`, so the
    mapping from a transport failure to a refusal is what is under test."""
    import policy_client
    monkeypatch.setattr(policy_client, "token", lambda: "test-token")
    monkeypatch.setattr(policy_client, "resolve", _REAL_RESOLVE)

    def _raise(req, timeout=None):
        raise exc
    monkeypatch.setattr(policy_client.IC, "pinned_opener", lambda: _Opener(_raise))


def test_a_policy_fetch_that_times_out_refuses_the_dispatch(agentctl, monkeypatch):
    """A timed-out policy read is a refusal, not the floor. The message names the
    timeout and says nothing was dispatched."""
    _round6_policy_fetch_raises(monkeypatch, TimeoutError("timed out"))
    agentctl._LIBRARY_DENIALS_MEMO.clear()
    with pytest.raises(SystemExit) as exc:
        agentctl._library_denials("coder", "agent-platform", "claude-opus-5-5")
    msg = str(exc.value)
    assert "timed out after" in msg
    assert "GET /policy/resolve" in msg
    assert "Nothing was dispatched" in msg


def test_a_policy_fetch_refused_at_the_connection_refuses_the_dispatch(agentctl, monkeypatch):
    import urllib.error
    _round6_policy_fetch_raises(
        monkeypatch, urllib.error.URLError(ConnectionRefusedError(111, "Connection refused")))
    agentctl._LIBRARY_DENIALS_MEMO.clear()
    with pytest.raises(SystemExit) as exc:
        agentctl._library_denials("coder", "agent-platform", "claude-opus-5-5")
    assert "connection failed: [Errno 111] Connection refused" in str(exc.value)
    assert "Nothing was dispatched" in str(exc.value)


@pytest.mark.parametrize("body", _MALFORMED_LIVE_BODIES)
def test_a_malformed_policy_answer_refuses_the_dispatch(agentctl, monkeypatch, body):
    """A 200 that is not a usable record is no answer, so the dispatch is refused.
    It is not served the floor, and nothing is dispatched."""
    import policy_client
    monkeypatch.setattr(policy_client, "token", lambda: "t")
    monkeypatch.setattr(policy_client, "resolve", _REAL_RESOLVE)

    class _Body:
        def read(self):
            return body
        def __enter__(self):
            return self
        def __exit__(self, *exc):
            return False
    monkeypatch.setattr(policy_client.IC, "pinned_opener",
                        lambda: _Opener(lambda req, timeout=None: _Body()))
    agentctl._LIBRARY_DENIALS_MEMO.clear()
    with pytest.raises(SystemExit, match="bad response"):
        agentctl._library_denials("coder", "agent-platform", "claude-opus-5-5")


def test_a_dispatch_with_no_control_plane_token_is_refused(agentctl, monkeypatch):
    """No token means the policy call is never made. The dispatch is refused, not run on
    the Library's last answer or on nothing."""
    import policy_client
    monkeypatch.setattr(policy_client, "token", lambda: None)
    monkeypatch.setattr(policy_client, "resolve", _REAL_RESOLVE)
    agentctl._LIBRARY_DENIALS_MEMO.clear()
    with pytest.raises(SystemExit, match="no control-plane token was available"):
        agentctl._library_denials("coder", "agent-platform", "claude-opus-5-5")


def test_a_crew_less_dispatch_the_library_refuses_is_refused(agentctl, monkeypatch):
    """A repo with no registered crew sends no crew, and the Library answers 400. The triple
    has no record, so the dispatch is refused. It used to run on the floor."""
    import urllib.error
    _round6_policy_fetch_raises(
        monkeypatch, urllib.error.HTTPError("u", 400, "crew is required", {}, None))
    agentctl._LIBRARY_DENIALS_MEMO.clear()
