def test_a_dispatch_the_library_cannot_answer_starts_no_agent(agentctl, monkeypatch):
    """The refusal reaches the caller before the run directory exists and before the
    detached grandchild is forked, so no agent process is started and the caller sees
    the refusal rather than a run id."""
    monkeypatch.setattr(agentctl, "_warn_deployed_tree", lambda: None)
    monkeypatch.setattr(agentctl, "_spawn_lib_gate", lambda: None)
    monkeypatch.setattr(agentctl, "resolve_agent", lambda *a, **k: {
        "id": "x", "name": "reviewer", "body": "sys", "model_alias": "opus",
        "frontmatter": {"model": "opus"}, "source": None, "local": False, "tools": []})
    monkeypatch.setattr(agentctl.R, "can_spawn", lambda *a, **k: (True, [], ""))

    def _must_not_run(*a, **k):
        raise AssertionError("a run was started before the policy was read")
    monkeypatch.setattr(agentctl.T, "create_run_dir", _must_not_run)
    monkeypatch.setattr(agentctl, "_detach_and_run", _must_not_run)
    _round6_policy_fetch_raises(monkeypatch, TimeoutError("timed out"))
    agentctl._LIBRARY_DENIALS_MEMO.clear()
    args = _cmd_spawn_args(model=None, reason=None)
    args.dry_run = False
